const $ = (selector) => document.querySelector(selector);
const $$ = (selector) => [...document.querySelectorAll(selector)];

// V6.1.2 — estabilidade de viewport do editor.
// Autosave, rerender e reload da prévia não podem deslocar a coluna de edição.
try { if ('scrollRestoration' in history) history.scrollRestoration = 'manual'; } catch (_) {}
function editorScroller() { return document.querySelector('main'); }
function captureEditorViewport() {
  const node = editorScroller();
  return node ? { top: node.scrollTop, left: node.scrollLeft } : { top: 0, left: 0 };
}
function restoreEditorViewport(pos) {
  const node = editorScroller();
  if (!node || !pos) return;
  node.scrollTop = pos.top;
  node.scrollLeft = pos.left;
}
function keepEditorViewportStable(pos) {
  restoreEditorViewport(pos);
  requestAnimationFrame(() => restoreEditorViewport(pos));
  setTimeout(() => restoreEditorViewport(pos), 0);
}
let PREVIEW_RESTORE_STATE = null;
let PREVIEW_REFRESH_TIMER = 0;
let PREVIEW_PATCH_TIMER = 0;
let PREVIEW_READY = false;
let PREVIEW_LAST_STRUCTURAL_SIGNATURE = '';
let PREVIEW_RELOAD_IN_FLIGHT = false;
let PREVIEW_RELOAD_CONTEXT = null;
let PREVIEW_LAST_COMPLETED_RELOAD_KEY = '';
let PREVIEW_LAST_SENT_PATCH_KEY = '';
const PREVIEW_METRICS = {
  patches:0, reloads:0, reloadsBlocked:0, duplicatePatchesBlocked:0, ready:0,
  failed:0, lastMode:'', lastReason:'', lastAppliedRevision:'', lastLoadedRevision:'',
  cloudApplies:0, cloudNoops:0,
};

function capturePreviewViewport() {
  const frame = $('#previewFrame');
  try {
    const win = frame?.contentWindow;
    const doc = frame?.contentDocument;
    const detail = doc?.querySelector('#projectDetail');
    return {
      top: Number(win?.scrollY || 0), left: Number(win?.scrollX || 0), hash: String(win?.location?.hash || ''),
      project_id: String(detail?.dataset?.projectId || ''), project_scroll_top: Number(detail?.scrollTop || 0),
    };
  } catch (_) { return PREVIEW_RESTORE_STATE || { top:0, left:0, hash:'', project_id:'', project_scroll_top:0 }; }
}
function restorePreviewViewport(state = PREVIEW_RESTORE_STATE) {
  const frame = $('#previewFrame');
  if (!frame?.contentWindow || !state) return;
  try { frame.contentWindow.postMessage({ type:'studioframe-restore-preview', state }, location.origin); } catch (_) {}
}
function previewRevisionToken() { return `draft:${Number(STATE?.editGeneration || 0)}:${String(STATE?.modified || STATE?.savedRevision || '').slice(0,12)}`; }
function previewCustomRoute(){
  const pages=STATE.settings?.site_builder?.custom_pages||{};
  const id=String(STATE.previewCustomPageId||'');
  if(!id||!pages[id])return '';
  try{return customPageFullPath(id)||'';}catch(_){return String(pages[id]?.slug||'');}
}
function previewContextKey(){
  if(STATE.previewPage==='briefing')return 'briefing';
  if(STATE.previewPage==='services')return 'services';
  const project=String(STATE.previewProjectId||'');
  if(project)return `project:${project}`;
  const route=previewCustomRoute();
  if(route)return `custom:${route}`;
  const section=String(STATE.previewSectionId||'');
  return section?`section:${section}`:'home';
}
function previewUrlQuery(){
  if(STATE.previewPage==='briefing'){const b=STATE.settings?.site_builder?.briefing||{};return `&sf_route=${encodeURIComponent(b.full_path||b.slug||'briefing')}`;}
  if(STATE.previewPage==='services')return '&page=services';
  const project=String(STATE.previewProjectId||'');
  if(project)return `&sf_project=${encodeURIComponent(project)}`;
  const route=previewCustomRoute();
  return route?`&sf_route=${encodeURIComponent(route)}`:'';
}
function previewDesiredHash(){
  if(STATE.previewProjectId)return '';
  const section=String(STATE.previewSectionId||'');
  if(section)return `#section=${encodeURIComponent(section)}`;
  if(STATE.previewPage==='services'||STATE.previewPage==='briefing'||previewCustomRoute())return '';
  return String(PREVIEW_RESTORE_STATE?.hash||'');
}
function cloneForPreview(value) { try { return structuredClone(value); } catch (_) { return JSON.parse(JSON.stringify(value ?? null)); } }
function previewStructuralSignature() {
  const settings = STATE.settings || {}, builder = settings.site_builder || {}, pages = builder.custom_pages || {}, sectionPages = builder.section_pages || {}, services = builder.services || {};
  const shape = {
    preview_page: previewContextKey(),
    home: (builder.home?.blocks || []).map((b)=>[b?.id||'',b?.type||'',b?.visible!==false]),
    custom_pages: Object.values(pages).filter(Boolean).map((p)=>[p.id||'',p.slug||'',p.parent_id||'',p.visible!==false,p.show_in_menu!==false,(p.sections||[]).map((b)=>[b?.id||'',b?.type||'',b?.visible!==false])]),
    section_pages: Object.entries(sectionPages).map(([id,p])=>[id,(p?.blocks||[]).map((b)=>[b?.id||'',b?.type||'',b?.visible!==false])]),
    services: [services.slug||'servicos',services.visible!==false,(services.categories||[]).map((c)=>[c?.id||'',c?.visible!==false,Number(c?.order||0),(c?.services||[]).map((i)=>[i?.id||'',i?.slug||'',i?.visible!==false,i?.page_enabled!==false,Number(i?.order||0)])])],
    editorial_catalog_projection: {folders:settings.folders||{},projects:settings.projects||{},project_sections:settings.project_sections||{},collections:settings.collections||{}},
  };
  return JSON.stringify(shape);
}
function previewSnapshot(reason='editor') {
  return { type:'studioframe-preview-patch', revision:previewRevisionToken(), saved_revision:STATE.savedRevision||STATE.modified||'', reason,
    identity:cloneForPreview(STATE.settings?.identity||{}), site_builder:cloneForPreview(STATE.settings?.site_builder||{}) };
}
function previewReloadKey(revisionToken=previewRevisionToken(), structuralSignature=previewStructuralSignature()) {
  return `${String(revisionToken||'')}|${previewContextKey()}|${String(structuralSignature||'')}`;
}
function updatePreviewMetricsLabel() {
  const status=$('#previewStatus'); if(!status)return;
  status.dataset.previewRevision=STATE.previewRevision||'';
  status.dataset.previewPatches=String(PREVIEW_METRICS.patches);
  status.dataset.previewReloads=String(PREVIEW_METRICS.reloads);
  status.dataset.previewReloadsBlocked=String(PREVIEW_METRICS.reloadsBlocked);
  status.title=`Prévia · ${PREVIEW_METRICS.patches} patch(es) · ${PREVIEW_METRICS.reloads} reload(s) · ${PREVIEW_METRICS.reloadsBlocked} bloqueado(s)${STATE.previewRevision?` · ${STATE.previewRevision}`:''}`;
}
function postPreviewPatch(reason='editor') {
  if(previewRuntimeMode()==='artifact')return true;
  const frame=$('#previewFrame'); if(!frame?.contentWindow || !PREVIEW_READY)return false;
  const snapshot=previewSnapshot(reason);
  const key=`${snapshot.revision}|${previewStructuralSignature()}`;
  if (STATE.previewRevision===snapshot.revision || PREVIEW_LAST_SENT_PATCH_KEY===key) {
    PREVIEW_METRICS.duplicatePatchesBlocked+=1; PREVIEW_METRICS.lastMode='patch-noop'; PREVIEW_METRICS.lastReason=reason; updatePreviewMetricsLabel(); return true;
  }
  try {
    PREVIEW_LAST_SENT_PATCH_KEY=key;
    frame.contentWindow.postMessage(snapshot,location.origin);
    PREVIEW_METRICS.patches+=1; PREVIEW_METRICS.lastMode='patch'; PREVIEW_METRICS.lastReason=reason; updatePreviewMetricsLabel(); return true;
  }
  catch(error){ PREVIEW_LAST_SENT_PATCH_KEY=''; PREVIEW_METRICS.failed+=1; console.warn('Preview patch falhou; reload controlado será usado.',error); return false; }
}
function previewRuntimeMode(){
  const proof=STATE.previewBuildParity||{};
  return (!STATE.dirty&&proof.parity===true&&proof.preview_artifact_hosted===true)?'artifact':'draft';
}
function previewLoadToken(){
  if(previewRuntimeMode()==='artifact')return `artifact:${String(STATE.previewBuildParity?.artifact_id||STATE.buildArtifactId||STATE.buildRevision||'unknown')}`;
  return previewRevisionToken();
}
function previewFrameBaseUrl(){return previewRuntimeMode()==='artifact'?'/site/':'/preview';}
function reloadPreviewControlled(reason='structural') {
  const revisionToken=previewLoadToken();
  const structuralSignature=previewStructuralSignature();
  const key=previewReloadKey(revisionToken,structuralSignature);
  if ((PREVIEW_RELOAD_IN_FLIGHT && PREVIEW_RELOAD_CONTEXT?.key===key) || (PREVIEW_READY && PREVIEW_LAST_COMPLETED_RELOAD_KEY===key)) {
    PREVIEW_METRICS.reloadsBlocked+=1; PREVIEW_METRICS.lastMode='reload-blocked'; PREVIEW_METRICS.lastReason=reason; updatePreviewMetricsLabel();
    console.info('Preview reload ignorado: revisão/estrutura já carregada.',{reason,key});
    return false;
  }
  const editorViewport=captureEditorViewport(); PREVIEW_RESTORE_STATE=capturePreviewViewport(); PREVIEW_READY=false;
  PREVIEW_RELOAD_IN_FLIGHT=true;
  PREVIEW_RELOAD_CONTEXT={ key, revisionToken, structuralSignature, editGeneration:Number(STATE.editGeneration||0), reason, mode:previewRuntimeMode() };
  PREVIEW_LAST_SENT_PATCH_KEY='';
  clearTimeout(PREVIEW_PATCH_TIMER); clearTimeout(PREVIEW_REFRESH_TIMER);
  PREVIEW_REFRESH_TIMER=setTimeout(()=>{
    const frame=$('#previewFrame'), pageQuery=previewUrlQuery(), desiredHash=previewDesiredHash();
    if(frame){const base=previewFrameBaseUrl();const join=base.includes('?')?'&':'?';frame.src=`${base}${join}refresh=${Date.now()}${pageQuery}${desiredHash}`;frame.dataset.previewMode=previewRuntimeMode();}
    PREVIEW_METRICS.reloads+=1; PREVIEW_METRICS.lastMode='reload'; PREVIEW_METRICS.lastReason=reason; updatePreviewMetricsLabel(); keepEditorViewportStable(editorViewport);
  },80);
  keepEditorViewportStable(editorViewport);
  return true;
}
addEventListener('message',(event)=>{
  const frame=$('#previewFrame'); if(event.origin!==location.origin || event.source!==frame?.contentWindow)return;
  if(event.data?.type==='studioframe-preview-ready'){
    PREVIEW_READY=true; PREVIEW_RELOAD_IN_FLIGHT=false; PREVIEW_METRICS.ready+=1;
    PREVIEW_METRICS.lastLoadedRevision=String(event.data.revision||'');
    const context=PREVIEW_RELOAD_CONTEXT;
    if(context){PREVIEW_LAST_COMPLETED_RELOAD_KEY=context.key;PREVIEW_LAST_STRUCTURAL_SIGNATURE=context.structuralSignature;}
    else PREVIEW_LAST_STRUCTURAL_SIGNATURE=previewStructuralSignature();
    restorePreviewViewport(); setTimeout(()=>restorePreviewViewport(),180); updatePreviewMetricsLabel();
    // /preview is rendered from the last persisted editorial state. Structural
    // editor changes can therefore finish reloading with an older snapshot.
    // Reconcile the current draft after the shell is ready; the public runtime
    // performs a full in-place composition render when the topology changed.
    if(context){
      const currentSignature=previewStructuralSignature();
      const editedDuringReload=Number(STATE.editGeneration||0)!==Number(context.editGeneration||0);
      const loadedRevision=String(event.data.revision||'');
      const draftNotLoaded=loadedRevision!==String(context.revisionToken||'');
      PREVIEW_RELOAD_CONTEXT=null;
      if(context.mode==='artifact'){STATE.previewMode='artifact';renderPreviewBuildParity();}
      else if(editedDuringReload){
        if(currentSignature!==context.structuralSignature) reloadPreviewControlled('edit-during-preview-reload');
        else setTimeout(()=>postPreviewPatch('edit-during-preview-reload'),0);
      }
      else if(draftNotLoaded) setTimeout(()=>postPreviewPatch('draft-after-preview-reload'),0);
    }
  }
  if(event.data?.type==='studioframe-preview-applied'){
    STATE.previewRevision=String(event.data.revision||''); PREVIEW_METRICS.lastAppliedRevision=STATE.previewRevision;
    PREVIEW_LAST_SENT_PATCH_KEY=''; updatePreviewMetricsLabel();
  }
  if(event.data?.type==='studioframe-preview-reload-required'){
    PREVIEW_METRICS.failed+=1;
    reloadPreviewControlled(event.data.reason||'preview-requested-reload');
  }
});
let TOKEN = '';
let TOKEN_PROMISE = null;

async function refreshLocalToken() {
  const response = await fetch('/api/session', { cache: 'no-store' });
  const payload = await response.json();
  if (!response.ok || !payload.ok || !payload.token) {
    throw new Error(payload.message || `Falha ao obter sessão local (HTTP ${response.status})`);
  }
  TOKEN = payload.token;
  return TOKEN;
}

async function localToken(force = false) {
  if (force) TOKEN = '';
  if (TOKEN) return TOKEN;
  if (!TOKEN_PROMISE) {
    TOKEN_PROMISE = refreshLocalToken().finally(() => { TOKEN_PROMISE = null; });
  }
  return TOKEN_PROMISE;
}
