window.addEventListener('error', (event) => {
  console.error('StudioFrame frontend error:', event.error || event.message);
  const output = $('#diagnosticOutput');
  if (output) output.textContent = `FRONTEND ERROR\n${event.message || event.error || 'Erro JavaScript desconhecido'}`;
});
