function renderPersistenceFeedback() {
  const saveBadge = $('#saveStateBadge');
  const saveText = $('#saveStateText');
  const editCard = $('#editorialPersistenceCard');
  const editHeadline = $('#editorialPersistenceHeadline');
  const editDetail = $('#editorialPersistenceDetail');
  let saveKind = 'checking'; let headline = 'Verificando…'; let detail = 'Aguardando o estado editorial.';
  if (STATE.saving) {
    saveKind = 'saving'; headline = 'Salvando…'; detail = 'Gravando o estado editorial. Não feche esta janela até a confirmação.';
  } else if (STATE.dirty) {
    saveKind = 'pending'; headline = 'Alterações pendentes'; detail = 'Há mudanças ainda não confirmadas. O autosave será executado ou você pode clicar Salvar.';
  } else if (STATE.cloudSaved) {
    saveKind = 'cloud'; headline = 'Salvo na nuvem';
    const backend = 'GitHub';
    const revision = STATE.remoteBackend === 'github' && STATE.cloudCommit ? ` · commit ${STATE.cloudCommit.slice(0, 10)}` : '';
    const savedRevision = String(STATE.savedRevision || STATE.modified || '');
    detail = `Seguro para continuar em outro computador · ${backend}${revision}${savedRevision ? ` · revisão ${savedRevision.slice(0, 12)}` : ''}${STATE.lastSavedAt ? ` · ${shortTime(STATE.lastSavedAt)}` : ''}.`;
  } else if (STATE.localSaved) {
    saveKind = 'pending'; headline = 'Aguardando nuvem';
    const portable = STATE.portableSaved ? ' · cache portátil disponível' : '';
    detail = `A edição está preservada apenas como cache local${portable}. Ela só conta como SALVA quando o GitHub confirmar a mesma revisão.${STATE.remoteError ? ` GitHub: ${STATE.remoteError}` : ''}`;
  } else if (STATE.settings) {
    saveKind = 'pending'; headline = 'Ainda não salvo';
    detail = 'O editor está aberto, mas ainda não houve uma confirmação de gravação nesta sessão.';
  }
  if (saveBadge) saveBadge.className = `state-badge ${saveKind}`;
  if (saveText) saveText.textContent = headline;
  if (editCard) editCard.className = `persistence-card ${saveKind}`;
  if (editHeadline) editHeadline.textContent = headline;
  if (editDetail) editDetail.textContent = detail;

  const deploy = STATE.deployment || {};
  const publishBadge = $('#publishStateBadge'); const publishText = $('#publishStateText');
  const deployCard = $('#deploymentPersistenceCard'); const deployHeadline = $('#deploymentPersistenceHeadline'); const deployDetail = $('#deploymentPersistenceDetail');
  let publishKind = 'neutral'; let publishHeadline = 'Ainda não confirmada'; let publishDetail = 'Salvar a edição e publicar o site são ações separadas.';
  if (deploy.status === 'error') {
    publishKind = 'error'; publishHeadline = 'Falha na publicação'; publishDetail = deploy.failure_stage ? `Falha em: ${deploy.failure_stage}. Consulte o diagnóstico detalhado abaixo.` : 'A publicação não foi concluída. Consulte o diagnóstico por etapa.';
  } else if (deploy.conclusion === 'stale') {
    publishKind = 'pending'; publishHeadline = 'Domínio ainda em revisão anterior'; publishDetail = `O GitHub recebeu a atualização, mas o domínio ainda não confirmou ${String(deploy.requested_revision || STATE.publishedRevision || '').slice(0, 12) || 'a revisão solicitada'}. Aguarde a propagação; nenhuma edição foi perdida.`;
  } else if (deploy.status === 'saving' || deploy.status === 'publishing') {
    publishKind = 'deploying'; publishHeadline = 'Publicando…'; publishDetail = `Congelando e enviando exatamente a revisão ${String(deploy.requested_revision || '').slice(0, 12) || 'confirmada na nuvem'} para a branch pública.`;
  } else if (deploy.conclusion === 'success') {
    const publishedRevision = String(deploy.published_revision || STATE.publishedRevision || '');
    publishKind = 'published'; publishHeadline = 'Site publicado'; publishDetail = `Build confirmado${publishedRevision ? ` · revisão ${publishedRevision.slice(0, 12)}` : ''}${STATE.publishCommit ? ` · commit ${STATE.publishCommit.slice(0, 10)}` : ''}.`;
  } else if (['queued','in_progress','requested','waiting','pending'].includes(deploy.status)) {
    publishKind = 'deploying'; publishHeadline = 'Deploy em andamento'; publishDetail = `Build da revisão ${String(deploy.requested_revision || STATE.buildRevision || '').slice(0, 12) || 'solicitada'} já foi enviado ao GitHub${STATE.publishCommit ? ` · commit ${STATE.publishCommit.slice(0, 10)}` : ''}. O domínio público ainda está atualizando.`;
  } else if (STATE.publishCommit) {
    publishKind = 'deploying'; publishHeadline = 'Enviado ao GitHub'; publishDetail = `Commit ${STATE.publishCommit.slice(0, 10)} criado. Atualize o status para confirmar a conclusão do Pages.`;
  }
  if (publishBadge) publishBadge.className = `state-badge ${publishKind}`;
  if (publishText) publishText.textContent = publishHeadline;
  if (deployCard) deployCard.className = `persistence-card ${publishKind}`;
  if (deployHeadline) deployHeadline.textContent = publishHeadline;
  if (deployDetail) deployDetail.textContent = publishDetail;
  renderPublicationStateMachine();
  renderPreviewBuildParity();
  renderEditorDataDock();
}

function renderSelectionCloudFeedback() {
  const cloudOk=STATE.cloudSaved&&!STATE.dirty&&!STATE.saving;
  const status=STATE.saving?'SALVANDO NA NUVEM…':(STATE.dirty?'ALTERAÇÃO AINDA NÃO CONFIRMADA':(cloudOk?`SALVO NA NUVEM · ${String(STATE.savedRevision||STATE.modified||'').slice(0,10)}`:'AGUARDANDO CONFIRMAÇÃO DA NUVEM'));
  document.querySelectorAll('.selection-cloud-state').forEach((node)=>{
    node.textContent=status;
    node.classList.toggle('ok',cloudOk);
    node.classList.toggle('pending',!cloudOk);
  });
}
let EDITOR_CONFIRMED_FINGERPRINT = '';
let EDITOR_LAST_OBSERVED_FINGERPRINT = '';
