  STATE.cloudSaved = Boolean(payload.cloud_saved ?? STATE.cloudSaved);
  STATE.cloudSha = payload.cloud_sha || STATE.cloudSha || '';
  STATE.cloudCommit = payload.cloud_commit || STATE.cloudCommit || '';
  STATE.remoteBackend = payload.remote_backend || STATE.remoteBackend || '';
  STATE.remoteError = payload.remote_error || '';
  STATE.localSaved = Boolean(payload.local_saved ?? STATE.localSaved);
  STATE.localPath = payload.local_path || STATE.localPath || '';
  STATE.portableSaved = Boolean(payload.portable_saved ?? STATE.portableSaved);
  STATE.portablePath = payload.portable_path || STATE.portablePath || '';
