function queueCloudConfirmation(generation, notify = false) {
  cloudStatusTarget = Math.max(cloudStatusTarget, Number(generation || 0));
  cloudStatusNotify = cloudStatusNotify || notify;
  clearTimeout(cloudStatusTimer);
  cloudStatusTimer = setTimeout(pollCloudConfirmation, 650);
}

async function pollCloudConfirmation() {
  try {
    const payload = await api('/api/cloud/status');
    const result = payload.last_result || {};
    const confirmed = Number(payload.synced_generation || 0) >= cloudStatusTarget && Boolean(result.cloud_saved);
    if (confirmed) {
      STATE.cloudSha = result.cloud_sha || STATE.cloudSha || '';
      STATE.cloudCommit = result.cloud_commit || STATE.cloudCommit || '';
      STATE.remoteBackend = 'github';
      STATE.remoteError = '';
      STATE.cloudGeneration = Number(payload.synced_generation || 0);
      // The request may have confirmed an older generation while the user has
      // already edited again. Never paint that newer local state as cloud-safe.
      const currentStateConfirmed = !STATE.dirty && !STATE.saving;
      STATE.cloudSaved = currentStateConfirmed;
      STATE.selectionSaveStatus = currentStateConfirmed ? 'cloud-confirmed' : 'pending-cloud';
      renderPersistenceFeedback();
      renderSelectionCloudFeedback();
      const detail = $('#githubCloudDetail');
      if (detail) detail.textContent = currentStateConfirmed
        ? `Última edição confirmada no GitHub · commit ${STATE.cloudCommit ? STATE.cloudCommit.slice(0, 10) : '—'}`
        : `Revisão anterior confirmada · há uma alteração local mais nova aguardando Save.`;
      if (cloudStatusNotify && currentStateConfirmed) toast('Última edição confirmada na nuvem');
      cloudStatusNotify = false;
      return;
    }
    if (!payload.syncing && !payload.pending && result.remote_error) {
      STATE.remoteError = result.remote_error;
      renderPersistenceFeedback();
      return;
    }
    cloudStatusTimer = setTimeout(pollCloudConfirmation, 900);
  } catch (_) {
    cloudStatusTimer = setTimeout(pollCloudConfirmation, 1400);
  }
}

function toast(message) {
  const node = $('#toast');
  node.textContent = message;
  node.classList.add('show');
  clearTimeout(node.timer);
  node.timer = setTimeout(() => node.classList.remove('show'), 3600);
}

function formatPublicationStages(stages = []) {
  if (!Array.isArray(stages) || !stages.length) return [];
  return stages.map((stage) => {
    const icon = stage.status === 'ok' ? '✓' : (stage.status === 'failed' ? '✗' : (stage.status === 'running' ? '…' : '•'));
    const line = `${icon} ${stage.label || stage.key || 'Etapa'}${stage.message ? ` — ${stage.message}` : ''}`;
    return line;
  });
}

function formatPublicationFailureDetails(payload = {}) {
  const rows = [];
  const stages = Array.isArray(payload?.stages) ? payload.stages : [];
  const failed = stages.find((stage) => stage?.status === 'failed') || {};
  const access = failed.drive_public_access || payload?.build?.drive_public_access || payload?.validation?.drive_public_access || {};
  const media = failed.media_validation || payload?.build?.validation || payload?.validation || {};
  if (failed.code) rows.push(`Código: ${failed.code}`);
  if (access && Object.keys(access).length) {
    rows.push(`Drive público: ${access.ok ? 'PASS' : 'FAIL'}${access.code ? ` · ${access.code}` : ''}`);
    if (access.message && !access.ok) rows.push(`Drive: ${access.message}`);
  }
  if (media && Object.keys(media).length) {
    const checked = Number(media.checked || 0), valid = Number(media.valid || 0), invalid = Number(media.invalid || 0);
    if (checked || invalid) rows.push(`Mídias: ${valid}/${checked} válidas${invalid ? ` · ${invalid} falha(s)` : ''}`);
    (media.failures || []).slice(0, 6).forEach((item) => rows.push(`• ${item.name || item.file_id || 'Mídia'}: ${item.reason || item.message || 'indisponível'}`));
  }
  return rows;
}

function renderPublicationStages(stages = [], open = false) {
  const pre = $('#publicationStages');
  const details = $('#publicationDiagnosticDetails');
  if (pre) pre.textContent = formatPublicationStages(stages).join('\n') || 'Nenhuma etapa registrada.';
  if (details && open) details.open = true;
}

function writeDiagnosticOutput(value) {
  const output = $('#diagnosticOutput');
  if (!output) {
    console.warn('[StudioFrame] Diagnostic UI unavailable; operation state remains authoritative.');
    return false;
  }
  output.textContent = typeof value === 'string' ? value : JSON.stringify(value, null, 2);
  return true;
}
function renderPublicationStatus(kind = 'neutral', message = '') {
  const status = $('#publicationStatus');
  if (!status) {
    console.warn('[StudioFrame] Publication status UI unavailable; publication controller continues independently.', { kind, message });
    return false;
  }
  status.classList.toggle('ok', kind === 'ok');
  status.classList.toggle('error', kind === 'error');
  status.textContent = String(message || '');
  return true;
}

function showError(error) {
  console.error(error);
  const payload = error?.payload || {};
  const failures = payload?.failures || payload?.validation?.failures || [];
  if (failures?.length || Object.keys(payload).length) {
    writeDiagnosticOutput(payload);
  }
  const status = $('#publicationStatus');
  if (status && (payload.validation || payload.root_access || payload.required_action || payload.stages)) {
    const lines = [error.message || 'Falha na publicação.'];
    if (payload.stages?.length) { lines.push('', ...formatPublicationStages(payload.stages)); renderPublicationStages(payload.stages, true); }
    if (payload.root_access?.message) lines.push(payload.root_access.message);
    if (payload.required_action) lines.push(`AÇÃO NECESSÁRIA: ${payload.required_action}`);
    if (failures.length) {
      lines.push(`Alertas de mídia: ${failures.length}`);
      failures.slice(0, 8).forEach((item) => lines.push(`• ${item.name || item.file_id}: ${item.reason || item.stage || 'link público inválido'}`));
      if (failures.length > 8) lines.push(`… +${failures.length - 8} itens no Diagnóstico.`);
    }
    status.textContent = lines.join('\n');
    status.classList.remove('ok');
    status.classList.add('error');
  }
  toast(error.message || 'Falha inesperada');
}

function setBusy(button, active, label = 'Processando…') {
  if (!button) return;
  if (active) {
    if (!button.disabled || !button.dataset.originalText) button.dataset.originalText = button.textContent;
    button.textContent = label;
    button.disabled = true;
  } else {
    button.textContent = button.dataset.originalText || button.textContent;
    button.disabled = false;
  }
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"]/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;',
  }[character]));
}

