// V7.9 · professional services and pricing editor ----------------------------
function servicesState(){
  STATE.settings ||= {};STATE.settings.site_builder ||= {};
  STATE.settings.site_builder.services ||= {visible:true,show_on_home:true,slug:'servicos',menu_label:'Serviços',categories:[]};
  const services=STATE.settings.site_builder.services;
  services.categories=Array.isArray(services.categories)?services.categories:[];
  if(String(services.quote_finish_label||'')==='Finalizar pelo WhatsApp')services.quote_finish_label='Enviar solicitação';
  if(services.quote_home_visible==null)services.quote_home_visible=true;
  if(services.quote_endpoint_enabled==null)services.quote_endpoint_enabled=true;
  services.quote_endpoint=String(services.quote_endpoint||'/api/quote');
  services.quote_success_message=String(services.quote_success_message||'Solicitação recebida. Guarde o protocolo para acompanhar o pedido.');
  if(services.quote_fallback_whatsapp==null)services.quote_fallback_whatsapp=true;
  services.quote_home_title=String(services.quote_home_title||services.brief_title||'Monte seu orçamento');
  services.quote_home_intro=String(services.quote_home_intro||services.brief_body||'Escolha serviços, detalhe o escopo e envie uma solicitação com protocolo de recebimento.');
  return services;
}
function serviceEditorMediaOptions(selected=''){
  const rows=(STATE.projects||[]).filter((item)=>['image','video'].includes(String(item.type||'')));
  const options=[`<option value="">Sem capa · placeholder neutro</option>`];
  rows.forEach((item)=>options.push(`<option value="${escapeHtml(item.id)}" ${String(item.id)===String(selected)?'selected':''}>${escapeHtml(item.title||item.name||item.id)} · ${item.type==='video'?'VÍDEO':'IMAGEM'}</option>`));
  return options.join('');
}
function serviceEditorMedia(mediaId){return (STATE.projects||[]).find((item)=>String(item.id)===String(mediaId)&&['image','video'].includes(String(item.type||'')))||null;}
function serviceEditorCoverPreview(category){
  const fit=['cover','contain'].includes(String(category.cover_fit||''))?String(category.cover_fit):'cover';
  const focusX=Math.max(0,Math.min(100,Number(category.cover_position_x??50)||50));
  const focusY=Math.max(0,Math.min(100,Number(category.cover_position_y??50)||50));
  const overlay=Math.max(0,Math.min(.85,Number(category.overlay_strength??.38)||0));
  const previewStyle=`--service-accent:${escapeHtml(category.accent||'#0071E3')};--service-preview-overlay:${overlay};--service-preview-x:${focusX}%;--service-preview-y:${focusY}%;--service-preview-fit:${fit}`;
  if(category.show_cover===false)return `<div class="service-cover-preview is-auto" style="${previewStyle}"><span>${escapeHtml(category.number||'')}</span><i>Visual da área desativado</i></div>`;
  const media=serviceEditorMedia(category.cover_media_id);if(!media)return `<div class="service-cover-preview is-auto" style="${previewStyle}"><span>${escapeHtml(category.number||'')}</span><i>Sem capa escolhida · placeholder neutro</i></div>`;
  const poster=media.editor_thumbnail_url||`/api/drive/thumbnail/${encodeURIComponent(media.id)}`;
  return `<div class="service-cover-preview has-overlay" style="${previewStyle}"><img src="${escapeHtml(poster)}" alt=""><span>${media.type==='video'?'VÍDEO':'IMAGEM'}</span><i>${escapeHtml(media.title||media.name||media.id)}</i></div>`;
}
function serviceEditorItemCoverPreview(item,category){
  const media=serviceEditorMedia(item.cover_media_id);if(!media)return `<div class="service-cover-preview is-auto service-item-cover-preview" style="--service-accent:${escapeHtml(category.accent||'#0071E3')}"><span>↗</span><i>Usa a capa da área</i></div>`;
  const poster=media.editor_thumbnail_url||`/api/drive/thumbnail/${encodeURIComponent(media.id)}`;
  return `<div class="service-cover-preview service-item-cover-preview"><img src="${escapeHtml(poster)}" alt=""><span>${media.type==='video'?'VÍDEO':'IMAGEM'}</span><i>${escapeHtml(media.title||media.name||media.id)}</i></div>`;
}
