    block.section_reveal=boolValue('section_reveal',previous.section_reveal!==false);block.section_navigation_visible=boolValue('section_navigation_visible',previous.section_navigation_visible!==false);block.component_state_enabled=boolValue('component_state_enabled',previous.component_state_enabled!==false);applyMotionV77Fields(block,field);
