function createServiceCategory(){collectServicesEditor();const services=servicesState(),stamp=Date.now().toString(36);services.categories.push({id:`service-area-${stamp}`,order:(services.categories.length+1)*10,visible:true,featured:false,number:String(services.categories.length+1).padStart(2,'0'),title:'Nova área de serviço',short_title:'Nova área',description:'',accent:'#0071E3',cover_media_id:'',show_cover:true,cover_fit:'cover',cover_position_x:50,cover_position_y:50,overlay_strength:.38,text_alignment:'left',visual_height:'large',services:[]});renderServicesEditor();renderEditorSiteTree();markEditorDirty();queueAutoSave();}
function serviceCategoryById(id){return servicesState().categories.find((category)=>String(category.id)===String(id));}
function mutateServiceCategory(id,mutator){collectServicesEditor();const services=servicesState(),index=services.categories.findIndex((category)=>String(category.id)===String(id));if(index<0)return;mutator(services.categories,index);services.categories.forEach((category,position)=>category.order=(position+1)*10);renderServicesEditor();renderEditorSiteTree();markEditorDirty();queueAutoSave();refreshPreview();}
