async function loadCatalog({ render = true, preview = false } = {}) {
  const payload = await api('/api/catalog');
  STATE.catalog = payload.catalog;
  if (payload.asset_registry) STATE.assetRegistry = payload.asset_registry;
  if (payload.asset_health) STATE.assetHealth = payload.asset_health;
  flattenCatalog();
  renderDriveDataInspector();
  if (!STATE.assetRegistry) await loadAssetRegistry().catch(()=>null);
  STATE.renderedPanels = new Set();
  if (render) renderEditorShellAndActivePanel({ force:true });
  if (preview) schedulePreviewRefresh('catalog-loaded', 360);
  return payload;
}

async function synchronize(button = $('#syncDrive')) {
  setBusy(button, true, 'Lendo Drive…');
  const cloud = $('#cloudState');
  if (cloud) cloud.querySelector('span').textContent = 'Conectando ao Google Drive…';
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 45000);
    let payload;
    try {
      payload = await api('/api/catalog/sync', { method: 'POST', body: '{}', signal: controller.signal });
    } finally {
      clearTimeout(timer);
    }
    STATE.catalog = payload.catalog;
    if (payload.asset_registry) STATE.assetRegistry = payload.asset_registry;
    if (payload.asset_health) STATE.assetHealth = payload.asset_health;
    flattenCatalog();
    renderDriveDataInspector();
    STATE.renderedPanels = new Set();
    renderEditorShellAndActivePanel({ force:true });
    schedulePreviewRefresh('drive-sync', 280);
    toast(payload.source === 'cache' ? `${STATE.catalog.stats.projects} projetos do último catálogo válido · atualização do Drive não concluída` : `${STATE.catalog.stats.projects} projetos carregados diretamente do Drive`);
    return payload;
  } catch (error) {
    if (error?.name === 'AbortError') {
      const timeoutError = new Error('Google Drive não respondeu em 45 segundos. Verifique rede, credencial ou acesso da Service Account à pasta raiz.');
      if (cloud) cloud.querySelector('span').textContent = timeoutError.message;
      throw timeoutError;
    }
    if (cloud) cloud.querySelector('span').textContent = `Falha no Drive · ${error.message || 'erro desconhecido'}`;
    throw error;
  } finally {
    setBusy(button, false);
  }
}


function projectSectionConfig(id) {
  STATE.settings ||= {};
  STATE.settings.project_sections ||= {};
  return STATE.settings.project_sections[id] || {};
}


const COVER_GEOMETRY_PRESETS = {
  inherit: { label: 'Herdar formato da seção', px: 'usa o frame do grid' },
  '4x3': { label: 'Paisagem 4:3', px: '1600 × 1200 px', ratio: '4 / 3' },
  '16x9': { label: 'Wide 16:9', px: '1920 × 1080 px', ratio: '16 / 9' },
  '21x9': { label: 'Cinema 21:9', px: '2100 × 900 px', ratio: '21 / 9' },
  '1x1': { label: 'Quadrada 1:1', px: '1600 × 1600 px', ratio: '1 / 1' },
  '4x5': { label: 'Vertical 4:5', px: '1600 × 2000 px', ratio: '4 / 5' },
};
function coverGeometryLabel(cfg={}) {
  const key = String(cfg.cover_ratio || 'inherit');
  return COVER_GEOMETRY_PRESETS[key] || COVER_GEOMETRY_PRESETS.inherit;
}
function syncCoverGeometryLabel() {
  const root = $('#mmCoverGeometryInfo');
  if (!root) return;
  const preset = COVER_GEOMETRY_PRESETS[$('#mmCoverRatio')?.value || 'inherit'] || COVER_GEOMETRY_PRESETS.inherit;
  root.innerHTML = `<strong>${escapeHtml(preset.label)}</strong><span>${escapeHtml(preset.px)}</span><small>Use arquivos maiores que esta referência. O ponto focal evita cortes ruins quando a mesma capa aparece em outro breakpoint.</small>`;
}

function mediaConfig(id) {
  STATE.settings ||= {};
  STATE.settings.projects ||= {};
  return STATE.settings.projects[id] || {};
}

function collectMediaDescendants(node, output = []) {
  (node?.children || []).forEach((child) => {
    if (child.type === 'folder') collectMediaDescendants(child, output);
    else output.push(child);
  });
  return output;
}

function topLevelCategories() {
  return (STATE.catalog?.root?.children || []).filter((node) => node.type === 'folder' && Number(node.depth || 0) === 1);
}

function siteFilterSettings() {
  return STATE.settings?.site_builder?.projects?.filters || {};
}

function normalizedSiteFilterOrder() {
  const filters = siteFilterSettings();
  const categories = topLevelCategories();
  const valid = ['all', ...categories.map((category) => category.id)];
  const configuredOrder = Array.isArray(filters.order) ? filters.order.map(String) : [];
  const output = [];
  [...configuredOrder, ...valid].forEach((id) => {
    if (valid.includes(id) && !output.includes(id)) output.push(id);
  });
  return output;
}

function setSiteFilterOrder(order) {
  STATE.settings.site_builder ||= {};
  STATE.settings.site_builder.projects ||= {};
  STATE.settings.site_builder.projects.filters = {
    ...(STATE.settings.site_builder.projects.filters || {}),
    order: [...order],
  };
}

function renderSiteFilterOrder() {
  const root = $('#siteFilterOrderList');
  if (!root) return;
  const categories = new Map(topLevelCategories().map((category) => [category.id, category]));
  const order = normalizedSiteFilterOrder();
  root.replaceChildren();
  if (!order.length) {
    root.innerHTML = '<div class="empty">Sincronize o Drive para editar as seções.</div>';
    return;
  }
  order.forEach((id, index) => {
    const isAll = id === 'all';
    const category = categories.get(id);
    if (!isAll && !category) return;
    const cfg = isAll ? {} : configured(id);
    const title = isAll ? ($('#siteAllLabel')?.value || siteFilterSettings().all_label || 'Todos') : (cfg.title || category.title || category.name);
    const contentHidden = !isAll && cfg.visible === false;
    const navigationVisible = isAll ? ($('#siteAllVisible')?.checked !== false) : cfg.navigation_visible !== false;
    const row = document.createElement('article');
    row.className = `site-filter-order-row${isAll ? ' is-all' : ''}${navigationVisible ? '' : ' is-hidden'}${contentHidden ? ' is-content-hidden' : ''}`;
    row.dataset.siteFilterId = id;
    row.draggable = true;
    row.innerHTML = `<span class="handle">⋮⋮</span><div><strong>${escapeHtml(title)}</strong><small>${isAll ? 'Entrada geral da navegação' : (contentHidden ? 'Conteúdo oculto no site · pasta do Google Drive' : 'Categoria do portfólio · pasta do Google Drive')}</small></div><label class="inline-check site-filter-nav-toggle"><input type="checkbox" data-site-filter-navigation-visible="${escapeHtml(id)}" ${navigationVisible ? 'checked' : ''}> Mostrar na navegação</label><span class="arrows"><button data-site-filter-up="${escapeHtml(id)}" ${index === 0 ? 'disabled' : ''}>↑</button><button data-site-filter-down="${escapeHtml(id)}" ${index === order.length - 1 ? 'disabled' : ''}>↓</button></span>`;
    row.addEventListener('dragstart', (event) => {
      event.dataTransfer.setData('application/x-studioframe-filter', id);
      row.classList.add('dragging');
    });
    row.addEventListener('dragend', () => row.classList.remove('dragging'));
    row.addEventListener('dragover', (event) => { event.preventDefault(); row.classList.add('editorial-drop'); });
    row.addEventListener('dragleave', () => row.classList.remove('editorial-drop'));
    row.addEventListener('drop', (event) => {
      event.preventDefault(); row.classList.remove('editorial-drop');
      const sourceId = event.dataTransfer.getData('application/x-studioframe-filter');
      if (sourceId) reorderSiteFilter(sourceId, id);
    });
    root.append(row);
  });
  root.querySelectorAll('[data-site-filter-up]').forEach((button) => {
    button.onclick = () => moveSiteFilter(button.dataset.siteFilterUp, -1);
  });
  root.querySelectorAll('[data-site-filter-down]').forEach((button) => {
    button.onclick = () => moveSiteFilter(button.dataset.siteFilterDown, 1);
  });
  root.querySelectorAll('[data-site-filter-navigation-visible]').forEach((input) => {
    input.onchange = () => {
      const id = String(input.dataset.siteFilterNavigationVisible || '');
      if (id === 'all') {
        if ($('#siteAllVisible')) $('#siteAllVisible').checked = input.checked;
        STATE.settings.site_builder.projects.filters = { ...(STATE.settings.site_builder.projects.filters || {}), all_visible: input.checked };
      } else if (id) {
        STATE.settings.folders ||= {};
        STATE.settings.folders[id] = { ...configured(id), navigation_visible: input.checked };
      }
      const row = input.closest('.site-filter-order-row');
      row?.classList.toggle('is-hidden', !input.checked);
      markEditorDirty(); queueAutoSave(); refreshPreview();
    };
  });
}

function reorderSiteFilter(sourceId, targetId) {
  collectSettings();
  const order = normalizedSiteFilterOrder();
  const from = order.indexOf(sourceId), to = order.indexOf(targetId);
  if (from < 0 || to < 0 || from === to) return;
  const [moved] = order.splice(from, 1);
  order.splice(to, 0, moved);
  setSiteFilterOrder(order);
  renderSiteFilterOrder();
  queueAutoSave();
}

function moveSiteFilter(id, direction) {
  const order = normalizedSiteFilterOrder();
  const index = order.indexOf(id);
  const destination = index + direction;
  if (index < 0 || destination < 0 || destination >= order.length) return;
  [order[index], order[destination]] = [order[destination], order[index]];
  collectSettings();
  setSiteFilterOrder(order);
  renderSiteFilterOrder();
  queueAutoSave();
}

function syncSiteFilterCategoriesFromFolderOrder() {
  const current = normalizedSiteFilterOrder();
  const categories = topLevelCategories().map((category) => category.id);
  let categoryIndex = 0;
  const output = current.map((id) => id === 'all' ? 'all' : categories[categoryIndex++]).filter(Boolean);
  categories.slice(categoryIndex).forEach((id) => output.push(id));
  setSiteFilterOrder(output);
}

function rebuildProjectEntities() {
  const rootChildren = STATE.catalog?.root?.children || [];
  const categories = rootChildren.filter((node) => node.type === 'folder' && Number(node.depth || 0) === 1);
  const entities = [];
  categories.forEach((category) => {
    (category.children || []).forEach((child, fallbackOrder) => {
      if (child.type === 'folder') {
        const cfg = projectSectionConfig(child.id);
        entities.push({
          id: `folder:${child.id}`,
          drive_id: child.id,
          kind: 'folder-project',
          category_id: category.id,
          category,
          drive_item: child,
          name: child.name,
          title: cfg.title || child.title || child.name,
          description: cfg.description || child.description || '',
          order: Number.isFinite(Number(cfg.order)) ? Number(cfg.order) : Number(child.order ?? fallbackOrder),
          media: collectMediaDescendants(child, []),
        });
      } else {
        const cfg = mediaConfig(child.id);
        entities.push({
          id: `media:${child.id}`,
          drive_id: child.id,
          kind: 'single-media',
          category_id: category.id,
          category,
          drive_item: child,
          name: child.name,
          title: cfg.title || child.title || child.name.replace(/\.[^.]+$/, ''),
          description: cfg.description || child.description || '',
          order: Number.isFinite(Number(cfg.order)) ? Number(cfg.order) : Number(child.order ?? fallbackOrder),
          media: [child],
        });
      }
    });
  });
  entities.sort((a, b) => {
    if (a.category_id !== b.category_id) return 0;
    return (a.order - b.order) || String(a.title).localeCompare(String(b.title), 'pt-BR', { numeric: true });
  });
  STATE.projectEntities = entities;

  if (!categories.some((item) => item.id === STATE.selectedCategoryId)) {
    STATE.selectedCategoryId = categories[0]?.id || '';
  }
  const available = entities.filter((item) => item.category_id === STATE.selectedCategoryId);
  if (!available.some((item) => item.id === STATE.selectedProjectEntityId)) {
    STATE.selectedProjectEntityId = available[0]?.id || '';
  }
  return { categories, entities };
}

function selectedProjectEntity() {
  return STATE.projectEntities.find((item) => item.id === STATE.selectedProjectEntityId) || null;
}

function projectEntityConfig(entity) {
  if (!entity) return {};
  return entity.kind === 'folder-project' ? projectSectionConfig(entity.drive_id) : mediaConfig(entity.drive_id);
}

function projectCommercialConfig(entity) {
  const cfg = projectEntityConfig(entity);
  const source = cfg?.commercial && typeof cfg.commercial === 'object' ? cfg.commercial : {};
  const allowedModes = new Set(['cta','services','full']);
  const ids = [];
  const seen = new Set();
  (Array.isArray(source.related_service_ids) ? source.related_service_ids : []).forEach((value) => {
    const id = String(value || '').trim();
    if (id && !seen.has(id)) { seen.add(id); ids.push(id); }
  });
  return {
    enabled: source.enabled !== false,
    intro: String(source.intro || ''),
    related_service_ids: ids,
    cta_label: String(source.cta_label || 'Quero algo assim'),
    display_mode: allowedModes.has(String(source.display_mode || 'full')) ? String(source.display_mode || 'full') : 'full',
    position: 'after_media',
  };
}

function projectCommercialServiceChecklist(entity) {
  const selected = new Set(projectCommercialConfig(entity).related_service_ids.map(String));
  const rows = [];
  (servicesState().categories || []).forEach((category) => {
    (category.services || []).forEach((item) => {
      const id = String(item.id || '').trim();
      if (!id || item.visible === false) return;
      const label = `${category.short_title || category.title || 'Serviço'} · ${item.title || item.id}`;
      rows.push(`<label class="mm-commercial-service"><input type="checkbox" data-mm-project-commercial-service="${escapeHtml(id)}" ${selected.has(id)?'checked':''}> <span>${escapeHtml(label)}</span></label>`);
    });
  });
  return rows.join('') || '<div class="empty">Nenhum serviço disponível no catálogo.</div>';
}

function readProjectCommercialEditor(entity) {
  const previous = projectCommercialConfig(entity);
  if (!$('#mmProjectCommercialEnabled')) return previous;
  const ids = [...document.querySelectorAll('[data-mm-project-commercial-service]:checked')]
    .map((input) => String(input.dataset.mmProjectCommercialService || '').trim())
    .filter(Boolean);
  return {
    enabled: $('#mmProjectCommercialEnabled')?.checked === true,
    intro: String($('#mmProjectCommercialIntro')?.value || '').trim(),
    related_service_ids: [...new Set(ids)],
    cta_label: String($('#mmProjectCommercialCtaLabel')?.value || '').trim() || 'Quero algo assim',
    display_mode: $('#mmProjectCommercialDisplayMode')?.value || 'full',
    position: 'after_media',
  };
}

function mediaVisible(media) {
  return mediaConfig(media.id).visible !== false;
}

function projectCoverMedia(entity) {
  if (!entity?.media?.length) return null;
  if (entity.kind === 'folder-project') {
    const explicit = String(projectSectionConfig(entity.drive_id).cover_media_id || '');
    const selected = entity.media.find((media) => media.id === explicit && mediaVisible(media));
    if (selected) return selected;
  }
  return entity.media.find((media) => mediaVisible(media) && ['image', 'video'].includes(media.type))
    || entity.media.find((media) => mediaVisible(media))
    || entity.media[0];
}

function projectThumbnail(entity) {
  const media = projectCoverMedia(entity);
  return media?.editor_thumbnail_url || '';
}

function reorderProjectEntities(sourceId, targetId) {
  collectSettings();
  const source = STATE.projectEntities.find((item) => item.id === sourceId);
  const target = STATE.projectEntities.find((item) => item.id === targetId);
  if (!source || !target || source.category_id !== target.category_id || source.id === target.id) return;
  const siblings = STATE.projectEntities.filter((item) => item.category_id === source.category_id)
    .sort((a, b) => (a.order - b.order));
  const ids = siblings.map((item) => item.id);
  const from = ids.indexOf(source.id), to = ids.indexOf(target.id);
  if (from < 0 || to < 0) return;
  const [moved] = ids.splice(from, 1); ids.splice(to, 0, moved);
  ids.forEach((id, order) => {
    const entity = STATE.projectEntities.find((item) => item.id === id);
    if (!entity) return;
    if (entity.kind === 'folder-project') {
      STATE.settings.project_sections[entity.drive_id] = { ...projectSectionConfig(entity.drive_id), order };
    } else {
      STATE.settings.projects[entity.drive_id] = { ...mediaConfig(entity.drive_id), order };
    }
  });
  rebuildProjectEntities();
  renderMediaManagerProjects();
  queueAutoSave();
}

function reorderProjectMedia(entity, sourceId, targetId) {
  collectSettings();
  if (!entity || sourceId === targetId) return;
  const visibleOrder = [...entity.media].sort((a, b) => {
    const ao = Number(mediaConfig(a.id).order ?? a.order ?? 999999);
    const bo = Number(mediaConfig(b.id).order ?? b.order ?? 999999);
    return (ao - bo) || String(a.name).localeCompare(String(b.name), 'pt-BR', { numeric: true });
  });
  const ids = visibleOrder.map((item) => item.id);
  const from = ids.indexOf(sourceId), to = ids.indexOf(targetId);
  if (from < 0 || to < 0) return;
  const [moved] = ids.splice(from, 1); ids.splice(to, 0, moved);
  ids.forEach((id, order) => {
    STATE.settings.projects[id] = { ...mediaConfig(id), order };
  });
  entity.media.sort((a, b) => ids.indexOf(a.id) - ids.indexOf(b.id));
  renderMediaManagerInspector();
  queueAutoSave();
}

function renderMediaManagerCategories(categories) {
  const root = $('#mediaManagerCategoryList');
  if (!root) return;
  const filterRank = new Map(normalizedSiteFilterOrder().filter((id) => id !== 'all').map((id, index) => [id, index]));
  categories = [...categories].sort((a, b) => {
    const ar = filterRank.has(a.id) ? filterRank.get(a.id) : 999999;
    const br = filterRank.has(b.id) ? filterRank.get(b.id) : 999999;
    return (ar - br) || Number(a.order ?? 999999) - Number(b.order ?? 999999) || String(a.title || a.name || '').localeCompare(String(b.title || b.name || ''), 'pt-BR', { numeric: true });
  });
  root.replaceChildren();
  if (!categories.length) {
    root.innerHTML = '<div class="empty">Nenhuma categoria física encontrada.</div>';
    return;
  }
  categories.forEach((category) => {
    const count = STATE.projectEntities.filter((entity) => entity.category_id === category.id).length;
    const button = document.createElement('button');
    button.className = `mm-category${STATE.selectedCategoryId === category.id ? ' active' : ''}`;
    button.dataset.mmCategory = category.id;
    button.innerHTML = `<span>📁 ${escapeHtml(category.title || category.name)}</span><small>${count} projeto${count === 1 ? '' : 's'}</small>`;
    button.onclick = () => {
      STATE.selectedCategoryId = category.id;
      const first = STATE.projectEntities.find((item) => item.category_id === category.id);
      STATE.selectedProjectEntityId = first?.id || '';
      renderMediaManager();
      if (isMobileEditorViewport()) setMobileMediaManagerStage('projects');
    };
    button.addEventListener('dragover', (event) => {
      if (!driveWritable()) return;
      event.preventDefault(); button.classList.add('drive-drop');
    });
    button.addEventListener('dragleave', () => button.classList.remove('drive-drop'));
    button.addEventListener('drop', (event) => {
      event.preventDefault(); button.classList.remove('drive-drop');
      let payload = {};
      try { payload = JSON.parse(event.dataTransfer.getData('application/x-studioframe') || '{}'); } catch (_error) { payload = {}; }
      if (payload.kind !== 'project-entity') return;
      const entity = STATE.projectEntities.find((item) => item.id === payload.entity_id);
      if (!entity || entity.category_id === category.id) return;
      if (!window.confirm(`Mover "${entity.name}" para "${category.name}" no Google Drive?`)) return;
      STATE.selectedCategoryId = category.id;
      STATE.selectedProjectEntityId = entity.id;
      api('/api/drive/item/move', { method: 'POST', body: JSON.stringify({ file_id: entity.drive_id, new_parent_id: category.id }) })
        .then((result) => { applyCatalogFromDrive(result); toast(result.message); })
        .catch(showError);
    });
    root.append(button);
  });
}

function renderMediaManagerProjects() {
  const root = $('#mediaManagerProjectList');
  if (!root) return;
  const query = String($('#mediaManagerSearch')?.value || '').trim().toLowerCase();
  const entities = STATE.projectEntities.filter((entity) => entity.category_id === STATE.selectedCategoryId)
    .filter((entity) => !query || `${entity.title} ${entity.name}`.toLowerCase().includes(query))
    .sort((a, b) => (a.order - b.order) || String(a.title).localeCompare(String(b.title), 'pt-BR', { numeric: true }));
  root.replaceChildren();
  if (!entities.length) {
    root.innerHTML = '<div class="empty">Nenhum projeto nesta categoria.</div>';
    return;
  }
  entities.forEach((entity) => {
    const cfg = projectEntityConfig(entity);
    const physical = entity.drive_item;
    const canMove = driveWritable() && itemCapability(physical, 'canMoveItemWithinDrive', true);
    const card = document.createElement('article');
    card.className = `mm-project-card${STATE.selectedProjectEntityId === entity.id ? ' active' : ''}`;
    card.dataset.mmProject = entity.id;
    card.draggable = true;
    const thumb = projectThumbnail(entity);
    card.innerHTML = `
      <div class="mm-project-thumb">${thumb ? `<img src="${escapeHtml(thumb)}" alt="">` : '<span>—</span>'}</div>
      <div class="mm-project-handle" title="Arrastar para ordenar dentro desta categoria">⋮⋮</div>
      <div class="mm-project-copy">
        <strong>${escapeHtml(entity.title)}</strong>
        <small>${escapeHtml(entity.name)}</small>
        <span>${entity.media.length} mídia${entity.media.length === 1 ? '' : 's'}${cfg.visible === false ? ' · oculto' : ''}</span>
      </div>
      <div class="mm-project-order"><button data-mm-project-up="${entity.id}" title="Subir">↑</button><button data-mm-project-down="${entity.id}" title="Descer">↓</button></div>`;
    card.onclick = (event) => {
      if (event.target.closest('button')) return;
      STATE.selectedProjectEntityId = entity.id;
      renderMediaManagerProjects(); renderMediaManagerInspector();
      if (isMobileEditorViewport()) setMobileMediaManagerStage('inspector');
    };
    card.addEventListener('dragstart', (event) => {
      event.dataTransfer.setData('application/x-studioframe', JSON.stringify({ kind: 'project-entity', entity_id: entity.id, drive_id: entity.drive_id }));
      event.dataTransfer.effectAllowed = 'move'; card.classList.add('dragging');
    });
    card.addEventListener('dragend', () => card.classList.remove('dragging'));
    card.addEventListener('dragover', (event) => {
      event.preventDefault();
      card.classList.add('editorial-drop');
    });
    card.addEventListener('dragleave', () => card.classList.remove('editorial-drop'));
    card.addEventListener('drop', (event) => {
      event.preventDefault();
      card.classList.remove('editorial-drop');
      let payload = {};
      try { payload = JSON.parse(event.dataTransfer.getData('application/x-studioframe') || '{}'); } catch (_error) { payload = {}; }
      if (payload.kind === 'project-entity') reorderProjectEntities(payload.entity_id, entity.id);
    });
    root.append(card);
  });
  $$('[data-mm-project-up]').forEach((button) => {
    button.onclick = (event) => { event.stopPropagation(); const card = button.closest('[data-mm-project]'); const list = [...root.querySelectorAll('[data-mm-project]')]; const index = list.indexOf(card); if (index > 0) reorderProjectEntities(card.dataset.mmProject, list[index - 1].dataset.mmProject); };
  });
  $$('[data-mm-project-down]').forEach((button) => {
    button.onclick = (event) => { event.stopPropagation(); const card = button.closest('[data-mm-project]'); const list = [...root.querySelectorAll('[data-mm-project]')]; const index = list.indexOf(card); if (index >= 0 && index < list.length - 1) reorderProjectEntities(card.dataset.mmProject, list[index + 1].dataset.mmProject); };
  });
}



// V5.18 · Project Case Builder -------------------------------------------------
const CASE_BLOCK_REGISTRY = Object.freeze({
  case_header:{label:'Apresentação do projeto',core:true},media_stream:{label:'Sequência de mídias',core:true},next_project:{label:'Próximo projeto',core:true},
  media_full:{label:'Mídia full width'},split:{label:'Split · mídia + texto'},duo:{label:'Duas mídias'},video:{label:'Vídeo'},text:{label:'Texto / manifesto'},lettering:{label:'Lettering'},related_projects:{label:'Projetos semelhantes'},
});
const CASE_BLOCK_TYPES = Object.freeze(Object.fromEntries(Object.entries(CASE_BLOCK_REGISTRY).map(([type,meta])=>[type,meta.label])));
const CORE_CASE_TYPES = new Set(Object.entries(CASE_BLOCK_REGISTRY).filter(([,meta])=>meta.core).map(([type])=>type));

function caseBuilderConfig(entity) {
  const owner = entity?.kind === 'folder-project' ? projectSectionConfig(entity.drive_id) : mediaConfig(entity?.drive_id || '');
  return owner?.case_builder && typeof owner.case_builder === 'object' ? owner.case_builder : {};
}

function setCaseBuilderConfig(entity, builder) {
  if (!entity) return;
  if (entity.kind === 'folder-project') {
    STATE.settings.project_sections ||= {};
    STATE.settings.project_sections[entity.drive_id] = { ...projectSectionConfig(entity.drive_id), case_builder: builder };
  } else {
    STATE.settings.projects ||= {};
    STATE.settings.projects[entity.drive_id] = { ...mediaConfig(entity.drive_id), case_builder: builder };
  }
}

function normalizedProjectCaseBlocks(entity) {
  const configured = Array.isArray(caseBuilderConfig(entity).blocks) ? caseBuilderConfig(entity).blocks : [];
  const defaults = [
    { id:'case-core-header', type:'case_header', label:'Apresentação do projeto', visible:true, core:true },
    { id:'case-core-stream', type:'media_stream', label:'Sequência de mídias', visible:true, core:true, captions:true },
    { id:'case-core-related', type:'related_projects', label:'Projetos semelhantes', visible:true, core:true, mode:'auto_category', eyebrow:'CONTINUE EXPLORANDO', title:'Projetos semelhantes', max_items:3, columns:'3', show_category:true, items:[] },
    { id:'case-core-next', type:'next_project', label:'Próximo projeto', visible:true, core:true, scope:'category', cta:'Próximo projeto' },
  ];
  const output=[]; const seen=new Set();
  configured.forEach((source,index)=>{
    if (!source || typeof source !== 'object') return;
    const type=String(source.type||'').trim();
    if (!CASE_BLOCK_TYPES[type]) return;
    let id=String(source.id||'').trim() || `case-${Date.now()}-${index}`;
    if (seen.has(id)) id=`${id}-${index}`;
    seen.add(id);
    output.push({ ...source, id, type, core:Boolean(source.core || (CORE_CASE_TYPES.has(type) && id.startsWith('case-core-'))) });
  });
  defaults.forEach((item)=>{if(output.some((block)=>block.id===item.id))return;if(item.id==='case-core-related'){const nextIndex=output.findIndex((block)=>block.id==='case-core-next'||block.type==='next_project');if(nextIndex>=0){output.splice(nextIndex,0,{...item});return;}}output.push({...item});});
  const normalized=output.map((block)=>({...block,...normalizeComponentStateFields(block),...normalizeMotionV77Fields(block)}));
  setCaseBuilderConfig(entity, { ...caseBuilderConfig(entity), blocks: normalized });
  return normalized;
}

function caseMediaOptions(entity, selected='', type='all') {
  const list=(entity?.media || []).filter((media)=> type === 'all' || media.type === type);
  const options=['<option value="">Selecione uma mídia</option>'];
  list.forEach((media)=>{
    options.push(`<option value="${escapeHtml(media.id)}" ${String(media.id)===String(selected)?'selected':''}>${escapeHtml(`${media.type.toUpperCase()} · ${media.name}`)}</option>`);
  });
  return options.join('');
}

function caseRelatedProjectOptions(selectedItems=[]) {
  const selected=new Set((Array.isArray(selectedItems)?selectedItems:[]).map((row)=>String(row?.project_id||row||'')));
  return (STATE.projectEntities||[]).map((entity)=>{const value=homeProjectRef(entity);const category=entity.category?.title||entity.category?.name||'';return `<option value="${escapeHtml(value)}" ${selected.has(value)?'selected':''}>${escapeHtml(category?`${category} · ${entity.title}`:entity.title)}</option>`;}).join('');
}

function caseComponentStateFields(source={}) {
  const block=normalizeComponentStateFields(source),profile=activeThemeComponentProfile();
  const options=(items,current)=>items.map(([value,label])=>`<option value="${value}" ${String(value)===String(current)?'selected':''}>${label}</option>`).join('');
  return `<details class="wide motion-block-controls component-state-controls case-component-state-controls"><summary>Estados do componente · V7.8.6</summary><div class="motion-block-grid component-state-grid">
    <label>Motor<select data-case-field="component_state_enabled">${options([['true','Ativo'],['false','Desligado']],String(block.component_state_enabled!==false))}</select></label>
    <label>Hover<select data-case-field="component_hover_preset">${options([['inherit',`Herdar tema · ${profile.hover}`],['none','Nenhum'],['lift','Elevar'],['glow','Glow'],['zoom','Zoom'],['tilt','Tilt 3D'],['border','Borda de destaque'],['reveal','Reveal']],block.component_hover_preset)}</select></label>
    <label>Escopo<select data-case-field="component_hover_scope">${options([['auto','Automático'],['container','Bloco inteiro'],['cards','Cards'],['buttons','Botões'],['media','Mídias']],block.component_hover_scope)}</select></label>
    <label>Intensidade<input type="number" min="0" max="1" step="0.05" data-case-field="component_hover_intensity" value="${Number(block.component_hover_intensity)}"></label>
    <label>Transição · ms<input type="number" min="0" max="2000" step="20" data-case-field="component_transition_ms" value="${Number(block.component_transition_ms)}"></label>
    <label>Raio<select data-case-field="component_radius">${options([['inherit','Herdar'],['sharp','Reto'],['soft','Suave'],['round','Arredondado'],['pill','Pílula']],block.component_radius)}</select></label>
    <label>Superfície<select data-case-field="component_surface">${options([['inherit',`Herdar tema · ${profile.surface}`],['transparent','Transparente'],['solid','Sólida'],['glass','Glass'],['accent-soft','Destaque sutil']],block.component_surface)}</select></label>
    <label>Borda<select data-case-field="component_border">${options([['inherit','Herdar'],['none','Nenhuma'],['subtle','Sutil'],['accent','Destaque']],block.component_border)}</select></label>
    <label>Sombra<select data-case-field="component_shadow">${options([['inherit',`Herdar tema · ${profile.shadow}`],['none','Nenhuma'],['soft','Suave'],['deep','Profunda'],['glow','Glow']],block.component_shadow)}</select></label>
    <label>Foco<select data-case-field="component_focus">${options([['ring','Anel'],['underline','Sublinhado'],['invert','Invertido'],['none','Nativo']],block.component_focus)}</select></label>
    <label>Ativo / clique<select data-case-field="component_active">${options([['accent','Destaque'],['press','Pressionar'],['scale','Escala'],['none','Nenhum']],block.component_active)}</select></label>
    <label>Cursor<select data-case-field="component_cursor">${options([['auto','Automático'],['pointer','Pointer'],['default','Padrão']],block.component_cursor)}</select></label>
    <label>Mobile<select data-case-field="component_mobile_behavior">${options([['static','Estático'],['subtle','Sutil'],['preserve','Preservar']],block.component_mobile_behavior)}</select></label>
  </div></details>`;
}

function caseMotionVariationFields(source={}) {
  const block=normalizeMotionV77Fields(source),options=(items,current)=>items.map(([value,label])=>`<option value="${value}" ${String(value)===String(current)?'selected':''}>${label}</option>`).join('');
  return `<details class="wide motion-block-controls case-motion-controls"><summary>Motion Engine V7.8.7 · variação exclusiva</summary><div class="motion-block-grid">
    <label>Motion<select data-case-field="motion_enabled">${options([['true','Ativo'],['false','Desligado']],String(block.motion_enabled===true))}</select></label>
    <label class="wide">Variação exclusiva<select data-case-field="motion_preset">${motionV77PresetOptions(block.motion_preset)}</select><small>${escapeHtml(block.motion_theme_variant_id)}</small></label>
    <label>Engine<select data-case-field="motion_engine">${options([['auto','Auto'],['css_native','CSS / WAAPI'],['gsap','GSAP'],['motion','Motion'],['threejs','Three.js']],block.motion_engine)}</select></label>
    <label>Trigger<select data-case-field="motion_trigger">${options([['viewport','Viewport'],['scroll','Scroll'],['interaction','Interaction'],['state','State'],['continuous','Continuous'],['static','Static'],['load','Load']],block.motion_trigger)}</select></label>
    <label>Duração · s<input type="number" min="0" max="12" step="0.01" data-case-field="motion_duration" value="${Number(block.motion_duration)}"></label>
    <label>Delay · s<input type="number" min="0" max="12" step="0.01" data-case-field="motion_delay" value="${Number(block.motion_delay)}"></label>
    <label>Stagger · s<input type="number" min="0" max="2" step="0.01" data-case-field="motion_stagger" value="${Number(block.motion_stagger)}"></label>
    <label>Intensidade<select data-case-field="motion_intensity">${options([['none','None'],['subtle','Subtle'],['normal','Normal'],['strong','Strong'],['cinematic','Cinematic']],block.motion_intensity)}</select></label>
  </div></details>`;
}

function customCaseBlockFields(block, entity) {
  const title=escapeHtml(block.title||''); const eyebrow=escapeHtml(block.eyebrow||''); const body=escapeHtml(block.body||'');
  if (block.type === 'media_stream') return `
    <label>Legendas<select data-case-field="captions"><option value="true" ${block.captions!==false?'selected':''}>Exibir</option><option value="false" ${block.captions===false?'selected':''}>Ocultar</option></select></label>
    <div class="case-block-note wide">Usa todas as mídias visíveis na ordem definida acima. Oculte este bloco quando montar o case mídia por mídia.</div>`;
  if (block.type === 'next_project') return `
    <label>Texto do CTA<input data-case-field="cta" value="${escapeHtml(block.cta||'Próximo projeto')}"></label>
    <label>Sequência<select data-case-field="scope"><option value="category" ${(block.scope||'category')==='category'?'selected':''}>Mesma categoria</option><option value="all" ${block.scope==='all'?'selected':''}>Portfólio inteiro</option></select></label>`;
  if (block.type === 'related_projects') return `
    <label>Eyebrow<input data-case-field="eyebrow" value="${escapeHtml(block.eyebrow||'CONTINUE EXPLORANDO')}"></label>
    <label>Título<input data-case-field="title" value="${escapeHtml(block.title||'Projetos semelhantes')}"></label>
    <label>Modo<select data-case-field="mode"><option value="auto_category" ${(block.mode||'auto_category')==='auto_category'?'selected':''}>Automático · mesma categoria</option><option value="auto_services" ${block.mode==='auto_services'?'selected':''}>Automático · serviços relacionados</option><option value="selected" ${block.mode==='selected'?'selected':''}>Selecionados manualmente</option></select></label>
    <label>Máximo<select data-case-field="max_items"><option value="3" ${String(block.max_items||3)==='3'?'selected':''}>3</option><option value="4" ${String(block.max_items)==='4'?'selected':''}>4</option><option value="6" ${String(block.max_items)==='6'?'selected':''}>6</option></select></label>
    <label>Colunas<select data-case-field="columns"><option value="2" ${String(block.columns||'3')==='2'?'selected':''}>2</option><option value="3" ${String(block.columns||'3')==='3'?'selected':''}>3</option><option value="4" ${String(block.columns||'3')==='4'?'selected':''}>4</option></select></label>
    <label>Mostrar categoria<select data-case-field="show_category"><option value="true" ${block.show_category!==false?'selected':''}>Sim</option><option value="false" ${block.show_category===false?'selected':''}>Não</option></select></label>
    <label class="wide">Projetos manuais<select multiple size="7" data-case-related-projects>${caseRelatedProjectOptions(block.items||[])}</select><small>Usado quando o modo for “Selecionados manualmente”. Ctrl/Cmd permite selecionar vários.</small></label>`;
  if (block.type === 'media_full') return `
    <label class="wide">Mídia<select data-case-field="media_id">${caseMediaOptions(entity,block.media_id)}</select></label>
    <label>Título opcional<input data-case-field="title" value="${title}"></label>
    <label>Legenda<select data-case-field="caption"><option value="true" ${block.caption!==false?'selected':''}>Exibir</option><option value="false" ${block.caption===false?'selected':''}>Ocultar</option></select></label>`;
  if (block.type === 'video') return `
    <label class="wide">Vídeo<select data-case-field="media_id">${caseMediaOptions(entity,block.media_id,'video')}</select></label>
    <label>Eyebrow<input data-case-field="eyebrow" value="${eyebrow}"></label>
    <label>Título<input data-case-field="title" value="${title}"></label>
    <label class="wide">Texto<textarea data-case-field="body">${body}</textarea></label>`;
  if (block.type === 'split') return `
    <label>Mídia<select data-case-field="media_id">${caseMediaOptions(entity,block.media_id)}</select></label>
    <label>Lado da mídia<select data-case-field="media_side"><option value="left" ${(block.media_side||'left')==='left'?'selected':''}>Esquerda</option><option value="right" ${block.media_side==='right'?'selected':''}>Direita</option></select></label>
    <label>Eyebrow<input data-case-field="eyebrow" value="${eyebrow}"></label>
    <label>Título<input data-case-field="title" value="${title}"></label>
    <label class="wide">Texto<textarea data-case-field="body">${body}</textarea></label>`;
  if (block.type === 'duo') return `
    <label>Mídia 1<select data-case-field="media_id">${caseMediaOptions(entity,block.media_id)}</select></label>
    <label>Mídia 2<select data-case-field="media_id_2">${caseMediaOptions(entity,block.media_id_2)}</select></label>
    <label class="wide">Espaçamento<select data-case-field="gap"><option value="tight" ${block.gap==='tight'?'selected':''}>Compacto</option><option value="normal" ${(block.gap||'normal')==='normal'?'selected':''}>Normal</option><option value="wide" ${block.gap==='wide'?'selected':''}>Amplo</option></select></label>`;
  if (block.type === 'text') return `
    <label>Eyebrow<input data-case-field="eyebrow" value="${eyebrow}"></label>
    <label>Título<input data-case-field="title" value="${title}"></label>
    <label class="wide">Texto<textarea data-case-field="body">${body}</textarea></label>
    <label>Largura<select data-case-field="width"><option value="narrow" ${block.width==='narrow'?'selected':''}>Leitura</option><option value="medium" ${(block.width||'medium')==='medium'?'selected':''}>Média</option><option value="wide" ${block.width==='wide'?'selected':''}>Ampla</option></select></label>`;
  if (block.type === 'lettering') return `
    <label>Eyebrow<input data-case-field="eyebrow" value="${eyebrow}"></label>
    <label>Texto<input data-case-field="title" value="${title||'Mensagem Studio'}"></label>
    <label>Estilo<select data-case-field="style"><option value="split" ${(block.style||'split')==='split'?'selected':''}>Sólido + contorno</option><option value="solid" ${block.style==='solid'?'selected':''}>Sólido</option><option value="outline" ${block.style==='outline'?'selected':''}>Contorno</option></select></label>
    <label>Direção<select data-case-field="direction"><option value="left" ${(block.direction||'left')==='left'?'selected':''}>Esquerda</option><option value="right" ${block.direction==='right'?'selected':''}>Direita</option></select></label>`;
  return '';
}

function caseHeaderEditorFields(block, entity) {
  const cfg = entity?.kind === 'folder-project' ? projectSectionConfig(entity.drive_id) : mediaConfig(entity?.drive_id || '');
  const fallbackTitle = cfg?.title || entity?.title || entity?.name || '';
  const fallbackDescription = cfg?.description || entity?.description || '';
  const fallbackEyebrow = entity?.category?.title || entity?.category?.name || 'Projeto';
  const effective = (field, fallback='') => Object.prototype.hasOwnProperty.call(block, field) ? block[field] : fallback;
  const font = block.font_family || 'display';
  const weight = String(block.title_weight || '400');
  const align = block.text_align || 'left';
  const titleColor = block.title_color || 'text';
  const eyebrowColor = block.eyebrow_color || 'accent';
  return `
    <div class="wide home-editor-subgroup home-content-editor">
      <strong>Apresentação do projeto</strong>
      <div class="home-content-grid">
        <label>Eyebrow<input data-case-field="eyebrow" value="${escapeHtml(effective('eyebrow', fallbackEyebrow))}" placeholder="${escapeHtml(fallbackEyebrow)}"></label>
        <label>Título exibido<input data-case-field="title" value="${escapeHtml(effective('title', fallbackTitle))}" placeholder="${escapeHtml(fallbackTitle)}"></label>
        <label class="wide">Descrição exibida<textarea data-case-field="body" rows="5" placeholder="Descrição do projeto">${escapeHtml(effective('body', fallbackDescription))}</textarea></label>
        <label>Composição<select data-case-field="header_layout"><option value="media-copy" ${(block.header_layout||'media-copy')==='media-copy'?'selected':''}>Capa + texto</option><option value="copy-media" ${block.header_layout==='copy-media'?'selected':''}>Texto + capa</option><option value="copy-only" ${block.header_layout==='copy-only'?'selected':''}>Somente texto</option></select></label>
        <label>Exibir capa<select data-case-field="show_cover"><option value="true" ${block.show_cover!==false?'selected':''}>Sim</option><option value="false" ${block.show_cover===false?'selected':''}>Não</option></select></label>
        <label>Largura da descrição<select data-case-field="body_width"><option value="narrow" ${block.body_width==='narrow'?'selected':''}>Leitura</option><option value="medium" ${(block.body_width||'medium')==='medium'?'selected':''}>Média</option><option value="wide" ${block.body_width==='wide'?'selected':''}>Ampla</option></select></label>
      </div>
    </div>
    <details class="wide home-editor-subgroup typography-editor" open>
      <summary>Tipografia da apresentação</summary>
      <div class="home-typography-grid">
        <label>Fonte<select data-case-field="font_family"><option value="display" ${font==='display'?'selected':''}>Display · Gotham / Futura / Montserrat</option><option value="body" ${font==='body'?'selected':''}>Texto do projeto</option><option value="system" ${font==='system'?'selected':''}>Sans do sistema</option><option value="serif" ${font==='serif'?'selected':''}>Serif</option><option value="mono" ${font==='mono'?'selected':''}>Monoespaçada</option></select></label>
        <label>Tamanho do título · px<input type="number" min="18" max="320" step="1" data-case-field="title_size" value="${escapeHtml(block.title_size||'')}" placeholder="Automático"></label>
        <label>Peso<select data-case-field="title_weight"><option value="300" ${weight==='300'?'selected':''}>Light · 300</option><option value="400" ${weight==='400'?'selected':''}>Regular · 400</option><option value="500" ${weight==='500'?'selected':''}>Medium · 500</option><option value="600" ${weight==='600'?'selected':''}>Semibold · 600</option><option value="700" ${weight==='700'?'selected':''}>Bold · 700</option></select></label>
        <label>Entrelinha<input type="number" min=".65" max="2" step=".05" data-case-field="title_line_height" value="${escapeHtml(block.title_line_height||'')}" placeholder="Automática"></label>
        <label>Espaçamento<select data-case-field="title_letter_spacing"><option value="auto" ${(block.title_letter_spacing||'auto')==='auto'?'selected':''}>Automático</option><option value="-0.08em" ${block.title_letter_spacing==='-0.08em'?'selected':''}>Muito fechado</option><option value="-0.04em" ${block.title_letter_spacing==='-0.04em'?'selected':''}>Fechado</option><option value="0em" ${block.title_letter_spacing==='0em'?'selected':''}>Normal</option><option value="0.06em" ${block.title_letter_spacing==='0.06em'?'selected':''}>Aberto</option><option value="0.12em" ${block.title_letter_spacing==='0.12em'?'selected':''}>Muito aberto</option></select></label>
        <label>Alinhamento<select data-case-field="text_align"><option value="left" ${align==='left'?'selected':''}>Esquerda</option><option value="center" ${align==='center'?'selected':''}>Centro</option><option value="right" ${align==='right'?'selected':''}>Direita</option></select></label>
        <label>Cor do título<select data-case-field="title_color"><option value="text" ${titleColor==='text'?'selected':''}>Branco / texto</option><option value="accent" ${titleColor==='accent'?'selected':''}>Verde destaque</option><option value="muted" ${titleColor==='muted'?'selected':''}>Cinza</option></select></label>
        <label>Tamanho da descrição · px<input type="number" min="8" max="80" step="1" data-case-field="body_size" value="${escapeHtml(block.body_size||'')}" placeholder="Automático"></label>
        <label>Tamanho do eyebrow · px<input type="number" min="5" max="48" step="1" data-case-field="eyebrow_size" value="${escapeHtml(block.eyebrow_size||'')}" placeholder="Automático"></label>
        <label>Cor do eyebrow<select data-case-field="eyebrow_color"><option value="accent" ${eyebrowColor==='accent'?'selected':''}>Verde destaque</option><option value="text" ${eyebrowColor==='text'?'selected':''}>Branco / texto</option><option value="muted" ${eyebrowColor==='muted'?'selected':''}>Cinza</option></select></label>
      </div>
    </details>`;
}

function collectProjectCaseBlocksFromEditor(entity) {
  const root=$('#mmCaseBlockList');
  if (!root) return normalizedProjectCaseBlocks(entity);
  const current=new Map(normalizedProjectCaseBlocks(entity).map((block)=>[block.id,block]));
  const output=[];
  root.querySelectorAll('.case-block-row').forEach((row)=>{
    const id=row.dataset.caseBlockId; const previous=current.get(id)||{id,type:row.dataset.caseBlockType};
    const block={...previous,id,type:row.dataset.caseBlockType};
    const visible=row.querySelector('[data-case-visible]'); if (visible) block.visible=visible.checked;
    row.querySelectorAll('[data-case-field]').forEach((input)=>{
      let value=input.value; const field=input.dataset.caseField;
      if (['captions','caption','show_cover','show_category','component_state_enabled','motion_enabled'].includes(field)) value=value==='true';
      if(field==='max_items') value=Math.max(1,Math.min(6,Number(value)||3));
      if(field==='component_hover_intensity') value=Math.max(0,Math.min(1,Number(value)||0));
      if(field==='component_transition_ms') value=Math.max(0,Math.min(2000,Number(value)||0));
      block[field]=value;
    });
    applyMotionV77Fields(block,(name)=>row.querySelector(`[data-case-field="${name}"]`));
    const related=row.querySelector('[data-case-related-projects]');if(related){block.items=[...related.selectedOptions].map((option,index)=>({id:`related-${index+1}`,project_id:option.value,title:'',description:'',action_label:''})).filter((item)=>item.project_id);}
    output.push(block);
  });
  setCaseBuilderConfig(entity,{...caseBuilderConfig(entity),blocks:output});
  return output;
}

function renderProjectCaseEditor(entity) {
  const root=$('#mmCaseBlockList'); if (!root || !entity) return;
  const blocks=normalizedProjectCaseBlocks(entity); root.replaceChildren();
  blocks.forEach((block)=>{
    const core=Boolean(block.core || block.id.startsWith('case-core-'));
    const row=document.createElement('article'); row.className=`case-block-row${block.visible===false?' is-hidden':''}`;
    row.dataset.caseBlockId=block.id; row.dataset.caseBlockType=block.type;
    const fields=(block.type==='case_header'
      ? caseHeaderEditorFields(block,entity)
      : customCaseBlockFields(block,entity))+caseMotionVariationFields(block)+caseComponentStateFields(block);
    row.innerHTML=`<div class="case-block-main"><span class="case-block-handle" draggable="true" title="Arrastar para ordenar">⋮⋮</span><div class="case-block-title"><strong>${escapeHtml(block.label||CASE_BLOCK_TYPES[block.type]||'Bloco')}</strong><span class="case-block-type">${escapeHtml(CASE_BLOCK_TYPES[block.type]||block.type)}</span></div><div class="case-block-actions"><label><input type="checkbox" data-case-visible ${block.visible===false?'':'checked'}> Exibir</label>${core?'':`<button type="button" data-case-duplicate="${escapeHtml(block.id)}">Duplicar</button><button type="button" class="danger" data-case-delete="${escapeHtml(block.id)}">Excluir</button>`}</div></div><div class="case-block-settings">${fields}</div>`;
    root.append(row);
    row.querySelector('[data-case-visible]')?.addEventListener('change',()=>{collectProjectCaseBlocksFromEditor(entity);queueAutoSave();renderProjectCaseEditor(entity);});
    row.querySelectorAll('[data-case-field],[data-case-related-projects]').forEach((input)=>{input.addEventListener(input.tagName==='SELECT'?'change':'input',()=>{collectProjectCaseBlocksFromEditor(entity);queueAutoSave();});});
    row.querySelector('[data-case-duplicate]')?.addEventListener('click',()=>{
      collectProjectCaseBlocksFromEditor(entity); const current=normalizedProjectCaseBlocks(entity); const index=current.findIndex((item)=>item.id===block.id); const clone={...block,id:`case-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,label:`${block.label||CASE_BLOCK_TYPES[block.type]} cópia`,core:false}; current.splice(index+1,0,clone); setCaseBuilderConfig(entity,{...caseBuilderConfig(entity),blocks:current}); queueAutoSave(); renderProjectCaseEditor(entity);
    });
    row.querySelector('[data-case-delete]')?.addEventListener('click',()=>{
      collectProjectCaseBlocksFromEditor(entity); const current=normalizedProjectCaseBlocks(entity).filter((item)=>item.id!==block.id); setCaseBuilderConfig(entity,{...caseBuilderConfig(entity),blocks:current}); queueAutoSave(); renderProjectCaseEditor(entity);
    });
    const handle=row.querySelector('.case-block-handle');
    handle?.addEventListener('dragstart',(event)=>{event.dataTransfer.setData('application/x-studioframe-case',block.id);row.classList.add('dragging');});
    handle?.addEventListener('dragend',()=>row.classList.remove('dragging'));
    row.addEventListener('dragover',(event)=>{event.preventDefault();row.classList.add('drag-over');});
    row.addEventListener('dragleave',()=>row.classList.remove('drag-over'));
    row.addEventListener('drop',(event)=>{
      event.preventDefault();row.classList.remove('drag-over');const sourceId=event.dataTransfer.getData('application/x-studioframe-case');if(!sourceId||sourceId===block.id)return;
      collectProjectCaseBlocksFromEditor(entity); const current=normalizedProjectCaseBlocks(entity); const from=current.findIndex((item)=>item.id===sourceId); const to=current.findIndex((item)=>item.id===block.id); if(from<0||to<0)return; const [moved]=current.splice(from,1); current.splice(to,0,moved); setCaseBuilderConfig(entity,{...caseBuilderConfig(entity),blocks:current}); queueAutoSave(); renderProjectCaseEditor(entity);
    });
  });
}

function addProjectCaseBlock(entity) {
  const type=$('#mmCaseBlockType')?.value || 'media_full';
  if (!CASE_BLOCK_TYPES[type] || CORE_CASE_TYPES.has(type)) return;
  collectProjectCaseBlocksFromEditor(entity);
  const blocks=normalizedProjectCaseBlocks(entity);
  const firstMedia=(entity.media||[])[0]; const firstVideo=(entity.media||[]).find((item)=>item.type==='video');
  const block={id:`case-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,type,label:CASE_BLOCK_TYPES[type],visible:true,core:false};
  if (['media_full','split','duo'].includes(type)) block.media_id=firstMedia?.id||'';
  if (type==='duo') block.media_id_2=(entity.media||[])[1]?.id||'';
  if (type==='video') block.media_id=firstVideo?.id||'';
  if (type==='text') {block.eyebrow='Projeto';block.title='Novo bloco de texto';block.body='';block.width='medium';}
  if (type==='lettering') {block.title=entity.title||'Projeto';block.style='split';block.direction='left';}
  blocks.splice(Math.max(1,blocks.length-1),0,block);
  setCaseBuilderConfig(entity,{...caseBuilderConfig(entity),blocks}); queueAutoSave(); renderProjectCaseEditor(entity);
}

function renderMediaManagerInspector() {
  const root = $('#mediaManagerInspector');
  if (!root) return;
  const entity = selectedProjectEntity();
  if (!entity) {
    root.innerHTML = '<div class="empty">Selecione um projeto para editar.</div>';
    return;
  }
  const cfg = projectEntityConfig(entity);
  const folderProject = entity.kind === 'folder-project';
  const physical = entity.drive_item;
  const canRename = driveWritable() && itemCapability(physical, 'canRename', true);
  const canMove = driveWritable() && itemCapability(physical, 'canMoveItemWithinDrive', true);
  const canTrash = driveWritable() && itemCapability(physical, 'canTrash', true);
  const cover = projectCoverMedia(entity);
  const sortedMedia = [...entity.media].sort((a, b) => {
    const ao = Number(mediaConfig(a.id).order ?? a.order ?? 999999);
    const bo = Number(mediaConfig(b.id).order ?? b.order ?? 999999);
    return (ao - bo) || String(a.name).localeCompare(String(b.name), 'pt-BR', { numeric: true });
  });
  root.innerHTML = `
    <div class="mm-inspector-head">
      <div><em>${folderProject ? 'PROJETO / PASTA REAL' : 'PROJETO DE MÍDIA ÚNICA'}</em><h2>${escapeHtml(entity.title)}</h2><small>${escapeHtml(entity.category?.name || '')} / ${escapeHtml(entity.name)}</small></div>
      <div class="actions">
        <button data-mm-drive-rename ${canRename ? '' : 'disabled'}>Renomear Drive</button>
        <button data-mm-drive-move ${canMove ? '' : 'disabled'}>Mover Drive</button>
        <button class="danger" data-mm-drive-trash ${canTrash ? '' : 'disabled'}>Lixeira</button>
      </div>
    </div>
    <div class="mm-project-editor">
      <label>Nome no Google Drive<input id="mmProjectDriveName" data-drive-name="${entity.drive_id}" data-drive-original="${escapeHtml(entity.name)}" data-follow-title="${folderProject ? 'project' : 'media'}" value="${escapeHtml(entity.name)}" ${canRename ? '' : 'disabled'}></label>
      <label>Título público <small>(opcional)</small><input id="mmProjectTitle" value="${escapeHtml(cfg.title || entity.title)}" placeholder="Se vazio, usa o nome do Drive"></label>
      <label>Descrição<textarea id="mmProjectDescription" placeholder="Descrição editorial do projeto">${escapeHtml(cfg.description || entity.description || '')}</textarea></label>
      <label>Tamanho do título · px<input id="mmProjectTitleSize" type="number" min="14" max="160" step="1" value="${escapeHtml(cfg.title_size || '')}" placeholder="Automático responsivo"></label>
      <label>Tamanho da descrição · px<input id="mmProjectDescriptionSize" type="number" min="9" max="32" step="1" value="${escapeHtml(cfg.description_size || '')}" placeholder="Automático responsivo"></label>
      <div class="mm-editor-checks">
        <label><input id="mmProjectVisible" type="checkbox" ${cfg.visible === false ? '' : 'checked'}> Projeto visível</label>
        <label><input id="mmProjectFeatured" type="checkbox" ${cfg.featured ? 'checked' : ''}> Destaque</label>
        ${folderProject ? `<label><input id="mmProjectHero" type="checkbox" ${cfg.hero ? 'checked' : ''}> Usar projeto no Hero</label>` : ''}
      </div>
    </div>
    <section class="mm-project-commercial" aria-label="Projeto para serviços">
      <div class="mm-project-commercial-head"><div><em>PROJETO → SERVIÇOS</em><h3>Contratação relacionada</h3></div><label class="mm-commercial-toggle"><input id="mmProjectCommercialEnabled" type="checkbox" ${projectCommercialConfig(entity).enabled ? 'checked' : ''}> Ativar no projeto</label></div>
      <p>Associe este case aos serviços que o visitante pode contratar. O CTA reutiliza o Orçamento global e leva o projeto como referência; nenhum segundo formulário é criado.</p>
      <div class="mm-project-commercial-fields">
        <label class="wide">Texto introdutório<textarea id="mmProjectCommercialIntro" rows="3" placeholder="Ex.: Gostou deste trabalho? Podemos criar algo semelhante para sua marca.">${escapeHtml(projectCommercialConfig(entity).intro)}</textarea></label>
        <label>Texto do CTA<input id="mmProjectCommercialCtaLabel" value="${escapeHtml(projectCommercialConfig(entity).cta_label)}" placeholder="Quero algo assim"></label>
        <label>Apresentação<select id="mmProjectCommercialDisplayMode"><option value="cta" ${projectCommercialConfig(entity).display_mode==='cta'?'selected':''}>CTA simples</option><option value="services" ${projectCommercialConfig(entity).display_mode==='services'?'selected':''}>CTA + serviços relacionados</option><option value="full" ${projectCommercialConfig(entity).display_mode==='full'?'selected':''}>Bloco comercial completo</option></select></label>
        <label>Posição<select id="mmProjectCommercialPosition" disabled><option value="after_media" selected>Após sequência de mídias · hierarquia canônica</option></select></label>
      </div>
      <div class="mm-project-commercial-services"><strong>Serviços relacionados</strong><small>O primeiro serviço selecionado funciona como sugestão principal do CTA “Quero algo assim”.</small><div class="mm-project-commercial-service-grid">${projectCommercialServiceChecklist(entity)}</div></div>
    </section>
    <div class="mm-cover-panel mm-cover-editor">
      <div class="mm-cover-preview" id="mmCoverPreview" style="--cover-fit:${escapeHtml(cfg.cover_fit || 'cover')};--cover-x:${Number(cfg.cover_position_x ?? 50)}%;--cover-y:${Number(cfg.cover_position_y ?? 50)}%;--cover-zoom:${Number(cfg.cover_zoom ?? 1)};--cover-bg:${escapeHtml(cfg.cover_bg || '#111111')};">${cover?.editor_thumbnail_url ? `<img src="${escapeHtml(cover.editor_thumbnail_url)}" alt="Capa">` : '<div class="mm-cover-empty">Sem capa visual</div>'}</div>
      <div class="mm-cover-copy"><span>CAPA DO PROJETO</span><strong>${escapeHtml(cover?.name || 'Nenhuma mídia')}</strong><small>${folderProject ? 'Selecione “Capa” em qualquer mídia visível abaixo. Depois ajuste o enquadramento aqui.' : 'Projetos de mídia única usam a própria mídia.'}</small>
        <div class="mm-cover-geometry" id="mmCoverGeometryInfo"></div>
      </div>
      <div class="mm-cover-controls">
        <label>Formato preferencial<select id="mmCoverRatio"><option value="inherit" ${!cfg.cover_ratio || cfg.cover_ratio==='inherit'?'selected':''}>Herdar da seção</option><option value="4x3" ${cfg.cover_ratio==='4x3'?'selected':''}>4:3 · 1600×1200</option><option value="16x9" ${cfg.cover_ratio==='16x9'?'selected':''}>16:9 · 1920×1080</option><option value="21x9" ${cfg.cover_ratio==='21x9'?'selected':''}>21:9 · 2100×900</option><option value="1x1" ${cfg.cover_ratio==='1x1'?'selected':''}>1:1 · 1600×1600</option><option value="4x5" ${cfg.cover_ratio==='4x5'?'selected':''}>4:5 · 1600×2000</option></select></label>
        <label>Encaixe<select id="mmCoverFit"><option value="cover" ${(cfg.cover_fit||'cover')==='cover'?'selected':''}>Preencher · crop</option><option value="contain" ${cfg.cover_fit==='contain'?'selected':''}>Mostrar inteira</option></select></label>
        <label>Ponto focal X (%)<input id="mmCoverPositionX" type="number" min="0" max="100" step="1" value="${Number(cfg.cover_position_x ?? 50)}"></label>
        <label>Ponto focal Y (%)<input id="mmCoverPositionY" type="number" min="0" max="100" step="1" value="${Number(cfg.cover_position_y ?? 50)}"></label>
        <label>Zoom da capa<input id="mmCoverZoom" type="number" min="1" max="2.2" step="0.05" value="${Number(cfg.cover_zoom ?? 1)}"><small>1 = sem zoom · 2.2 = máximo</small></label>
        <label>Fundo<input id="mmCoverBg" type="color" value="${escapeHtml(cfg.cover_bg || '#111111')}"></label>
      </div>
    </div>
    <div class="mm-media-head"><div><em>MÍDIAS DO PROJETO</em><h3>${sortedMedia.length} item${sortedMedia.length === 1 ? '' : 's'}</h3></div><div class="actions">${folderProject ? '<button id="mmUploadProject">+ Adicionar arquivos</button>' : ''}<button data-save class="accent">Salvar</button></div></div>
    <div id="mmMediaList" class="mm-media-list">
      ${sortedMedia.length ? sortedMedia.map((media, index) => {
        const mc = mediaConfig(media.id);
        const isCover = folderProject ? String(cfg.cover_media_id || '') === media.id : index === 0;
        return `<article class="mm-media-row" draggable="true" data-mm-media-row="${media.id}">
          <div class="mm-drag" title="Arrastar para ordenar">⋮⋮</div>
          <div class="mm-media-thumb">${media.editor_thumbnail_url ? `<img src="${escapeHtml(media.editor_thumbnail_url)}" alt="">` : '<span>—</span>'}</div>
          <div class="mm-media-editor">
            <div class="physical-file"><span>${escapeHtml(media.type.toUpperCase())}</span><b>ARQUIVO REAL NO DRIVE</b></div>
            <input data-drive-name="${media.id}" data-drive-original="${escapeHtml(media.name)}" data-follow-title="media" value="${escapeHtml(media.name)}" ${driveWritable() && itemCapability(media, 'canRename', true) ? '' : 'disabled'} title="Nome físico do arquivo no Google Drive">
            <input data-project-title="${media.id}" value="${escapeHtml(mc.title || media.title || media.name.replace(/\.[^.]+$/, ''))}" placeholder="Título público opcional">
            <textarea data-project-description="${media.id}" placeholder="Descrição da mídia">${escapeHtml(mc.description || media.description || '')}</textarea>
            <small>${escapeHtml(media.relative_path || '')}</small>
          </div>
          <div class="mm-media-options">
            ${folderProject ? `<label class="cover-radio"><input type="radio" name="mmProjectCover" data-mm-cover="${media.id}" ${isCover ? 'checked' : ''} ${mc.visible === false ? 'disabled' : ''}> Capa</label>` : ''}
            <label><input type="checkbox" data-project-visible="${media.id}" ${mc.visible === false ? '' : 'checked'}> Visível</label>
            <label><input type="checkbox" data-project-featured="${media.id}" ${mc.featured ? 'checked' : ''}> Destaque</label>
            <label><input type="checkbox" data-project-hero="${media.id}" ${mc.hero ? 'checked' : ''} ${media.type === 'pdf' ? 'disabled' : ''}> Hero</label>
            <input type="checkbox" data-project-grid="${media.id}" checked hidden>
            <button data-mm-media-open="${media.id}">Visualizar</button>
            <button data-mm-media-rename="${media.id}" ${driveWritable() && itemCapability(media, 'canRename', true) ? '' : 'disabled'}>Renomear Drive</button>
            <button data-mm-media-move="${media.id}" ${driveWritable() && itemCapability(media, 'canMoveItemWithinDrive', true) ? '' : 'disabled'}>Mover Drive</button>
            <button class="danger" data-mm-media-trash="${media.id}" ${driveWritable() && itemCapability(media, 'canTrash', true) ? '' : 'disabled'}>Lixeira</button>
          </div>
        </article>`;
      }).join('') : '<div class="empty">Projeto sem mídia compatível. PSD/PSB e formatos não suportados permanecem ignorados.</div>'}
    </div>
    <div class="mm-case-builder">
      <div class="mm-media-head case-builder-head"><div><em>PROJECT PAGE BUILDER</em><h3>Apresentação e narrativa do projeto</h3></div><div class="actions"><select id="mmCaseBlockType"><option value="media_full">Mídia full width</option><option value="split">Split · mídia + texto</option><option value="duo">Duas mídias</option><option value="video">Vídeo</option><option value="text">Texto / manifesto</option><option value="lettering">Lettering</option></select><button id="mmAddCaseBlock" type="button" class="accent">+ Bloco</button></div></div>
      <p>O bloco “Apresentação do projeto” controla o título, a descrição e a tipografia exibidos quando o projeto é aberto. Depois dele, monte o case como uma sequência editorial; “Sequência de mídias” preserva o comportamento atual.</p>
      <div id="mmCaseBlockList" class="case-block-list"><div class="empty">Carregando blocos do case…</div></div>
    </div>`;

  $('#mmProjectTitle')?.addEventListener('input', queueAutoSave);
  $('#mmProjectDescription')?.addEventListener('input', queueAutoSave);
  $('#mmProjectTitleSize')?.addEventListener('input', queueAutoSave);
  $('#mmProjectDescriptionSize')?.addEventListener('input', queueAutoSave);
  ['mmProjectVisible','mmProjectFeatured','mmProjectHero'].forEach((id) => $('#'+id)?.addEventListener('change', queueAutoSave));
  ['mmProjectCommercialEnabled','mmProjectCommercialDisplayMode','mmProjectCommercialPosition'].forEach((id) => $('#'+id)?.addEventListener('change', queueAutoSave));
  ['mmProjectCommercialIntro','mmProjectCommercialCtaLabel'].forEach((id) => $('#'+id)?.addEventListener('input', queueAutoSave));
  root.querySelectorAll('[data-mm-project-commercial-service]').forEach((input) => input.addEventListener('change', queueAutoSave));

  syncCoverGeometryLabel();
  const refreshCoverPreview = () => {
    const preview = $('#mmCoverPreview'); if (!preview) return;
    preview.style.setProperty('--cover-fit', $('#mmCoverFit')?.value || 'cover');
    preview.style.setProperty('--cover-x', `${Math.max(0,Math.min(100,Number($('#mmCoverPositionX')?.value ?? 50)))}%`);
    preview.style.setProperty('--cover-y', `${Math.max(0,Math.min(100,Number($('#mmCoverPositionY')?.value ?? 50)))}%`);
    preview.style.setProperty('--cover-zoom', String(Math.max(1,Math.min(2.2,Number($('#mmCoverZoom')?.value ?? 1)))));
    preview.style.setProperty('--cover-bg', $('#mmCoverBg')?.value || '#111111');
    const preset=COVER_GEOMETRY_PRESETS[$('#mmCoverRatio')?.value || 'inherit'];
    preview.style.aspectRatio = preset?.ratio || '4 / 3';
  };
  ['mmCoverRatio','mmCoverFit','mmCoverBg'].forEach((id) => $('#'+id)?.addEventListener('change', () => { syncCoverGeometryLabel(); refreshCoverPreview(); queueAutoSave(); }));
  ['mmCoverPositionX','mmCoverPositionY','mmCoverZoom'].forEach((id) => $('#'+id)?.addEventListener('input', () => { refreshCoverPreview(); queueAutoSave(); }));
  refreshCoverPreview();
  root.querySelector('[data-mm-drive-rename]')?.addEventListener('click', () => renameDriveItem(entity.drive_id).catch(showError));
  root.querySelector('[data-mm-drive-move]')?.addEventListener('click', () => openDriveMove(entity.drive_id));
  root.querySelector('[data-mm-drive-trash]')?.addEventListener('click', () => trashDriveItem(entity.drive_id).catch(showError));
  $('#mmUploadProject')?.addEventListener('click', () => openDriveUpload(entity.drive_id));
  $('#mmAddCaseBlock')?.addEventListener('click', () => addProjectCaseBlock(entity));
  renderProjectCaseEditor(entity);
  root.querySelectorAll('[data-save]').forEach((button) => { button.onclick = () => saveSettings(button).catch(showError); });
  root.querySelectorAll('[data-mm-cover]').forEach((radio) => {
    radio.addEventListener('change', () => {
      if (!radio.checked || !folderProject) return;
      collectSettings();
      STATE.settings.project_sections[entity.drive_id] = { ...projectSectionConfig(entity.drive_id), cover_media_id: radio.dataset.mmCover };
      queueAutoSave(); renderMediaManagerProjects(); renderMediaManagerInspector();
    });
  });
  root.querySelectorAll('[data-mm-media-open]').forEach((button) => { button.onclick = () => { const media = entity.media.find((item) => item.id === button.dataset.mmMediaOpen); if (media?.editor_media_url) window.open(media.editor_media_url, '_blank'); }; });
  root.querySelectorAll('[data-mm-media-rename]').forEach((button) => { button.onclick = () => renameDriveItem(button.dataset.mmMediaRename).catch(showError); });
  root.querySelectorAll('[data-mm-media-move]').forEach((button) => { button.onclick = () => openDriveMove(button.dataset.mmMediaMove); });
  root.querySelectorAll('[data-mm-media-trash]').forEach((button) => { button.onclick = () => trashDriveItem(button.dataset.mmMediaTrash).catch(showError); });
  root.querySelectorAll('[data-mm-media-row]').forEach((row) => {
    row.addEventListener('dragstart', (event) => { event.dataTransfer.setData('application/x-studioframe', JSON.stringify({ kind: 'project-media', id: row.dataset.mmMediaRow })); row.classList.add('dragging'); });
    row.addEventListener('dragend', () => row.classList.remove('dragging'));
    row.addEventListener('dragover', (event) => { event.preventDefault(); row.classList.add('editorial-drop'); });
    row.addEventListener('dragleave', () => row.classList.remove('editorial-drop'));
    row.addEventListener('drop', (event) => {
      event.preventDefault(); row.classList.remove('editorial-drop');
      let payload = {};
      try { payload = JSON.parse(event.dataTransfer.getData('application/x-studioframe') || '{}'); } catch (_error) { payload = {}; }
      if (payload.kind === 'project-media') reorderProjectMedia(entity, payload.id, row.dataset.mmMediaRow);
    });
  });
}

function renderMediaManager() {
  const { categories } = rebuildProjectEntities();
  renderMediaManagerCategories(categories);
  renderMediaManagerProjects();
  renderMediaManagerInspector();
}


