    <label>Mobile<select data-home-field="experience_mobile_mode"><option value="pills" ${(block.experience_mobile_mode||'pills')==='pills'?'selected':''}>Pills horizontais + swipe</option><option value="compact" ${block.experience_mobile_mode==='compact'?'selected':''}>Índice compacto</option></select></label>
