function collectHomeBlocksFromEditor() {
  if(!STATE.renderedPanels?.has('home')) return normalizedHomeBlocks();
  const root = $('#homeBlockList');
  if (!root) return normalizedHomeBlocks();
  const current = new Map(normalizedHomeBlocks().map((block) => [block.id, block]));
  const output = [];
  root.querySelectorAll('.home-block-row').forEach((row) => {
    const id = row.dataset.homeBlockId;
    const previous = current.get(id) || { id, type: row.dataset.homeBlockType };
    const block = { ...previous, id, type: row.dataset.homeBlockType };
    const visible = row.querySelector('[data-home-visible]');
    if (visible) block.visible = visible.checked;
    row.querySelectorAll('[data-home-field]').forEach((input) => {
      const field = input.dataset.homeField;
      let value = input.value;
      if (['autoplay','muted','loop','pause_on_hover','force_motion','parallax','desktop_visible','mobile_visible','show_category','show_external_link','show_channel_link','section_reveal','section_navigation_visible','motion_enabled','component_state_enabled','wheel_navigation','decorative_lines','scroll_indicator','once','active','mouse_glow','mouse_parallax','scroll_parallax','mobile_mouse_parallax','section_global_canvas_keyframe_enabled','floating','form_enabled','grayscale','indicators','progress','minimal_controls','orbit','auto_rotate','scroll_enabled','scroll_pin','reduced_motion_fallback','navigation','fullscreen','open_external','allow_scripts','allow_same_origin'].includes(field) || (field === 'controls' && block.type === 'home_video')) value = value === 'true';
      if(['textured_focal_x','textured_focal_y','textured_scale','textured_parallax','textured_overlay','section_global_canvas_x','section_global_canvas_y','section_global_canvas_scale','section_global_canvas_rotation','section_global_canvas_opacity','section_global_canvas_blur','section_global_canvas_depth','section_global_canvas_mask_size','section_global_canvas_mask_radius','section_global_canvas_mask_feather','slice_depth_spread','slice_x_spread','slice_y_spread','slice_rotation_spread','slice_perspective','slice_mouse_strength','slice_scroll_strength','slice_smoothing','section_texture_opacity','section_texture_scale','section_overlay_opacity','section_min_height','section_padding_top','section_padding_bottom','line_opacity','motion_duration','motion_delay','motion_stagger','motion_scrub','component_hover_intensity','component_transition_ms','duration','delay','stagger','dot_size','dot_spacing','dot_opacity','wave_intensity','wave_radius','cols','strength','gradient_angle','speed','interval','perspective','depth','opacity','line_delay','slice_count','slice_gap','slice_overlap','height_vh','slice_duration','slice_stagger','slice_intensity','mouse_sensitivity','tablet_slice_count','mobile_slice_count','mobile_layer_limit','tablet_height_vh','mobile_height_vh','overlay','model_scale','rotation_x','rotation_y','rotation_z','camera_fov','scroll_scrub','max_pixel_ratio','radius'].includes(field))value=Number(value||0);
      block[field] = value;
    });
    const slicedRows=row.querySelectorAll('[data-sliced-layer-index]');
    if(block.type==='sliced_hero'&&slicedRows.length){
      const layerNumbers=new Set(['gradient_angle','x','y','scale','rotation','opacity','blur','z_index','depth','focal_x','focal_y']);
      const layerBooleans=new Set(['desktop_visible','tablet_visible','mobile_visible']);
      block.layers=[...slicedRows].map((layerRow,index)=>{
        const previousLayer=normalizedSlicedHeroLayers(block)[index]||{id:`slice-layer-${index+1}`};
        const layer={...previousLayer,id:String(previousLayer.id||`slice-layer-${index+1}`)};
        layerRow.querySelectorAll('[data-sliced-layer-field]').forEach((input)=>{
          const field=input.dataset.slicedLayerField;let value=input.value;
          if(layerNumbers.has(field))value=Number(value||0);
          if(layerBooleans.has(field))value=value==='true';
          layer[field]=value;
        });
        return layer;
      });
    }
    const itemRows = row.querySelectorAll('[data-home-items] .home-section-item-row');
    if (itemRows.length || row.querySelector('[data-home-items]')) {
      block.items = [...itemRows].map((itemRow, itemIndex) => {
        const item = { id: itemRow.dataset.homeItemRow || `item-${itemIndex+1}` };
        itemRow.querySelectorAll('[data-home-item-field]').forEach((input) => { item[input.dataset.homeItemField] = input.value || ''; });
        return item;
      });
    }
    output.push(block);
  });
  STATE.settings.site_builder.home = { ...(STATE.settings.site_builder.home || {}), blocks: output };
  const visibleCore = (type) => output.some((block) => block.type === type && block.visible !== false);
  const projectsHeader = output.find((block) => block.type === 'projects_header');
  const coreProjects = output.find((block) => block.type === 'projects');
  STATE.settings.site_builder.projects = { ...(STATE.settings.site_builder.projects || {}), visible: visibleCore('projects') };
  if (projectsHeader) {
    const projectsCfg=STATE.settings.site_builder.projects;
    projectsCfg.header_visible=projectsHeader.visible!==false;
    projectsCfg.eyebrow=String(projectsHeader.eyebrow??'');
    projectsCfg.title=String(projectsHeader.title??'');
    if ($('#siteProjectsHeaderVisible')) $('#siteProjectsHeaderVisible').checked=projectsCfg.header_visible;
    if ($('#siteProjectsEyebrow')) $('#siteProjectsEyebrow').value=projectsCfg.eyebrow;
    if ($('#siteProjectsTitle')) $('#siteProjectsTitle').value=projectsCfg.title;
  }
  if (coreProjects) {
    const projectsCfg = STATE.settings.site_builder.projects;
    if ($('#siteProjectsTitleSize')) $('#siteProjectsTitleSize').value = coreProjects.title_size || '';
    if ($('#siteProjectsEyebrowSize')) $('#siteProjectsEyebrowSize').value = coreProjects.eyebrow_size || '';
    if ($('#siteProjectsTitleWeight')) $('#siteProjectsTitleWeight').value = String(coreProjects.title_weight || '400');
    if ($('#siteProjectsTextAlign')) $('#siteProjectsTextAlign').value = coreProjects.text_align || 'left';
  }
  STATE.settings.site_builder.lettering = { ...(STATE.settings.site_builder.lettering || {}), visible: visibleCore('lettering') };
  STATE.settings.site_builder.about = { ...(STATE.settings.site_builder.about || {}), visible: visibleCore('about') };
  STATE.settings.site_builder.contact = { ...(STATE.settings.site_builder.contact || {}), visible: visibleCore('contact') };
  return output;
}

function renderHomeBlockEditor() {
  const root = $('#homeBlockList');
  if (!root) return;
  const blocks = normalizedHomeBlocks();
  root.replaceChildren();
  if (!STATE.openHomeBlockId && blocks.length) STATE.openHomeBlockId = blocks[0].id;
  blocks.forEach((block, index) => {
    const core = Boolean(block.core || block.id.startsWith('core-'));
    const row = document.createElement('article');
    row.className = `home-block-row${block.visible === false ? ' is-hidden' : ''}${STATE.openHomeBlockId === block.id ? ' is-open' : ' is-collapsed'}`;
    row.dataset.homeBlockId = block.id;
    row.dataset.homeBlockType = block.type;
    row.draggable = true;
    const contentFields = core ? coreHomeBlockFields(block) : customHomeBlockFields(block);
    const fields = `${wrapHomeContentFields(contentFields)}${homeTypographyFields(block)}${homeSectionLayoutFields(block)}`;
    row.innerHTML = `
      <div class="home-block-main">
        <span class="home-block-handle">⋮⋮</span>
        <span class="home-block-index">${String(index + 1).padStart(2,'0')}</span>
        <div class="home-block-title"><strong>${escapeHtml(block.label || HOME_BLOCK_TYPES[block.type] || 'Bloco')}</strong><span class="home-block-type">${escapeHtml(HOME_BLOCK_TYPES[block.type] || block.type)}${core ? ' · base' : ' · seção independente'}</span></div>
        <div class="home-block-actions">
          <label class="inline-check"><input type="checkbox" data-home-visible ${block.visible !== false ? 'checked' : ''}> Visível</label>
          <button type="button" data-home-edit="${escapeHtml(block.id)}" aria-expanded="${STATE.openHomeBlockId === block.id ? 'true' : 'false'}" class="${STATE.openHomeBlockId === block.id ? 'accent' : ''}">${STATE.openHomeBlockId === block.id ? 'Fechar editor' : 'Editar conteúdo'}</button>
          <button type="button" data-home-up="${escapeHtml(block.id)}" ${index === 0 ? 'disabled' : ''}>↑</button>
          <button type="button" data-home-down="${escapeHtml(block.id)}" ${index === blocks.length - 1 ? 'disabled' : ''}>↓</button>
          <button type="button" data-home-duplicate="${escapeHtml(block.id)}" ${core ? 'disabled title="Blocos-base não podem ser duplicados; remova e adicione outro tipo"' : ''}>Duplicar</button>
          <button type="button" class="danger" data-home-delete="${escapeHtml(block.id)}">Remover</button>
        </div>
      </div>
      <div class="home-block-settings"><label>Nome no editor<input data-home-field="label" value="${escapeHtml(block.label || HOME_BLOCK_TYPES[block.type] || 'Bloco')}"></label>${fields}</div>`;
    root.append(row);
  });
  if (!blocks.length) root.innerHTML = '<div class="empty home-empty-composer"><strong>A Home está vazia.</strong><span>Adicione Banner, Introdução, Grid, Carrossel ou qualquer outra seção acima.</span></div>';
  renderGlobalMediaCanvasEditor();
  renderThreeDSceneEditor();
  renderPhaserSceneEditor();
}

