function mutateHomeBlocks(mutator) {
  collectHomeBlocksFromEditor();
  const blocks = [...normalizedHomeBlocks()];
  const before = new Set(blocks.map((block)=>block.id));
  mutator(blocks);
  const added = blocks.find((block)=>!before.has(block.id));
  if (added) {
    STATE.openHomeBlockId = added.id;
    if(added.type==='youtube_showcase') STATE.settings.site_builder.home.youtube_showcase_removed=false;
  }
  if (STATE.openHomeBlockId && !blocks.some((block)=>block.id===STATE.openHomeBlockId)) STATE.openHomeBlockId = blocks[0]?.id || '';
  STATE.settings.site_builder.home.blocks = blocks;
  renderHomeBlockEditor();
  renderEditorSiteTree();
  queueAutoSave();
}

function moveHomeBlock(id, direction) {
  mutateHomeBlocks((blocks) => {
    const index = blocks.findIndex((block) => block.id === id);
    const target = index + direction;
    if (index < 0 || target < 0 || target >= blocks.length) return;
    [blocks[index], blocks[target]] = [blocks[target], blocks[index]];
  });
}

function duplicateHomeBlock(id) {
  mutateHomeBlocks((blocks) => {
    const index = blocks.findIndex((block) => block.id === id);
    if (index < 0 || blocks[index].core) return;
    const copy = { ...blocks[index], id: `block-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`, label: `${blocks[index].label || HOME_BLOCK_TYPES[blocks[index].type]} · cópia` };
    blocks.splice(index + 1, 0, copy);
  });
}

function deleteHomeBlock(id) {
  collectHomeBlocksFromEditor();
  const target=normalizedHomeBlocks().find((block)=>block.id===id);
  if(target?.type==='youtube_showcase'){
    STATE.settings.site_builder.home.youtube_showcase_removed=true;
  }
  mutateHomeBlocks((blocks) => {
    const index = blocks.findIndex((block) => block.id === id);
    if (index >= 0) blocks.splice(index, 1);
  });
}

function mutateSlicedHeroLayers(blockId,mutator) {
  mutateHomeBlocks((blocks)=>{
    const block=blocks.find((item)=>item.id===blockId&&item.type==='sliced_hero');
    if(!block)return;
    const layers=normalizedSlicedHeroLayers(block);
    mutator(layers);
    block.layers=layers.slice(0,9);
  });
}
function addSlicedHeroLayer(blockId) {
  mutateSlicedHeroLayers(blockId,(layers)=>{
    if(layers.length>=9){toast('O Sliced Hero aceita até 9 layers neste runtime');return;}
    const index=layers.length;
    layers.push({id:`slice-layer-${Date.now().toString(36)}`,role:'custom',label:`LAYER ${String(index+1).padStart(2,'0')}`,media_type:'transparent',media_id:'',color:'#72F2A5',gradient_start:'#72F2A5',gradient_end:'#FFFFFF',gradient_angle:90,x:0,y:0,scale:1,rotation:0,opacity:.5,blur:0,blend_mode:'screen',z_index:index+1,depth:Math.min(.95,.12+index*.14),focal_x:50,focal_y:50,desktop_visible:true,tablet_visible:true,mobile_visible:false});
  });
}
function moveSlicedHeroLayer(blockId,index,direction) {
  mutateSlicedHeroLayers(blockId,(layers)=>{const target=index+direction;if(index<0||target<0||target>=layers.length)return;[layers[index],layers[target]]=[layers[target],layers[index]];});
}
function removeSlicedHeroLayer(blockId,index) {
  if(index<3){toast('BACKGROUND, MIDDLE e FOREGROUND FRAME são obrigatórias');return;}
  mutateSlicedHeroLayers(blockId,(layers)=>{if(index>=0&&index<layers.length)layers.splice(index,1);});
}

function mutateHomeSectionItems(blockId, mutator) {
  collectHomeBlocksFromEditor();
  const block = normalizedHomeBlocks().find((item) => item.id === blockId);
  if (!block) return;
  const items = normalizedEditorialItems(block);
  mutator(items);
  block.items = items;
  renderHomeBlockEditor();
  queueAutoSave();
}

function addHomeSectionItem(blockId) {
  mutateHomeSectionItems(blockId, (items) => items.push({ id:`section-item-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,5)}`, project_id:'', media_id:'', title:'', description:'', action_label:'' }));
}
function moveHomeSectionItem(blockId, itemId, direction) {
  mutateHomeSectionItems(blockId, (items) => { const index=items.findIndex((item)=>item.id===itemId); const target=index+direction; if(index<0||target<0||target>=items.length)return; [items[index],items[target]]=[items[target],items[index]]; });
}
function removeHomeSectionItem(blockId, itemId) {
  mutateHomeSectionItems(blockId, (items) => { const index=items.findIndex((item)=>item.id===itemId); if(index>=0)items.splice(index,1); });
}

function sectionPickerKey(item) { return `${item.project_id || ''}|${item.media_id || ''}`; }
function sectionPickerProjectForMedia(mediaId) {
  const entity=(STATE.projectEntities||[]).find((candidate)=>(candidate.media||[]).some((media)=>String(media.id)===String(mediaId)));
  return entity ? homeProjectRef(entity) : '';
}
function sectionPickerCandidates(mode='projects', filter='') {
  const needle=String(filter||'').trim().toLocaleLowerCase('pt-BR');
  if(mode==='selected') return (STATE.sectionPickerDraft||[]).map((item)=>({kind:'selected',id:item.id||sectionPickerKey(item),...editorialItemVisual(item)})).filter((item)=>{const hay=[item.title,item.category,item.badge].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');return !needle||hay.includes(needle);});
  if(mode==='media') return (STATE.projects||[]).filter((item)=>['image','video'].includes(item.type)).filter((item)=>{const hay=[item.title,item.name,item.category_title,item.category,...(item.path||[])].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');return !needle||hay.includes(needle);}).map((item)=>({kind:'media',id:String(item.id),project_id:sectionPickerProjectForMedia(item.id),media_id:String(item.id),title:item.title||item.name||item.id,category:item.category_title||item.category||item.path?.[0]||'Drive',poster:item.editor_thumbnail_url||`/api/drive/thumbnail/${encodeURIComponent(item.id)}`,badge:item.type==='video'?'VÍDEO':'IMAGEM'}));
  return (STATE.projectEntities||[]).filter((entity)=>{const hay=[entity.title,entity.name,entity.category?.title,entity.category?.name].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');return !needle||hay.includes(needle);}).map((entity)=>({kind:'project',id:homeProjectRef(entity),project_id:homeProjectRef(entity),media_id:'',title:entity.title||entity.name||entity.id,category:entity.category?.title||entity.category?.name||'Projeto',poster:projectThumbnail(entity)||'',badge:'PROJETO'}));
}
function renderSectionContentPicker() {
  const root=$('#sectionContentLibrary'); if(!root)return;
  const mode=STATE.sectionPickerMode||'projects'; const filter=$('#sectionContentSearch')?.value||''; const candidates=sectionPickerCandidates(mode,filter); const selected=new Set((STATE.sectionPickerDraft||[]).map(sectionPickerKey));
  $('#sectionContentCount') && ($('#sectionContentCount').textContent=`${selected.size} selecionado${selected.size===1?'':'s'}`);
  document.querySelectorAll('[data-section-picker-tab]').forEach((button)=>button.classList.toggle('active',button.dataset.sectionPickerTab===mode));
  if(!candidates.length){root.innerHTML='<div class="empty">Nenhum conteúdo encontrado.</div>';return;}
  root.innerHTML=candidates.map((item)=>{const key=`${item.project_id}|${item.media_id}`;const active=selected.has(key);return `<button type="button" class="hero-media-choice section-content-choice${active?' is-selected':''}" data-section-content-project="${escapeHtml(item.project_id)}" data-section-content-media="${escapeHtml(item.media_id)}"><span class="hero-media-choice-preview">${item.poster?`<img src="${escapeHtml(item.poster)}" alt="" loading="lazy">`:''}<b>${item.badge}</b>${active?'<i>✓</i>':''}</span><span class="hero-media-choice-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml(item.category)}</small></span><span class="hero-media-choice-add">${active?'Selecionado':'Adicionar +'}</span></button>`}).join('');
}
function openSectionContentPicker(blockId, context='home') {
  let block = null;
  STATE.sectionPickerContext = context;
  if (context === 'section') {
    collectSectionPageFromEditor();
    const page = normalizedSectionPage(currentSectionPageId());
    block = page?.blocks?.find((item)=>item.id===blockId) || null;
  } else if (context === 'composer') {
    const row=$(`#sectionComposerList [data-composer-id="${CSS.escape(blockId)}"]`); if(row)collectComposerRow(row); block=findComposerSection(blockId)?.block||null;
  } else if (context === 'custom-page') {
    block=findCustomPageSection?.(blockId)?.block||null;
  } else {
    collectHomeBlocksFromEditor();
    block = normalizedHomeBlocks().find((item)=>item.id===blockId) || null;
  }
  if(!block)return;
  STATE.sectionPickerBlockId=blockId;
  STATE.sectionPickerDraft=normalizedEditorialItems(block).map((item)=>({...item}));
  STATE.sectionPickerMode=STATE.sectionPickerDraft.length?'selected':'projects';
  if($('#sectionContentSearch'))$('#sectionContentSearch').value='';
  renderSectionContentPicker();
  const dialog=$('#sectionContentDialog'); if(dialog&&!dialog.open)dialog.showModal();
  setTimeout(()=>$('#sectionContentSearch')?.focus(),30);
}
function toggleSectionPickerItem(projectId,mediaId) {
  const draft=STATE.sectionPickerDraft||[]; const key=`${projectId||''}|${mediaId||''}`; const index=draft.findIndex((item)=>sectionPickerKey(item)===key); if(index>=0)draft.splice(index,1); else draft.push({id:`section-item-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,5)}`,project_id:projectId||'',media_id:mediaId||'',title:'',description:'',action_label:''}); STATE.sectionPickerDraft=draft; renderSectionContentPicker();
}
function applySectionContentPicker() {
  const blockId=STATE.sectionPickerBlockId||''; if(!blockId)return;
  const draft=(STATE.sectionPickerDraft||[]).map((item)=>({...item}));
  if (STATE.sectionPickerContext === 'composer') {
    const found=findComposerSection(blockId); if(!found)return; found.block.items=draft; found.block.content_mode='selected'; persistComposerArray(found.destination,composerArray(found.destination)); STATE.openComposerSectionId=blockId; renderSectionComposer(); queueAutoSave(); refreshPreview(); $('#sectionContentDialog')?.close(); toast(`${draft.length} item(ns) aplicado(s) ao carrossel/seção`); return;
  }
  if (STATE.sectionPickerContext === 'custom-page') {
    const found=findCustomPageSection(blockId); if(!found)return; found.block.items=draft; found.block.content_mode='selected'; renderCustomPageBuilder(); queueAutoSave(); refreshPreview(); $('#sectionContentDialog')?.close(); toast(`${draft.length} item(ns) aplicado(s) à página`); return;
  }
  if (STATE.sectionPickerContext === 'section') {
    collectSectionPageFromEditor();
    const sectionId=currentSectionPageId();
    const page=normalizedSectionPage(sectionId);
    const block=page?.blocks?.find((item)=>item.id===blockId);
    if(!block)return;
    block.items=draft;
    block.content_mode='selected';
    STATE.settings.site_builder.section_pages[sectionId]=page;
    STATE.selectionSaveStatus='pending-cloud';
    STATE.openSectionBlockId=blockId;
    renderSectionPageEditor();
    markEditorDirty();
    queueAutoSave();
    refreshPreview({reason:'section-content-picker'});
    $('#sectionContentDialog')?.close();
    toast(`${block.items.length} item(ns) aplicado(s) ao bloco da categoria`);
    return;
  }
  collectHomeBlocksFromEditor();
  const block=normalizedHomeBlocks().find((item)=>item.id===blockId); if(!block)return;
  block.items=draft; block.content_mode='selected'; renderHomeBlockEditor(); markEditorDirty(); queueAutoSave(); refreshPreview({reason:'home-content-picker'}); $('#sectionContentDialog')?.close(); toast(`${block.items.length} item(ns) aplicado(s) à seção`);
}


// V7 Stage 6 · Page Builder / subpages -----------------------------------------
function customPageSectionTypeOptions(selected='') {
  return COMPOSER_SECTION_TYPES.map((type) => `<option value="${escapeHtml(type)}" ${type===selected?'selected':''}>${escapeHtml(HOME_BLOCK_TYPES[type]||type)}</option>`).join('');
}
function renderCustomPageBuilder(){
  const list=$('#customPageList'),editor=$('#customPageEditor'),parent=$('#newCustomPageParent'); if(!list||!editor||!STATE.settings)return; const pages=normalizedCustomPages(); if(parent)parent.innerHTML=customPageParentOptions('');
  const rows=Object.values(pages).sort((a,b)=>a.order-b.order);
  list.innerHTML=rows.length?rows.map((page)=>`<article class="custom-page-list-row${STATE.activeCustomPageId===page.id?' active':''}" data-custom-page-list-id="${escapeHtml(page.id)}" style="--page-depth:${customPageDepth(page.id)}"><button type="button" data-custom-page-open><strong>${escapeHtml(page.title)}</strong><small>/${escapeHtml(customPageFullPath(page.id))}/</small></button><div><button type="button" title="Subpágina" data-custom-page-child>＋</button><button type="button" data-custom-page-up>↑</button><button type="button" data-custom-page-down>↓</button><button type="button" class="danger" data-custom-page-delete>×</button></div></article>`).join(''):'<div class="empty">Nenhuma página customizada criada.</div>';
  const page=activeCustomPage(); if(!page){editor.innerHTML='<div class="empty">Crie uma página para iniciar o Page Builder.</div>';return;} STATE.activeCustomPageId=page.id;
  const sections=Array.isArray(page.sections)?page.sections:[];
  editor.innerHTML=`<div class="custom-page-inspector" data-custom-page-editor-id="${escapeHtml(page.id)}"><div class="subhead compact"><div><em>PÁGINA</em><h2>${escapeHtml(page.title)}</h2></div><code>/${escapeHtml(customPageFullPath(page.id))}/</code></div><div class="fields"><label>Título<input data-custom-page-field="title" value="${escapeHtml(page.title)}"></label><label>Slug<input data-custom-page-field="slug" value="${escapeHtml(page.slug)}"></label><label>Página pai<select data-custom-page-field="parent_id">${customPageParentOptions(page.parent_id,page.id)}</select></label><label>Nome no menu<input data-custom-page-field="menu_label" value="${escapeHtml(page.menu_label||page.title)}"></label><label class="inline-check"><input type="checkbox" data-custom-page-field="visible" ${page.visible!==false?'checked':''}> Página publicada</label><label class="inline-check"><input type="checkbox" data-custom-page-field="show_in_menu" ${page.show_in_menu!==false?'checked':''}> Exibir no menu</label><label>Eyebrow<input data-custom-page-field="eyebrow" value="${escapeHtml(page.eyebrow||'')}"></label><label class="wide">Introdução<textarea rows="4" data-custom-page-field="intro">${escapeHtml(page.intro||'')}</textarea></label></div><section class="custom-page-sections"><div class="subhead compact"><div><em>SEÇÕES</em><h2>Composição da página</h2></div><div class="page-section-create"><select data-custom-page-section-type><option value="auto_carousel">Carrossel contínuo</option><option value="editorial_carousel">Carrossel editorial</option><option value="editorial_blocks">Grid / blocos</option><option value="editorial_gallery">Galeria</option><option value="related_projects">Cases relacionados</option><option value="quote_cta">Orçamento integrado</option><option value="showcase">Showcase</option><option value="split">Mídia + texto</option><option value="text">Texto</option><option value="textured_reveal">Textured Reveal</option><option value="marquee">Marquee</option><option value="cta">CTA</option><option value="home_video">Vídeo</option><option value="spacer">Respiro</option></select><button type="button" class="accent" data-custom-page-section-add>+ Seção</button></div></div><div class="custom-page-section-list">${sections.length?sections.map((block,index)=>`<article class="composer-section-row${STATE.openCustomPageSectionId===block.id?' is-open':''}" data-custom-page-section-id="${escapeHtml(block.id)}"><div class="composer-section-head"><span class="composer-index">${String(index+1).padStart(2,'0')}</span><div><strong>${escapeHtml(block.label||HOME_BLOCK_TYPES[block.type]||block.type)}</strong><small>${escapeHtml(HOME_BLOCK_TYPES[block.type]||block.type)}</small></div><label class="inline-check"><input type="checkbox" data-custom-page-section-visible ${block.visible!==false?'checked':''}> Visível</label><div class="composer-actions"><button type="button" data-custom-page-section-edit>${STATE.openCustomPageSectionId===block.id?'Fechar':'Editar'}</button><button type="button" data-custom-page-section-up>↑</button><button type="button" data-custom-page-section-down>↓</button><button type="button" class="danger" data-custom-page-section-remove>Remover</button></div></div><div class="composer-section-body" ${STATE.openCustomPageSectionId===block.id?'':'hidden'}><div class="fields composer-fields">${adaptHomeEditorToCustomPage(composerBlockEditor(block))}</div></div></article>`).join(''):'<div class="empty">A página ainda não possui seções.</div>'}</div></section></div>`;
  const typeSelect=editor.querySelector('[data-custom-page-section-type]');
  if(typeSelect)typeSelect.innerHTML=customPageSectionTypeOptions(typeSelect.value);
}
function adaptHomeEditorToCustomPage(html=''){return String(html||'').replaceAll('data-composer-field','data-custom-page-section-field').replaceAll('data-composer-items','data-custom-page-section-items').replaceAll('data-composer-item-row','data-custom-page-section-item-row').replaceAll('data-composer-item-field','data-custom-page-section-item-field').replaceAll('data-composer-content-picker','data-custom-page-content-picker').replaceAll('data-composer-item-add','data-custom-page-item-add').replaceAll('data-composer-item-up','data-custom-page-item-up').replaceAll('data-composer-item-down','data-custom-page-item-down').replaceAll('data-composer-item-remove','data-custom-page-item-remove');}
function collectCustomPageEditor(){const page=activeCustomPage();const root=$('[data-custom-page-editor-id]');if(!page||!root)return page;root.querySelectorAll('[data-custom-page-field]').forEach((input)=>{const field=input.dataset.customPageField;let value=input.type==='checkbox'?input.checked:input.value;if(field==='slug')value=slugifyPage(value);page[field]=value;});const blocked=new Set([page.id,...customPageDescendantIds(page.id)]);if(blocked.has(page.parent_id))page.parent_id='';page.title=page.title||'Página';page.menu_label=page.menu_label||page.title;page.sections ||= [];const current=new Map(page.sections.map((b)=>[b.id,b]));root.querySelectorAll('[data-custom-page-section-id]').forEach((row)=>{const id=row.dataset.customPageSectionId;const block=current.get(id);if(!block)return;block.visible=row.querySelector('[data-custom-page-section-visible]')?.checked!==false;row.querySelectorAll('[data-custom-page-section-field]').forEach((input)=>{let value=input.value;const field=input.dataset.customPageSectionField;if(['autoplay','pause_on_hover','force_motion','muted','loop','controls','parallax','desktop_visible','mobile_visible','show_category','show_external_link','show_channel_link','section_reveal','section_navigation_visible','motion_enabled','component_state_enabled','wheel_navigation','decorative_lines','scroll_indicator','once','active','mouse_glow','floating','form_enabled','grayscale','indicators','progress','minimal_controls','pause_on_hover'].includes(field))value=value==='true';if(['section_texture_opacity','section_texture_scale','section_overlay_opacity','section_min_height','section_padding_top','section_padding_bottom','line_opacity','motion_duration','motion_delay','motion_stagger','component_hover_intensity','component_transition_ms','duration','delay','stagger','dot_size','dot_spacing','dot_opacity','wave_intensity','wave_radius','cols','strength','gradient_angle','speed','interval','perspective','depth','opacity','line_delay','speed','gap_px','card_width','initial_open'].includes(field))value=Number(value||0);block[field]=value;});const itemRows=row.querySelectorAll('[data-custom-page-section-items] [data-custom-page-section-item-row]');if(itemRows.length||row.querySelector('[data-custom-page-section-items]'))block.items=[...itemRows].map((itemRow,i)=>{const item={id:itemRow.dataset.customPageSectionItemRow||`page-item-${i+1}`};itemRow.querySelectorAll('[data-custom-page-section-item-field]').forEach((input)=>item[input.dataset.customPageSectionItemField]=input.value||'');return item;});});return page;}
function createCustomPage(parentId=''){collectCustomPageEditor();const pages=normalizedCustomPages();const title=String($('#newCustomPageTitle')?.value||'Nova página').trim()||'Nova página';const id=`page-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;pages[id]={id,title,slug:slugifyPage(title),parent_id:parentId||$('#newCustomPageParent')?.value||'',visible:true,show_in_menu:true,menu_label:title,order:(Object.keys(pages).length+1)*10,eyebrow:'',intro:'',sections:[]};STATE.activeCustomPageId=id;STATE.previewCustomPageId=id;STATE.previewSectionId='';STATE.previewPage='';try{localStorage.setItem('studioframe-active-custom-page',id);}catch(_){}renderAll();renderCustomPageBuilder();markEditorDirty();queueAutoSave();refreshPreview({structural:true,reason:'custom-page-created'});}
function deleteCustomPage(id){const pages=normalizedCustomPages();if(!pages[id])return;Object.values(pages).forEach((page)=>{if(page.parent_id===id)page.parent_id='';});delete pages[id];if(STATE.activeCustomPageId===id)STATE.activeCustomPageId='';renderAll();renderCustomPageBuilder();markEditorDirty();queueAutoSave();refreshPreview();}
function moveCustomPage(id,direction){collectCustomPageEditor();const pages=normalizedCustomPages();const page=pages[id];if(!page)return;const siblings=Object.values(pages).filter((p)=>p.parent_id===page.parent_id).sort((a,b)=>a.order-b.order);const i=siblings.findIndex((p)=>p.id===id),j=i+direction;if(i<0||j<0||j>=siblings.length)return;[siblings[i],siblings[j]]=[siblings[j],siblings[i]];siblings.forEach((p,index)=>p.order=(index+1)*10);renderAll();renderCustomPageBuilder();queueAutoSave();refreshPreview();}
function addCustomPageSection(pageId,type){const pages=normalizedCustomPages();const page=pages[pageId];if(!page)return;const block=newHomeBlock(type);if(!block)return;block.id=`page-section-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,5)}`;block.core=false;block.label=HOME_BLOCK_TYPES[type]||'Seção';if(['auto_carousel','editorial_carousel','editorial_blocks','editorial_gallery','highlights','horizontal_projects','related_projects'].includes(type)){block.content_mode='selected';block.items=[];}page.sections.push(block);STATE.openCustomPageSectionId=block.id;renderCustomPageBuilder();renderEditorSiteTree();queueAutoSave();refreshPreview();}
function reorderCustomPageSection(pageId,blockId,direction){collectCustomPageEditor();const page=normalizedCustomPages()[pageId];if(!page)return;const i=page.sections.findIndex((b)=>b.id===blockId),j=i+direction;if(i<0||j<0||j>=page.sections.length)return;[page.sections[i],page.sections[j]]=[page.sections[j],page.sections[i]];renderCustomPageBuilder();queueAutoSave();refreshPreview();}
function removeCustomPageSection(pageId,blockId){const page=normalizedCustomPages()[pageId];if(!page)return;page.sections=page.sections.filter((b)=>b.id!==blockId);renderCustomPageBuilder();queueAutoSave();refreshPreview();}

// V7 Stage 4 · Unified Section Composer ---------------------------------------
const COMPOSER_SECTION_TYPES = ['editorial_carousel','auto_carousel','autoplay_carousel','editorial_blocks','editorial_gallery','highlights','related_projects','quote_cta','showcase','showcase_3d','html5_pdf_show','full_media','split','horizontal_projects','spotlight','marquee','cta','text','lettering_custom','home_video','video_feature','youtube_showcase','external_embed','cinematic_hero','section_experience','textured_reveal','renaissance_chapter','metrics','process','testimonials','accordion','spacer','loop_cards','interactive_folders'];
function slugifyPage(value=''){return String(value||'pagina').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'')||'pagina';}
function normalizedCustomPages(){
  STATE.settings.site_builder ||= {}; STATE.settings.site_builder.custom_pages ||= {}; const pages=STATE.settings.site_builder.custom_pages;
  Object.entries(pages).forEach(([id,page],index)=>{if(!page||typeof page!=='object'){delete pages[id];return;}page.id=String(page.id||id);page.title=String(page.title||'Página');page.slug=slugifyPage(page.slug||page.title);page.parent_id=String(page.parent_id||'');if(page.parent_id===page.id||!pages[page.parent_id])page.parent_id='';page.visible=page.visible!==false;page.show_in_menu=page.show_in_menu!==false;page.menu_label=String(page.menu_label||page.title);page.order=Number(page.order??((index+1)*10));page.eyebrow=String(page.eyebrow||'');page.intro=String(page.intro||'');page.sections=Array.isArray(page.sections)?page.sections:[];});
  // Break accidental parent cycles deterministically. A page can never become
  // a descendant of itself; this protects the editor tree and generated routes.
  Object.values(pages).forEach((page)=>{const seen=new Set([page.id]);let parent=page.parent_id;while(parent&&pages[parent]){if(seen.has(parent)){page.parent_id='';break;}seen.add(parent);parent=pages[parent].parent_id;}});
  return pages;
}
function customPageFullPath(pageId,seen=new Set()){const pages=normalizedCustomPages();const page=pages[pageId];if(!page)return'';if(seen.has(pageId))return'';seen.add(pageId);const own=slugifyPage(page.slug||page.title);if(!page.parent_id||!pages[page.parent_id])return own;const parent=customPageFullPath(page.parent_id,seen);return [parent,own].filter(Boolean).join('/');}
function customPageDescendantIds(pageId){const pages=normalizedCustomPages(),out=new Set();const walk=(id)=>Object.values(pages).filter((p)=>p.parent_id===id).forEach((child)=>{if(out.has(child.id))return;out.add(child.id);walk(child.id);});walk(pageId);return out;}
function customPageDepth(pageId){const pages=normalizedCustomPages();let depth=0,current=pages[pageId],seen=new Set();while(current?.parent_id&&pages[current.parent_id]&&!seen.has(current.parent_id)){seen.add(current.parent_id);depth+=1;current=pages[current.parent_id];}return depth;}
function customPageParentOptions(selected='',exclude=''){const blocked=new Set(exclude?[exclude,...customPageDescendantIds(exclude)]:[]);const pages=Object.values(normalizedCustomPages()).filter((p)=>!blocked.has(p.id)).sort((a,b)=>a.order-b.order);return `<option value="">Nenhuma · página principal</option>`+pages.map((p)=>`<option value="${escapeHtml(p.id)}" ${p.id===selected?'selected':''}>${'— '.repeat(customPageDepth(p.id))}${escapeHtml(p.title)} · /${escapeHtml(customPageFullPath(p.id))}/</option>`).join('');}
function activeCustomPage(){const pages=normalizedCustomPages();if(STATE.activeCustomPageId&&pages[STATE.activeCustomPageId])return pages[STATE.activeCustomPageId];try{const saved=localStorage.getItem('studioframe-active-custom-page');if(saved&&pages[saved]){STATE.activeCustomPageId=saved;return pages[saved];}}catch(_){}return Object.values(pages).sort((a,b)=>a.order-b.order)[0]||null;}
function findCustomPageSection(blockId){for(const page of Object.values(normalizedCustomPages())){const block=(page.sections||[]).find((item)=>String(item.id)===String(blockId));if(block)return{page,block};}return null;}

function composerDestinations(){
  const rows=[{id:'home',label:'Home'}];
  topLevelCategories().forEach((category)=>rows.push({id:`category:${category.id}`,label:`Categoria · ${configured(category.id).title || category.title || category.name}`}));
  Object.values(normalizedCustomPages()).sort((a,b)=>Number(a.order||0)-Number(b.order||0)).forEach((page)=>rows.push({id:`page:${page.id}`,label:`Página · ${page.title || page.id}`}));
  return rows;
}
function composerDestinationOptions(selected='home'){ return composerDestinations().map((row)=>`<option value="${escapeHtml(row.id)}" ${row.id===selected?'selected':''}>${escapeHtml(row.label)}</option>`).join(''); }
function composerPositionOptions(destination='home', selected='end') {
  const blocks = composerArray(destination, false) || [];
  const options = ['<option value="start">No início da página</option>'];
  blocks.forEach((block, index) => {
    const label = block.label || HOME_BLOCK_TYPES[block.type] || block.type || `Bloco ${index + 1}`;
    options.push(`<option value="after:${escapeHtml(block.id)}" ${selected===`after:${block.id}`?'selected':''}>Depois de ${String(index+1).padStart(2,'0')} · ${escapeHtml(label)}</option>`);
  });
  options.push(`<option value="end" ${selected==='end'?'selected':''}>No final da página</option>`);
  return options.join('');
}
function renderComposerPageMap(destination='home') {
  const root = $('#composerPageMap');
  const position = $('#composerPosition');
  const blocks = composerArray(destination, false) || [];
  if (position) {
    const selected = position.value || 'end';
    position.innerHTML = composerPositionOptions(destination, selected);
    if (![...position.options].some((item)=>item.value===selected)) position.value='end';
  }
  if (!root) return;
  const destinationLabel = composerDestinations().find((item)=>item.id===destination)?.label || destination;
  root.innerHTML = `<strong>${escapeHtml(destinationLabel)}</strong><div>${blocks.map((block,index)=>`<span class="${block.visible===false?'is-hidden':''}"><b>${String(index+1).padStart(2,'0')}</b>${escapeHtml(block.label||HOME_BLOCK_TYPES[block.type]||block.type)}</span>`).join('') || '<i>Página vazia</i>'}</div>`;
}
function composerArray(destination, create=true){
  if(destination==='home'){ return normalizedHomeBlocks(); }
  if(destination.startsWith('category:')){ const id=destination.slice(9); const page=normalizedSectionPage(id); return page?.blocks || []; }
  if(destination.startsWith('page:')){ const id=destination.slice(5); const pages=normalizedCustomPages(); if(!pages[id]&&create)pages[id]={id,title:'Nova página',slug:`pagina-${id}`,visible:true,order:Object.keys(pages).length*10+10,sections:[]}; pages[id].sections ||= []; return pages[id].sections; }
  return [];
}
function persistComposerArray(destination,array){
  if(destination==='home'){ STATE.settings.site_builder.home.blocks=array; return; }
  if(destination.startsWith('category:')){ const id=destination.slice(9); const page=normalizedSectionPage(id); if(page){page.blocks=array;STATE.settings.site_builder.section_pages[id]=page;} return; }
  if(destination.startsWith('page:')){ const id=destination.slice(5); const pages=normalizedCustomPages(); if(pages[id])pages[id].sections=array; }
}
function composerSections(){
  const rows=[];
  const add=(dest,blocks)=>blocks.forEach((block,index)=>{ if(block?.type && !block.core && !['section_header','section_projects'].includes(block.type))rows.push({destination:dest,index,block}); });
  add('home',normalizedHomeBlocks()); topLevelCategories().forEach((cat)=>add(`category:${cat.id}`,normalizedSectionPage(cat.id)?.blocks||[])); Object.values(normalizedCustomPages()).forEach((page)=>add(`page:${page.id}`,page.sections||[]));
  return rows;
}
function findComposerSection(id){ return composerSections().find((row)=>String(row.block.id)===String(id)) || null; }
function adaptHomeEditorToComposer(html=''){ return String(html||'').replaceAll('data-home-field','data-composer-field').replaceAll('data-home-items','data-composer-items').replaceAll('data-home-item-row','data-composer-item-row').replaceAll('data-home-item-field','data-composer-item-field').replaceAll('data-home-content-picker','data-composer-content-picker').replaceAll('data-home-item-add','data-composer-item-add').replaceAll('data-home-item-up','data-composer-item-up').replaceAll('data-home-item-down','data-composer-item-down').replaceAll('data-home-item-remove','data-composer-item-remove'); }
function composerBlockEditor(block){ const html=`<label>Nome no editor<input data-composer-field="label" value="${escapeHtml(block.label||HOME_BLOCK_TYPES[block.type]||'Seção')}"></label>${customHomeBlockFields(block)}${homeTypographyFields(block)}${homeSectionLayoutFields(block)}`; return adaptHomeEditorToComposer(html); }
function renderSectionComposer(){
  const root=$('#sectionComposerList'); if(!root||!STATE.settings)return;
  const destinationSelect=$('#composerDestination');
  if(destinationSelect){ const current=destinationSelect.value||'home'; destinationSelect.innerHTML=composerDestinationOptions(current); if([...destinationSelect.options].some((o)=>o.value===current)) destinationSelect.value=current; renderComposerPageMap(destinationSelect.value||'home'); }
  const selectedDestination=destinationSelect?.value||'home';
  const sections=composerSections().filter((entry)=>entry.destination===selectedDestination);
  if(!sections.length){root.innerHTML='<div class="empty">Esta página ainda não possui seções adicionais. Escolha o tipo, a posição e clique “Inserir bloco”.</div>';return;}
  root.innerHTML=sections.map((entry)=>{const b=entry.block;const opened=STATE.openComposerSectionId===b.id;const isCarousel=['editorial_carousel','auto_carousel','autoplay_carousel'].includes(b.type);return `<article class="composer-section-row${opened?' is-open':''}" data-composer-id="${escapeHtml(b.id)}" data-composer-destination="${escapeHtml(entry.destination)}"><div class="composer-section-head"><span class="composer-index">${String(entry.index+1).padStart(2,'0')}</span><div><strong>${escapeHtml(b.label||HOME_BLOCK_TYPES[b.type]||b.type)}</strong><small>${escapeHtml(HOME_BLOCK_TYPES[b.type]||b.type)}${isCarousel?' · carrossel real · projetos selecionáveis':''}</small></div><label>Destino<select data-composer-destination-select>${composerDestinationOptions(entry.destination)}</select></label><label class="inline-check"><input type="checkbox" data-composer-visible ${b.visible!==false?'checked':''}> Visível</label><div class="composer-actions"><button type="button" data-composer-edit>${opened?'Fechar':'Editar'}</button><button type="button" data-composer-up>↑</button><button type="button" data-composer-down>↓</button><button type="button" class="danger" data-composer-remove>Remover</button></div></div><div class="composer-section-body" ${opened?'':'hidden'}><div class="fields composer-fields">${composerBlockEditor(b)}</div></div></article>`}).join('');
}
function addComposerSection(){
  const type=$('#composerSectionType')?.value||'auto_carousel';
  const destination=$('#composerDestination')?.value||'home';
  const position=$('#composerPosition')?.value||'end';
  if(!COMPOSER_SECTION_TYPES.includes(type))return;
  const block=newHomeBlock(type);if(!block)return;
  block.core=false;block.id=`section-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;block.label=HOME_BLOCK_TYPES[type]||'Seção';
  if(['auto_carousel','autoplay_carousel','editorial_carousel','editorial_blocks','editorial_gallery','highlights','horizontal_projects','related_projects'].includes(type)){block.content_mode='selected';block.items=block.items||[];}
  const arr=[...composerArray(destination)];
  let insertion=arr.length;
  if(position==='start') insertion=0;
  else if(position.startsWith('after:')) { const anchor=position.slice(6); const index=arr.findIndex((item)=>String(item.id)===anchor); insertion=index<0?arr.length:index+1; }
  arr.splice(insertion,0,block);
  persistComposerArray(destination,arr);STATE.openComposerSectionId=block.id;renderSectionComposer();queueAutoSave();refreshPreview();
  toast(`${block.label} inserido na posição ${insertion+1} de ${composerDestinations().find((d)=>d.id===destination)?.label||destination}`);
  if(['auto_carousel','autoplay_carousel','editorial_carousel','editorial_blocks','editorial_gallery','highlights','horizontal_projects','related_projects'].includes(type)) {
    setTimeout(()=>openSectionContentPicker(block.id,'composer'),0);
  }
}
function moveComposerSection(id,newDestination){const found=findComposerSection(id);if(!found||found.destination===newDestination)return;const source=[...composerArray(found.destination)];const idx=source.findIndex((b)=>b.id===id);if(idx<0)return;const [block]=source.splice(idx,1);persistComposerArray(found.destination,source);const target=[...composerArray(newDestination)];target.push(block);persistComposerArray(newDestination,target);renderSectionComposer();queueAutoSave();refreshPreview();}
function reorderComposerSection(id,direction){const found=findComposerSection(id);if(!found)return;const arr=[...composerArray(found.destination)];const i=arr.findIndex((b)=>b.id===id),j=i+direction;if(i<0||j<0||j>=arr.length)return;[arr[i],arr[j]]=[arr[j],arr[i]];persistComposerArray(found.destination,arr);renderSectionComposer();queueAutoSave();refreshPreview();}
function removeComposerSection(id){const found=findComposerSection(id);if(!found)return;const arr=[...composerArray(found.destination)].filter((b)=>b.id!==id);persistComposerArray(found.destination,arr);if(STATE.openComposerSectionId===id)STATE.openComposerSectionId='';renderSectionComposer();queueAutoSave();refreshPreview();}
function collectComposerRow(row){const id=row?.dataset.composerId;const found=findComposerSection(id);if(!found)return;const block=found.block;block.visible=row.querySelector('[data-composer-visible]')?.checked!==false;row.querySelectorAll('[data-composer-field]').forEach((input)=>{let value=input.value;const field=input.dataset.composerField;if(['autoplay','pause_on_hover','force_motion','muted','loop','controls','parallax','desktop_visible','mobile_visible','show_category','show_external_link','show_channel_link','section_reveal','section_navigation_visible','motion_enabled','component_state_enabled','wheel_navigation','decorative_lines','scroll_indicator','once','active','mouse_glow','floating','form_enabled','grayscale','indicators','progress','minimal_controls'].includes(field))value=value==='true';if(['section_texture_opacity','section_texture_scale','section_overlay_opacity','section_min_height','section_padding_top','section_padding_bottom','line_opacity','motion_duration','motion_delay','motion_stagger','component_hover_intensity','component_transition_ms','duration','delay','stagger','dot_size','dot_spacing','dot_opacity','wave_intensity','wave_radius','cols','strength','gradient_angle','speed','interval','perspective','depth','opacity','line_delay'].includes(field))value=Number(value||0);block[field]=value;});const itemRows=row.querySelectorAll('[data-composer-items] .home-section-item-row');if(itemRows.length||row.querySelector('[data-composer-items]')){block.items=[...itemRows].map((itemRow,i)=>{const item={id:itemRow.dataset.composerItemRow||`section-item-${i+1}`};itemRow.querySelectorAll('[data-composer-item-field]').forEach((input)=>item[input.dataset.composerItemField]=input.value||'');return item;});}persistComposerArray(found.destination,composerArray(found.destination));}
// V5.19 · Section Page Builder ------------------------------------------------
const SECTION_BLOCK_TYPES = {
  section_header: 'Cabeçalho da seção',
  section_projects: 'Projetos da categoria',
  showcase: HOME_BLOCK_TYPES.showcase,
  full_media: HOME_BLOCK_TYPES.full_media,
  split: HOME_BLOCK_TYPES.split,
  horizontal_projects: HOME_BLOCK_TYPES.horizontal_projects,
  related_projects: HOME_BLOCK_TYPES.related_projects,
  quote_cta: HOME_BLOCK_TYPES.quote_cta,
  auto_carousel: HOME_BLOCK_TYPES.auto_carousel,
  spotlight: HOME_BLOCK_TYPES.spotlight,
  marquee: HOME_BLOCK_TYPES.marquee,
  cta: HOME_BLOCK_TYPES.cta,
  text: HOME_BLOCK_TYPES.text,
  lettering_custom: HOME_BLOCK_TYPES.lettering_custom,
  video_feature: HOME_BLOCK_TYPES.video_feature,
  section_experience: HOME_BLOCK_TYPES.section_experience,
  textured_reveal: HOME_BLOCK_TYPES.textured_reveal,
};

function currentSectionPageId() {
  const selected = $('#sectionPageCategory')?.value || '';
  if (selected && topLevelCategories().some((item) => String(item.id) === String(selected))) return selected;
  return String(topLevelCategories()[0]?.id || '');
}

function sectionCategoryTitle(sectionId) {
  const category = topLevelCategories().find((item) => String(item.id) === String(sectionId));
  return category ? (configured(category.id).title || category.title || category.name || 'Categoria') : 'Categoria';
}

function adaptHomeEditorToSection(html='') {
  return String(html || '')
    .replaceAll('data-home-field', 'data-section-field')
    .replaceAll('data-home-items', 'data-section-items')
    .replaceAll('data-home-item-row', 'data-section-item-row')
    .replaceAll('data-home-item-field', 'data-section-item-field')
    .replaceAll('data-home-content-picker', 'data-section-content-picker')
    .replaceAll('data-home-item-add', 'data-section-item-add')
    .replaceAll('data-home-item-up', 'data-section-item-up')
    .replaceAll('data-home-item-down', 'data-section-item-down')
    .replaceAll('data-home-item-remove', 'data-section-item-remove');
}

function toggleSectionBlockInspector(blockId) {
  const root = $('#sectionBlockList');
  if (!root || !blockId) return;
  const next = STATE.openSectionBlockId === blockId ? '' : blockId;
  STATE.openSectionBlockId = next;
  root.querySelectorAll('.section-block-row').forEach((row) => {
    const open = row.dataset.sectionBlockId === next;
    row.classList.toggle('is-open', open);
    row.classList.toggle('is-collapsed', !open);
    const button = row.querySelector('[data-section-edit]');
    if (button) {
      button.textContent = open ? 'Fechar editor' : 'Editar conteúdo';
      button.classList.toggle('accent', open);
      button.setAttribute('aria-expanded', open ? 'true' : 'false');
    }
  });
}

function normalizedSectionPage(sectionId) {
  if (!sectionId) return null;
  STATE.settings ||= {};
  STATE.settings.site_builder ||= {};
  STATE.settings.site_builder.section_pages ||= {};
  const previous = STATE.settings.site_builder.section_pages[sectionId] || {};
  const headerId = `section-${sectionId}-header`;
  const projectsId = `section-${sectionId}-projects`;
  const configuredBlocks = Array.isArray(previous.blocks) ? previous.blocks : [];
  const blocks = [];
  const seen = new Set();
  configuredBlocks.forEach((source, index) => {
    if (!source || typeof source !== 'object') return;
    const type = String(source.type || '').trim();
    if (!SECTION_BLOCK_TYPES[type]) return;
    let id = String(source.id || '').trim() || `section-block-${Date.now()}-${index}`;
    if (seen.has(id)) id = `${id}-${index}`;
    seen.add(id);
    const core = id === headerId || id === projectsId || Boolean(source.core && ['section_header','section_projects'].includes(type));
    blocks.push({ ...source, id, type, core });
  });
  if (!blocks.some((block) => block.id === headerId)) blocks.unshift({ id:headerId, type:'section_header', label:'Cabeçalho', visible:true, core:true });
  if (!blocks.some((block) => block.id === projectsId)) blocks.push({ id:projectsId, type:'section_projects', label:'Projetos da categoria', visible:true, core:true });
  const page = {
    ...previous,
    enabled: previous.enabled !== false,
    header_visible: previous.header_visible !== false,
    eyebrow: Object.prototype.hasOwnProperty.call(previous,'eyebrow') ? String(previous.eyebrow??'') : 'Categoria',
    title: Object.prototype.hasOwnProperty.call(previous,'title') ? String(previous.title??'') : sectionCategoryTitle(sectionId),
    body: previous.body || '',
    blocks,
  };
  STATE.settings.site_builder.section_pages[sectionId] = page;
  return page;
}

function renderSectionPageCategoryOptions() {
  const select = $('#sectionPageCategory');
  if (!select) return '';
  const previous = STATE.sectionPageEditorId || select.value || currentSectionPageId();
  const categories = topLevelCategories();
  select.innerHTML = categories.map((category) => {
    const title = configured(category.id).title || category.title || category.name || 'Categoria';
    return `<option value="${escapeHtml(category.id)}">${escapeHtml(title)}</option>`;
  }).join('');
  const chosen = categories.some((item) => String(item.id) === String(previous)) ? previous : String(categories[0]?.id || '');
  select.value = chosen;
  STATE.sectionPageEditorId = chosen;
  return chosen;
}

function sectionBlockFields(block, sectionId) {
  if (block.type === 'section_header') {
    const page=STATE.settings?.site_builder?.section_pages?.[sectionId]||{};
    const titleSize=escapeHtml(block.title_size||'');
    const eyebrowSize=escapeHtml(block.eyebrow_size||'');
    const weight=String(block.title_weight||'400');
    const align=block.text_align||'left';
    const background=block.section_background||'none';
    const width=block.section_width||'full';
    return `<div class="wide section-header-direct-editor">
      <div class="wide service-quote-admin-divider"><strong>Título / cabeçalho desta seção</strong><small>Edite aqui o que aparece no card de cabeçalho desta categoria. Cada categoria tem seus próprios valores.</small></div>
      <label class="wide inline-check section-header-visible-control"><input type="checkbox" data-section-page-field="header_visible" ${page.header_visible!==false?'checked':''}> Exibir cabeçalho desta categoria</label>
      <label>Eyebrow<input data-section-page-field="eyebrow" value="${escapeHtml(page.eyebrow??'')}" placeholder="Ex.: Categoria"></label>
      <label>Título público<input data-section-page-field="title" value="${escapeHtml(page.title??'')}" placeholder="Ex.: Banners"></label>
      <label class="wide">Descrição / introdução<textarea data-section-page-field="body" placeholder="Texto opcional">${escapeHtml(page.body||'')}</textarea></label>
      <label>Tamanho do título (px)<input type="number" min="12" max="180" step="1" data-section-header-field="title_size" value="${titleSize}" placeholder="Automático · máximo 64"></label>
      <label>Tamanho do eyebrow (px)<input type="number" min="5" max="48" step="1" data-section-header-field="eyebrow_size" value="${eyebrowSize}" placeholder="Automático"></label>
      <label>Peso do título<select data-section-header-field="title_weight"><option value="300" ${weight==='300'?'selected':''}>Light · 300</option><option value="400" ${weight==='400'?'selected':''}>Regular · 400</option><option value="500" ${weight==='500'?'selected':''}>Medium · 500</option><option value="600" ${weight==='600'?'selected':''}>Semibold · 600</option><option value="700" ${weight==='700'?'selected':''}>Bold · 700</option></select></label>
      <label>Alinhamento<select data-section-header-field="text_align"><option value="left" ${align==='left'?'selected':''}>Esquerda</option><option value="center" ${align==='center'?'selected':''}>Centro</option><option value="right" ${align==='right'?'selected':''}>Direita</option></select></label>
      <label>Fundo<select data-section-header-field="section_background"><option value="none" ${background==='none'?'selected':''}>Sem fundo adicional</option><option value="surface" ${background==='surface'?'selected':''}>Superfície</option><option value="soft" ${background==='soft'?'selected':''}>Suave</option><option value="accent" ${background==='accent'?'selected':''}>Destaque</option></select></label>
      <label>Largura<select data-section-header-field="section_width"><option value="full" ${width==='full'?'selected':''}>Largura total</option><option value="wide" ${width==='wide'?'selected':''}>Amplo</option><option value="content" ${width==='content'?'selected':''}>Conteúdo</option></select></label>
      <div class="wide home-block-core-note">Se Eyebrow, Título e Descrição estiverem vazios, o cabeçalho inteiro desaparece — sem bloco branco.</div>
    </div>${adaptHomeEditorToSection(homeSectionLayoutFields(block))}`;
  }
  if (block.type === 'section_projects') {
    const columns = String(block.grid_columns || '3');
    const ratio = block.card_ratio || '4x3';
    const gap = block.grid_gap || 'normal';
    return `<div class="wide home-editor-subgroup home-content-editor"><strong>Grid da categoria</strong><div class="home-content-grid">
      <label>Colunas no desktop<select data-section-field="grid_columns"><option value="2" ${columns==='2'?'selected':''}>2 colunas</option><option value="3" ${columns==='3'?'selected':''}>3 colunas</option><option value="4" ${columns==='4'?'selected':''}>4 colunas</option></select></label>
      <label>Proporção das capas<select data-section-field="card_ratio"><option value="4x3" ${ratio==='4x3'?'selected':''}>4:3</option><option value="1x1" ${ratio==='1x1'?'selected':''}>1:1</option><option value="4x5" ${ratio==='4x5'?'selected':''}>4:5</option><option value="16x9" ${ratio==='16x9'?'selected':''}>16:9</option></select></label>
      <label>Espaçamento<select data-section-field="grid_gap"><option value="compact" ${gap==='compact'?'selected':''}>Compacto</option><option value="normal" ${gap==='normal'?'selected':''}>Normal</option><option value="wide" ${gap==='wide'?'selected':''}>Amplo</option></select></label>
      <div class="wide home-block-core-note">A ordem deste grid segue a ordem dos projetos no Media Manager. Para mostrar apenas alguns itens e ordenar manualmente, use Carrossel de projetos ou Projetos horizontais.</div>
    </div></div>${adaptHomeEditorToSection(homeSectionLayoutFields(block))}`;
  }
  const prepared = { ...block };
  if (['horizontal_projects','auto_carousel'].includes(prepared.type) && !prepared.category_id) prepared.category_id = sectionId;
  const content = adaptHomeEditorToSection(customHomeBlockFields(prepared));
  const typography = adaptHomeEditorToSection(homeTypographyFields(prepared));
  const layout = adaptHomeEditorToSection(homeSectionLayoutFields(prepared));
  return `<label>Nome no editor<input data-section-field="label" value="${escapeHtml(block.label || SECTION_BLOCK_TYPES[block.type] || 'Bloco')}"></label>${content}${typography}${layout}`;
}

function collectSectionPageFromEditor(sectionIdOverride = '') {
  if(!STATE.renderedPanels?.has('categorypages')) return;
  if(!sectionIdOverride && activeEditorPanelName()!=='categorypages') return;
  const sectionId = sectionIdOverride || STATE.sectionPageEditorId || currentSectionPageId();
  const root = $('#sectionBlockList');
  if (!sectionId || !root) return;
  const page = normalizedSectionPage(sectionId);
  if (!page) return;
  page.enabled = $('#sectionPageEnabled')?.checked !== false;
  const directHeader=root.querySelector('.section-block-row[data-section-block-type="section_header"]');
  const directPageField=(name)=>directHeader?.querySelector(`[data-section-page-field="${name}"]`)||null;
  const directVisible=directPageField('header_visible');
  page.header_visible = directVisible ? directVisible.checked : ($('#sectionPageHeaderVisible')?.checked !== false);
  page.eyebrow = directPageField('eyebrow')?.value ?? ($('#sectionPageEyebrow')?.value ?? '');
  page.title = directPageField('title')?.value ?? ($('#sectionPageTitle')?.value ?? '');
  page.body = directPageField('body')?.value ?? ($('#sectionPageBody')?.value || '');
  const current = new Map(page.blocks.map((block) => [block.id, block]));
  const output = [];
  root.querySelectorAll('.section-block-row').forEach((row) => {
    const id = row.dataset.sectionBlockId;
    const previous = current.get(id) || { id, type: row.dataset.sectionBlockType };
    const block = { ...previous, id, type: row.dataset.sectionBlockType };
    const visible = row.querySelector('[data-section-visible]');
    if (visible) block.visible = visible.checked;
    row.querySelectorAll('[data-section-field]').forEach((input) => {
      const field = input.dataset.sectionField;
      let value = input.value;
      if (['autoplay','pause_on_hover','force_motion','muted','loop','parallax','desktop_visible','mobile_visible','show_category','show_external_link','show_channel_link','section_reveal','section_navigation_visible','motion_enabled','wheel_navigation','decorative_lines','scroll_indicator','once','active','mouse_glow','floating','form_enabled','grayscale','indicators','progress','minimal_controls'].includes(field)) value = value === 'true';
      if(['section_texture_opacity','section_texture_scale','section_overlay_opacity','section_min_height','section_padding_top','section_padding_bottom','line_opacity','motion_duration','motion_delay','motion_stagger','duration','delay','stagger','dot_size','dot_spacing','dot_opacity','wave_intensity','wave_radius','cols','strength','gradient_angle','speed','interval','perspective','depth','opacity','line_delay'].includes(field))value=Number(value||0);
      block[field] = value;
    });
    const itemRows = row.querySelectorAll('[data-section-items] .home-section-item-row');
    if (itemRows.length || row.querySelector('[data-section-items]')) {
      block.items = [...itemRows].map((itemRow, itemIndex) => {
        const item = { id: itemRow.dataset.sectionItemRow || `section-item-${itemIndex+1}` };
        itemRow.querySelectorAll('[data-section-item-field]').forEach((input) => { item[input.dataset.sectionItemField] = input.value || ''; });
        return item;
      });
    }
    output.push(block);
  });
  const headerBlock = output.find((block) => block.type === 'section_header' || block.id === `section-${sectionId}-header`);
  if (headerBlock) {
    const clampOptional = (selector, min, max) => {
      const raw = String($(selector)?.value ?? '').trim();
      if (!raw) return '';
      const value = Number(raw);
      return Number.isFinite(value) ? Math.max(min, Math.min(max, value)) : '';
    };
    const directHeaderValue=(field)=>directHeader?.querySelector(`[data-section-header-field="${field}"]`)||null;
    const clampDirect=(field, selector, min, max) => {
      const direct=directHeaderValue(field); const raw=String(direct ? direct.value : ($(selector)?.value ?? '')).trim();
      if(!raw)return ''; const value=Number(raw); return Number.isFinite(value)?Math.max(min,Math.min(max,value)):'';
    };
    headerBlock.title_size = clampDirect('title_size','#sectionPageTitleSize',12,180);
    headerBlock.eyebrow_size = clampDirect('eyebrow_size','#sectionPageEyebrowSize',5,48);
    headerBlock.title_weight = directHeaderValue('title_weight')?.value || $('#sectionPageTitleWeight')?.value || '400';
    headerBlock.text_align = directHeaderValue('text_align')?.value || $('#sectionPageTextAlign')?.value || 'left';
    headerBlock.section_background = directHeaderValue('section_background')?.value || $('#sectionPageHeaderBackground')?.value || 'none';
    headerBlock.section_width = directHeaderValue('section_width')?.value || $('#sectionPageHeaderWidth')?.value || 'full';
  }
  page.blocks = output;
  STATE.settings.site_builder.section_pages[sectionId] = page;
}

function renderSectionPageEditor() {
  const root = $('#sectionBlockList');
  if (!root) return;
  const sectionId = renderSectionPageCategoryOptions();
  if (!sectionId) {
    root.innerHTML = '<div class="empty">Sincronize o Drive para criar páginas de categoria.</div>';
    return;
  }
  const page = normalizedSectionPage(sectionId);
  $('#sectionPageEnabled').checked = page.enabled !== false;
  if($('#sectionPageHeaderVisible'))$('#sectionPageHeaderVisible').checked = page.header_visible !== false;
  $('#sectionPageEyebrow').value = page.eyebrow ?? '';
  $('#sectionPageTitle').value = page.title ?? '';
  $('#sectionPageBody').value = page.body || '';
  const headerBlock = page.blocks.find((block) => block.type === 'section_header' || block.id === `section-${sectionId}-header`) || {};
  if ($('#sectionPageTitleSize')) $('#sectionPageTitleSize').value = headerBlock.title_size || '';
  if ($('#sectionPageEyebrowSize')) $('#sectionPageEyebrowSize').value = headerBlock.eyebrow_size || '';
  if ($('#sectionPageTitleWeight')) $('#sectionPageTitleWeight').value = String(headerBlock.title_weight || '400');
  if ($('#sectionPageTextAlign')) $('#sectionPageTextAlign').value = headerBlock.text_align || 'left';
  if ($('#sectionPageHeaderBackground')) $('#sectionPageHeaderBackground').value = headerBlock.section_background || 'none';
  if ($('#sectionPageHeaderWidth')) $('#sectionPageHeaderWidth').value = headerBlock.section_width || 'full';
  root.replaceChildren();
  if (!STATE.openSectionBlockId && page.blocks.length) STATE.openSectionBlockId = page.blocks[0].id;
  page.blocks.forEach((block, index) => {
    const core = Boolean(block.core || ['section_header','section_projects'].includes(block.type));
    const row = document.createElement('article');
    row.className = `home-block-row section-block-row${block.visible === false ? ' is-hidden' : ''}${STATE.openSectionBlockId === block.id ? ' is-open' : ' is-collapsed'}`;
    row.dataset.sectionBlockId = block.id;
    row.dataset.sectionBlockType = block.type;
    row.draggable = true;
    row.innerHTML = `
      <div class="home-block-main">
        <span class="home-block-handle">⋮⋮</span>
        <div class="home-block-title"><strong>${escapeHtml(block.type==='section_header'?'Cabeçalho / título da categoria':(block.label || SECTION_BLOCK_TYPES[block.type] || 'Bloco'))}</strong><span class="home-block-type">${escapeHtml(SECTION_BLOCK_TYPES[block.type] || block.type)}</span></div>
        <div class="home-block-actions">
          <label class="inline-check"><input type="checkbox" data-section-visible ${block.visible !== false ? 'checked' : ''}> Visível</label>
          <button type="button" data-section-edit="${escapeHtml(block.id)}" aria-expanded="${STATE.openSectionBlockId === block.id ? 'true' : 'false'}" class="${STATE.openSectionBlockId === block.id ? 'accent' : ''}">${STATE.openSectionBlockId === block.id ? 'Fechar editor' : (block.type==='section_header'?'Editar título':'Editar conteúdo')}</button>
          <button type="button" data-section-up="${escapeHtml(block.id)}" ${index === 0 ? 'disabled' : ''}>↑</button>
          <button type="button" data-section-down="${escapeHtml(block.id)}" ${index === page.blocks.length - 1 ? 'disabled' : ''}>↓</button>
          <button type="button" data-section-duplicate="${escapeHtml(block.id)}" ${core ? 'disabled title="Blocos-base são únicos"' : ''}>Duplicar</button>
          <button type="button" data-section-delete="${escapeHtml(block.id)}" ${core ? 'disabled title="Bloco estrutural protegido"' : ''}>Excluir</button>
        </div>
      </div>
      <div class="home-block-settings">${sectionBlockFields(block, sectionId)}</div>`;
    root.append(row);
  });
}

function newSectionBlock(type, sectionId) {
  const block = newHomeBlock(type);
  block.id = `section-block-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;
  block.label = SECTION_BLOCK_TYPES[type] || block.label || 'Bloco';
  if (['horizontal_projects','auto_carousel','related_projects'].includes(type)) {
    block.category_id = sectionId;
    block.content_mode = 'selected';
    block.items = [];
    block.body = block.body || '';
  }
  return block;
}

function mutateSectionBlocks(mutator) {
  collectSectionPageFromEditor();
  const sectionId = currentSectionPageId();
  const page = normalizedSectionPage(sectionId);
  if (!page) return;
  const blocks = [...page.blocks];
  const before = new Set(blocks.map((block)=>block.id));
  mutator(blocks);
  const added = blocks.find((block)=>!before.has(block.id));
  if (added) STATE.openSectionBlockId = added.id;
  if (STATE.openSectionBlockId && !blocks.some((block)=>block.id===STATE.openSectionBlockId)) STATE.openSectionBlockId = blocks[0]?.id || '';
  page.blocks = blocks;
  STATE.settings.site_builder.section_pages[sectionId] = page;
  renderSectionPageEditor();
  queueAutoSave();
}

function moveSectionBlock(id, direction) {
  mutateSectionBlocks((blocks) => {
    const index = blocks.findIndex((block) => block.id === id);
    const target = index + direction;
    if (index < 0 || target < 0 || target >= blocks.length) return;
    [blocks[index], blocks[target]] = [blocks[target], blocks[index]];
  });
}

function duplicateSectionBlock(id) {
  mutateSectionBlocks((blocks) => {
    const index = blocks.findIndex((block) => block.id === id);
    if (index < 0 || blocks[index].core) return;
    const copy = { ...blocks[index], id:`section-block-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`, label:`${blocks[index].label || SECTION_BLOCK_TYPES[blocks[index].type]} · cópia` };
    blocks.splice(index + 1, 0, copy);
  });
}

function deleteSectionBlock(id) {
  mutateSectionBlocks((blocks) => {
    const index = blocks.findIndex((block) => block.id === id);
    if (index >= 0) blocks.splice(index, 1);
  });
}

function mutateSectionPageItems(blockId, mutator) {
  collectSectionPageFromEditor();
  const sectionId = currentSectionPageId();
  const page = normalizedSectionPage(sectionId);
  if (!page) return;
  const block = page.blocks.find((item)=>item.id===blockId);
  if (!block) return;
  const items = normalizedEditorialItems(block);
  mutator(items);
  block.items = items;
  block.content_mode = 'selected';
  STATE.settings.site_builder.section_pages[sectionId] = page;
  STATE.openSectionBlockId = blockId;
  renderSectionPageEditor();
  queueAutoSave();
}

function addSectionPageItem(blockId) {
  mutateSectionPageItems(blockId, (items)=>items.push({id:`section-item-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,5)}`,project_id:'',media_id:'',title:'',description:'',action_label:''}));
}
function moveSectionPageItem(blockId,itemId,direction) {
  mutateSectionPageItems(blockId,(items)=>{const index=items.findIndex((item)=>item.id===itemId);const target=index+direction;if(index<0||target<0||target>=items.length)return;[items[index],items[target]]=[items[target],items[index]];});
}
function removeSectionPageItem(blockId,itemId) {
  mutateSectionPageItems(blockId,(items)=>{const index=items.findIndex((item)=>item.id===itemId);if(index>=0)items.splice(index,1);});
}

function seoSettingsRoot(){STATE.settings.site_builder ||= {};const root=STATE.settings.site_builder.seo ||= {};root.version=2;root.projects_slug ||= 'projetos';root.title_suffix ||= STATE.settings.identity?.studio_name||'MENSAGEM STUDIO';root.language ||= 'pt-BR';root.locale ||= String(root.language||'pt-BR').replace('-','_');root.structured_data_enabled=root.structured_data_enabled!==false;root.breadcrumbs_enabled=root.breadcrumbs_enabled!==false;root.social_cards_enabled=root.social_cards_enabled!==false;root.sitemap_enabled=root.sitemap_enabled!==false;root.robots_enabled=root.robots_enabled!==false;root.llms_txt_enabled=root.llms_txt_enabled===true;root.search_console_verification ||= '';root.organization ||= {};root.organization.type ||= 'Organization';root.organization.name ||= STATE.settings.identity?.studio_name||'Mensagem Studio';root.organization.url ||= String(STATE.settings.identity?.public_url||'').replace(/\/+$/,'');root.organization.logo_media_id ||= '';root.organization.same_as=Array.isArray(root.organization.same_as)?root.organization.same_as:[];root.home ||= {};return root;}
function seoEntityRecords(){
  const out=[{key:'home',kind:'home',label:'Home',title:STATE.settings.identity?.portfolio_title||'Portfólio',description:STATE.settings.identity?.description||'',path:''}];
  const services=servicesState();out.push({key:'services',kind:'services',label:'Serviços · página principal',title:services.title||'Serviços',description:services.intro||'',path:services.slug||'servicos'});
  const briefing=briefingState();out.push({key:'briefing',kind:'briefing',briefing,label:'Briefing · página pública',title:briefing.title||'Briefing',description:briefing.description||briefing.intro||'',path:briefing.slug||'briefing'});
  (services.categories||[]).forEach((category)=>(category.services||[]).forEach((item)=>out.push({key:`service:${category.id}:${item.id}`,kind:'service',category,item,label:`Serviço · ${item.title||item.id}`,title:item.page_title||item.title||'Serviço',description:item.page_intro||item.description||'',path:item.full_path||`${services.slug||'servicos'}/${item.slug||slugifyPage(item.title||item.id)}`})));
  Object.values(normalizedCustomPages()).forEach((page)=>out.push({key:`page:${page.id}`,kind:'page',page,label:`Página · ${page.title}`,title:page.title||'Página',description:page.intro||page.body||'',path:page.full_path||customPageFullPath(page.id)}));
  topLevelCategories().forEach((category)=>{const cfg=(STATE.settings.site_builder?.section_pages||{})[category.id]||{};out.push({key:`category:${category.id}`,kind:'category',category,label:`Categoria · ${configured(category.id).title||category.title||category.name}`,title:cfg.title||configured(category.id).title||category.title||category.name,description:cfg.body||configured(category.id).description||'',path:`${seoSettingsRoot().projects_slug||'projetos'}/${slugifyPage((cfg.seo||{}).slug||configured(category.id).title||category.title||category.name)}`});});
  (STATE.projectEntities||[]).forEach((entity)=>{const cat=entity.category;const catTitle=configured(cat?.id).title||cat?.title||cat?.name||'categoria';out.push({key:`project:${entity.drive_id}`,kind:'project',entity,label:`Projeto · ${entity.title||entity.name}`,title:entity.title||entity.name,description:entity.description||'',path:`${seoSettingsRoot().projects_slug||'projetos'}/${slugifyPage(catTitle)}/${slugifyPage(entity.title||entity.name)}`});});
  return out;
}
function seoEntityConfig(record,create=true){if(!record)return{};const builder=STATE.settings.site_builder||{};if(record.kind==='home'){const root=seoSettingsRoot();if(create)root.home ||= {};return root.home||{};}if(record.kind==='services'){const services=servicesState();if(create)services.seo ||= {};return services.seo||{};}if(record.kind==='briefing'){const briefing=briefingState();if(create)briefing.seo ||= {index:false,follow:true};return briefing.seo||{};}if(record.kind==='service'){if(create)record.item.seo ||= {};return record.item.seo||{};}if(record.kind==='page'){if(create)record.page.seo ||= {};return record.page.seo||{};}if(record.kind==='category'){builder.section_pages ||= {};builder.section_pages[record.category.id] ||= {};if(create)builder.section_pages[record.category.id].seo ||= {};return builder.section_pages[record.category.id].seo||{};}if(record.kind==='project'){const entity=record.entity;if(entity.kind==='folder-project'){STATE.settings.project_sections ||= {};STATE.settings.project_sections[entity.drive_id] ||= {};if(create)STATE.settings.project_sections[entity.drive_id].seo ||= {};return STATE.settings.project_sections[entity.drive_id].seo||{};}STATE.settings.projects ||= {};STATE.settings.projects[entity.drive_id] ||= {};if(create)STATE.settings.projects[entity.drive_id].seo ||= {};return STATE.settings.projects[entity.drive_id].seo||{};}return{};}
