function seoEffectiveSlug(record,cfg={}){
  if(!record||record.kind==='home')return'';
  if(record.kind==='services')return slugifyPage(servicesState().slug||'servicos');
  if(record.kind==='briefing')return slugifyPage(record.briefing?.slug||'briefing');
  if(record.kind==='service')return slugifyPage(record.item?.slug||record.item?.title||record.item?.id||'servico');
  if(record.kind==='page')return slugifyPage(record.page?.slug||record.page?.title||record.page?.id||'pagina');
  if(record.kind==='category')return slugifyPage(cfg.slug||configured(record.category?.id).title||record.category?.title||record.category?.name||record.category?.id||'categoria');
  if(record.kind==='project')return slugifyPage(cfg.slug||record.entity?.title||record.entity?.name||record.entity?.drive_id||'projeto');
  return slugifyPage(cfg.slug||'pagina');
}
function seoCategoryRouteSlug(category){
  if(!category)return'categoria';
  const page=(STATE.settings.site_builder?.section_pages||{})[category.id]||{};
  return slugifyPage((page.seo||{}).slug||configured(category.id).title||category.title||category.name||category.id||'categoria');
}
function seoRecordPath(record,cfg={}){
  if(!record||record.kind==='home')return'';
  const projectsRoot=slugifyPage(seoSettingsRoot().projects_slug||'projetos');
  if(record.kind==='services')return seoEffectiveSlug(record,cfg)||'servicos';
  if(record.kind==='briefing')return seoEffectiveSlug(record,cfg)||'briefing';
  if(record.kind==='service')return`${slugifyPage(servicesState().slug||'servicos')}/${seoEffectiveSlug(record,cfg)}`;
  if(record.kind==='page')return customPageFullPath(record.page?.id)||seoEffectiveSlug(record,cfg);
  if(record.kind==='category')return`${projectsRoot}/${seoEffectiveSlug(record,cfg)}`;
  if(record.kind==='project')return`${projectsRoot}/${seoCategoryRouteSlug(record.entity?.category)}/${seoEffectiveSlug(record,cfg)}`;
  return String(record.path||'').replace(/^\/+|\/+$/g,'');
}
function seoPreviewCanonical(record,cfg={}){
  const base=String(STATE.settings.identity?.public_url||'https://mensagemstudio.shop/').replace(/\/+$/,'');
  const path=seoRecordPath(record,cfg);
  const automatic=`${base}/${path?path+'/':''}`;
  const manual=String(cfg.canonical||'').trim();
  if(!manual)return{url:automatic,status:'automático'};
  try{
    const requested=new URL(manual),origin=new URL(base);
    if(requested.protocol.match(/^https?:$/)&&requested.host.toLowerCase()===origin.host.toLowerCase())return{url:manual,status:'manual'};
  }catch(_err){}
  return{url:automatic,status:'override inválido ignorado'};
}
function seoSchemaAutoFor(record){return({home:'WebPage',services:'CollectionPage',service:'Service',briefing:'WebPage',page:'WebPage',category:'CollectionPage',project:'CreativeWork'})[record?.kind]||'WebPage';}
function seoGlobalMediaOptions(selected=''){return seoMediaOptions(selected).replace('Automática · usar capa/poster','Sem logo específico');}
function seoAuditRows(){const rows=seoEntityRecords();return rows.map((record)=>{const cfg=seoEntityConfig(record,false)||{},canonical=seoPreviewCanonical(record,cfg),title=cfg.title||record.title||'',description=cfg.description||record.description||'',issues=[];if(title.length<24)issues.push('título curto');if(title.length>70)issues.push('título longo');if(description&&description.length<70)issues.push('descrição curta');if(description.length>180)issues.push('descrição longa');if(!cfg.image_media_id)issues.push('imagem automática');if(canonical.status.includes('inválido'))issues.push('canonical inválido');if(cfg.index===false)issues.push('noindex');return{record,cfg,title,description,canonical,issues};});}
function renderSeoAudit(){const rows=seoAuditRows(),root=seoSettingsRoot(),warn=rows.filter((row)=>row.issues.some((x)=>!['imagem automática','noindex'].includes(x))).length,noindex=rows.filter((row)=>row.cfg.index===false).length;const summary=$('#seoAuditSummary');if(summary)summary.innerHTML=`<div><strong>${rows.length}</strong><span>rotas</span></div><div><strong>${rows.length-noindex}</strong><span>indexáveis</span></div><div><strong>${noindex}</strong><span>noindex</span></div><div><strong>${warn}</strong><span>revisar</span></div>`;const list=$('#seoAuditList');if(list)list.innerHTML=rows.map(({record,cfg,canonical,issues})=>`<article class="seo-audit-row"><div><strong>${escapeHtml(record.label)}</strong><small>${escapeHtml('/'+seoRecordPath(record,cfg)+(seoRecordPath(record,cfg)?'/':''))}</small></div><span class="${issues.some((x)=>!['imagem automática','noindex'].includes(x))?'warn':'ok'}">${escapeHtml(issues.length?issues.join(' · '):'pronto')}</span><small>${escapeHtml(canonical.status)} · ${escapeHtml(cfg.schema_type||seoSchemaAutoFor(record))}</small></article>`).join('');const note=$('#seoAuditEditor .muted');if(note)note.textContent=`Sitemap ${root.sitemap_enabled?'ativo':'desativado'} · JSON-LD ${root.structured_data_enabled?'ativo':'desativado'}`;}
function renderSeoGlobalEditor(){const root=seoSettingsRoot(),org=root.organization||{};const set=(id,value)=>{const el=$('#'+id);if(el)el.value=value??'';},check=(id,value)=>{const el=$('#'+id);if(el)el.checked=value!==false;};set('seoTitleSuffix',root.title_suffix);set('seoProjectsSlug',root.projects_slug);set('seoLanguage',root.language);set('seoLocale',root.locale);set('seoSearchConsoleVerification',root.search_console_verification);set('seoOrgType',org.type||'Organization');set('seoOrgName',org.name||'');set('seoOrgUrl',org.url||'');set('seoOrgSameAs',(org.same_as||[]).join('\n'));const logo=$('#seoOrgLogoMedia');if(logo)logo.innerHTML=seoGlobalMediaOptions(org.logo_media_id||'');check('seoStructuredEnabled',root.structured_data_enabled);check('seoBreadcrumbsEnabled',root.breadcrumbs_enabled);check('seoSocialCardsEnabled',root.social_cards_enabled);check('seoSitemapEnabled',root.sitemap_enabled);check('seoRobotsEnabled',root.robots_enabled);const llms=$('#seoLlmsEnabled');if(llms)llms.checked=root.llms_txt_enabled===true;}
function collectSeoGlobalEditor(){const root=seoSettingsRoot(),val=(id,f='')=>$('#'+id)?.value?.trim()??f;root.title_suffix=val('seoTitleSuffix',root.title_suffix)||STATE.settings.identity?.studio_name||'Mensagem Studio';root.projects_slug=slugifyPage(val('seoProjectsSlug',root.projects_slug)||'projetos');root.language=val('seoLanguage','pt-BR')||'pt-BR';root.locale=val('seoLocale',String(root.language).replace('-','_'))||String(root.language).replace('-','_');root.search_console_verification=val('seoSearchConsoleVerification','');root.structured_data_enabled=$('#seoStructuredEnabled')?.checked!==false;root.breadcrumbs_enabled=$('#seoBreadcrumbsEnabled')?.checked!==false;root.social_cards_enabled=$('#seoSocialCardsEnabled')?.checked!==false;root.sitemap_enabled=$('#seoSitemapEnabled')?.checked!==false;root.robots_enabled=$('#seoRobotsEnabled')?.checked!==false;root.llms_txt_enabled=$('#seoLlmsEnabled')?.checked===true;root.organization ||= {};root.organization.type=['Organization','ProfessionalService','Person'].includes(val('seoOrgType','Organization'))?val('seoOrgType','Organization'):'Organization';root.organization.name=val('seoOrgName',STATE.settings.identity?.studio_name||'Mensagem Studio');root.organization.url=val('seoOrgUrl',String(STATE.settings.identity?.public_url||'')).replace(/\/+$/,'');root.organization.logo_media_id=$('#seoOrgLogoMedia')?.value||'';root.organization.same_as=val('seoOrgSameAs','').split(/\n+/).map((x)=>x.trim()).filter((x)=>{try{const u=new URL(x);return/^https?:$/.test(u.protocol)}catch(_){return false}}).filter((x,i,a)=>a.indexOf(x)===i).slice(0,24);renderSeoAudit();return root;}
function renderSeoPreview(record,cfg){
  if(!record)return;
  const suffix=seoSettingsRoot().title_suffix||STATE.settings.identity?.studio_name||'Mensagem Studio';
  const sourceTitle=cfg.title||record.title||'Página';
  const title=cfg.title?sourceTitle:(String(sourceTitle).toLowerCase().includes(String(suffix).toLowerCase())?sourceTitle:`${sourceTitle} | ${suffix}`);
  const description=cfg.description||record.description||'';
  const canonical=seoPreviewCanonical(record,cfg),schema=cfg.schema_type||seoSchemaAutoFor(record);
  $('#seoPreviewTitle').textContent=title;
  $('#seoPreviewUrl').textContent=canonical.url;
  $('#seoPreviewDescription').textContent=description||'Descrição automática será derivada do conteúdo da página.';
  $('#seoPreviewDiagnostics').textContent=`Título: ${title.length} caracteres · Descrição: ${description.length} · Canonical: ${canonical.status} · Indexação: ${cfg.index===false?'Não':'Permitida'} · Schema: ${schema} · Imagem social: ${cfg.image_media_id?'definida':'automática'}`;
}
function renderSeoEditor(){
  const select=$('#seoEntitySelect');if(!select)return;
  renderSeoGlobalEditor();
  const rows=seoEntityRecords(),current=String(STATE.activeSeoEntity||select.value||'home');
  select.innerHTML=rows.map((row)=>`<option value="${escapeHtml(row.key)}">${escapeHtml(row.label)}</option>`).join('');
  select.value=rows.some((row)=>row.key===current)?current:(rows[0]?.key||'');STATE.activeSeoEntity=select.value;
  const record=activeSeoRecord(),cfg=seoEntityConfig(record,false)||{},slugField=$('#seoSlug');
  $('#seoTitle').value=cfg.title||'';$('#seoDescription').value=cfg.description||'';
  slugField.value=seoEffectiveSlug(record,cfg);slugField.disabled=record?.kind==='home';slugField.placeholder=record?.kind==='home'?'Home usa a raiz do domínio':'Slug da rota pública';
  $('#seoCanonical').value=cfg.canonical||'';$('#seoIndex').checked=cfg.index!==false;$('#seoFollow').checked=cfg.follow!==false;
  $('#seoSchemaType').value=cfg.schema_type||'';$('#seoImageMedia').innerHTML=seoMediaOptions(cfg.image_media_id||'');renderSeoPreview(record,cfg);renderSeoAudit();
}
function collectSeoEditor(){
  collectSeoGlobalEditor();
  const record=activeSeoRecord();if(!record)return;
  const cfg=seoEntityConfig(record,true),slugInput=$('#seoSlug')?.value?.trim()||'',slug=slugInput?slugifyPage(slugInput):'';
  cfg.title=$('#seoTitle')?.value?.trim()||'';cfg.description=$('#seoDescription')?.value?.trim()||'';
  if(record.kind==='home')cfg.slug='';
  else if(record.kind==='services'){if(slug)servicesState().slug=slug;cfg.slug='';}
  else if(record.kind==='briefing'){if(slug)briefingState().slug=slug;cfg.slug='';}
  else if(record.kind==='service'){if(slug)record.item.slug=slug;cfg.slug='';}
  else if(record.kind==='page'){if(slug)record.page.slug=slug;cfg.slug='';}
  else cfg.slug=slug;
  cfg.canonical=$('#seoCanonical')?.value?.trim()||'';cfg.image_media_id=$('#seoImageMedia')?.value||'';cfg.schema_type=$('#seoSchemaType')?.value||'';cfg.index=$('#seoIndex')?.checked!==false;cfg.follow=$('#seoFollow')?.checked!==false;
  renderSeoPreview(record,cfg);renderSeoAudit();
}

// The Briefing renderer historically called the canonical HTML escape helper
// through this short alias, but the alias was missing from the shipped file.
const esc = escapeHtml;
