function activeEditorPanelName() { return document.querySelector('.panel.active')?.dataset.panel || 'workspace'; }
function renderPanelForTab(tab = activeEditorPanelName(), { force = false } = {}) {
  const name = String(tab || 'workspace');
  if (!force && STATE.renderedPanels?.has(name)) return;
  if (name === 'workspace') renderWorkspace();
  else if (['editorappearance','siteappearance','design'].includes(name)) renderAppearanceEditors();
  else if (name === 'header') renderHeaderMenuEditor();
  else if (name === 'footer') renderGlobalFooterEditor();
  else if (name === 'pagebuilder') { renderCustomPageBuilder(); renderV9EntityRouteEditor(); }
  else if (name === 'services') renderServicesEditor();
  else if (name === 'quote') { renderServicesEditor(); loadQuoteAdmin(); }
  else if (name === 'briefing') renderBriefingEditor();
  else if (name === 'seo') renderSeoEditor();
  else if (name === 'categories') { renderCategories(); renderCollections(); }
  else if (name === 'projects') renderMediaManager();
  else if (name === 'showcases') renderShowcasesEditor();
  else if (name === 'homegrid') renderSiteFilterOrder();
  else if (name === 'categorypages') renderSectionPageEditor();
  else if (name === 'sections') renderSectionComposer();
  else if (name === 'home') renderHomeBlockEditor();
  else if (name === 'hero') { renderHeroMediaSelector(); renderHeroSlides(); renderHeroStoryEditor(); renderHeroGsapScrollEditor(); renderHeroAdvancedEditor(); renderHeroMediaLibrary(); }
  STATE.renderedPanels?.add(name);
}
function renderEditorShellAndActivePanel({ force = false } = {}) {
  const viewport = captureEditorViewport();
  renderWorkspace();
  renderEditorSiteTree();
  renderPanelForTab(activeEditorPanelName(), { force });
  applyEditorWorkspaceContext(activeTreeNavigationButton());
  $('#previewStatus').textContent = STATE.catalog
    ? `${STATE.catalog.stats?.projects || 0} mídias · ${STATE.projectEntities.length} projetos` : 'Aguardando catálogo';
  keepEditorViewportStable(viewport);
}
