function commitPortfolioListEditorDomain(activePanel) {
  if (!['categories','projects'].includes(activePanel)) return;
  $$('[data-folder-title]').forEach((input) => {
    const id = input.dataset.folderTitle;
    const node = STATE.folders.find((item) => item.id === id);
    const visible = document.querySelector(`[data-folder-visible="${CSS.escape(id)}"]`)?.checked !== false;
    if (Number(node?.depth || 0) === 2) {
      STATE.settings.project_sections ||= {};
      STATE.settings.project_sections[id] = { ...projectSectionConfig(id), title: input.value, visible };
    } else {
      STATE.settings.folders[id] = { ...configured(id), title: input.value, visible };
    }
  });
  if (activePanel !== 'projects') return;
  $$('[data-project-title]').forEach((input) => {
    const id = input.dataset.projectTitle;
    const previous = configured(id, 'project');
    STATE.settings.projects[id] = {
      ...previous,
      title: input.value,
      description: document.querySelector(`[data-project-description="${CSS.escape(id)}"]`)?.value || '',
      visible: document.querySelector(`[data-project-visible="${CSS.escape(id)}"]`)?.checked !== false,
      grid_visible: document.querySelector(`[data-project-grid="${CSS.escape(id)}"]`)?.checked !== false,
      featured: Boolean(document.querySelector(`[data-project-featured="${CSS.escape(id)}"]`)?.checked),
      hero: Boolean(document.querySelector(`[data-project-hero="${CSS.escape(id)}"]`)?.checked),
      collection_id: document.querySelector(`[data-project-collection="${CSS.escape(id)}"]`)?.value ?? previous.collection_id ?? '',
      gallery_group: document.querySelector(`[data-project-gallery="${CSS.escape(id)}"]`)?.value?.trim() ?? previous.gallery_group ?? '',
    };
  });
  const entity = selectedProjectEntity();
  if (STATE.renderedPanels?.has('projects') && entity && $('#mmProjectTitle')) {
    if (entity.kind === 'folder-project') {
      STATE.settings.project_sections ||= {};
      STATE.settings.project_sections[entity.drive_id] = {
        ...projectSectionConfig(entity.drive_id),
        title: $('#mmProjectTitle').value,
        description: $('#mmProjectDescription')?.value || '',
        title_size: Math.max(0, Math.min(160, Number($('#mmProjectTitleSize')?.value || 0))),
        description_size: Math.max(0, Math.min(32, Number($('#mmProjectDescriptionSize')?.value || 0))),
        visible: $('#mmProjectVisible')?.checked !== false,
        featured: Boolean($('#mmProjectFeatured')?.checked),
        hero: Boolean($('#mmProjectHero')?.checked),
        cover_ratio: $('#mmCoverRatio')?.value || 'inherit',
        cover_fit: $('#mmCoverFit')?.value || 'cover',
        cover_position_x: Math.max(0, Math.min(100, Number($('#mmCoverPositionX')?.value ?? 50))),
        cover_position_y: Math.max(0, Math.min(100, Number($('#mmCoverPositionY')?.value ?? 50))),
        cover_zoom: Math.max(1, Math.min(2.2, Number($('#mmCoverZoom')?.value ?? 1))),
        cover_bg: $('#mmCoverBg')?.value || '#111111',
        commercial: readProjectCommercialEditor(entity),
      };
    } else {
      STATE.settings.projects[entity.drive_id] = {
        ...mediaConfig(entity.drive_id),
        title: $('#mmProjectTitle').value,
        description: $('#mmProjectDescription')?.value || '',
        title_size: Math.max(0, Math.min(160, Number($('#mmProjectTitleSize')?.value || 0))),
        description_size: Math.max(0, Math.min(32, Number($('#mmProjectDescriptionSize')?.value || 0))),
        visible: $('#mmProjectVisible')?.checked !== false,
        featured: Boolean($('#mmProjectFeatured')?.checked),
        cover_ratio: $('#mmCoverRatio')?.value || 'inherit',
        cover_fit: $('#mmCoverFit')?.value || 'cover',
        cover_position_x: Math.max(0, Math.min(100, Number($('#mmCoverPositionX')?.value ?? 50))),
        cover_position_y: Math.max(0, Math.min(100, Number($('#mmCoverPositionY')?.value ?? 50))),
        cover_zoom: Math.max(1, Math.min(2.2, Number($('#mmCoverZoom')?.value ?? 1))),
        cover_bg: $('#mmCoverBg')?.value || '#111111',
        commercial: readProjectCommercialEditor(entity),
      };
    }
  }
}

function commitActiveEditorDomain(activePanel = activeEditorPanelName()) {
  ensureBuilderState();
  if(activePanel==='categorypages') collectSectionPageFromEditor();
  if (activePanel === 'pagebuilder') { collectCustomPageEditor(); collectV9EntityRouteEditor(); }
  if (activePanel === 'services') collectServicesEditor();
  if (activePanel === 'briefing') collectBriefingEditor();
  if (activePanel === 'immersive') collectImmersiveEditor();
  if (activePanel === 'workspace') commitWorkspaceEditorDomain();
  if (activePanel === 'categories') commitCollectionsEditorDomain();
  if (activePanel === 'header') commitHeaderEditorDomain();
  if (activePanel === 'footer') commitFooterEditorDomain();
  if (activePanel === 'home') commitHomeEditorDomain();
  if (activePanel === 'homegrid') commitHomeGridEditorDomain();
  if (activePanel === 'hero') commitHeroEditorDomain();
  if (activePanel === 'audio') commitAudioEditorDomain();
  if (activePanel === 'design') commitDesignEditorDomain();
  if (['editorappearance','siteappearance'].includes(activePanel)) commitAppearanceEditorDomain(activePanel);
  commitPortfolioListEditorDomain(activePanel);
  STATE.settings.site_builder.site_tree = normalizeSiteTree();
  STATE.workspace = STATE.settings.workspace || STATE.workspace || {};
  return EDITOR_DOMAIN_REGISTRY[activePanel] || 'state-live';
}

function collectSettings() {
  // Stage 5.5: Save commits only the currently edited domain. Hidden/stale DOM
  // from another panel is not allowed to rebuild unrelated canonical state.
  commitActiveEditorDomain(activeEditorPanelName());
  return STATE.settings;
}

function publicTitleInputForDriveName(input) {
  const id = input.dataset.driveName || '';
  const mode = input.dataset.followTitle || '';
  if (mode === 'project') return $('#mmProjectTitle');
  if (mode === 'folder') return document.querySelector(`[data-folder-title="${CSS.escape(id)}"]`);
  if (mode === 'media') return document.querySelector(`[data-project-title="${CSS.escape(id)}"]`);
  return null;
}

function defaultPublicTitle(name, mode) {
  const value = String(name || '');
  return mode === 'media' ? value.replace(/\.[^.]+$/, '') : value;
}

async function applyPhysicalRenames() {
  if (!driveWritable()) return 0;
  const changes = [...document.querySelectorAll('[data-drive-name]')]
    .map((input) => ({ input, id: input.dataset.driveName || '', original: input.dataset.driveOriginal || '', next: input.value.trim(), mode: input.dataset.followTitle || '' }))
    .filter((item) => item.id && item.next && item.next !== item.original && !item.input.disabled);
  if (!changes.length) return 0;

  let applied = 0;
  const seen = new Set();
  for (const change of changes) {
    if (seen.has(change.id)) continue;
    seen.add(change.id);
    const publicInput = publicTitleInputForDriveName(change.input);
    const oldPublicDefault = defaultPublicTitle(change.original, change.mode);
    const shouldFollow = publicInput && (!publicInput.value.trim() || publicInput.value.trim() === oldPublicDefault);
    const payload = await api('/api/drive/item/rename', {
      method: 'POST', body: JSON.stringify({ file_id: change.id, name: change.next }),
    });
    if (payload.catalog) {
      STATE.catalog = payload.catalog;
      flattenCatalog();
    }
    change.input.dataset.driveOriginal = change.next;
    if (shouldFollow && publicInput) publicInput.value = defaultPublicTitle(change.next, change.mode);
    applied += 1;
  }
  return applied;
}


async function reconcileCloudAfterSaveFailure(error, expectedRevision='') {
  const payload=error?.payload||{};
  const target=String(payload.modified_time||payload.revision_status?.saved_revision||expectedRevision||STATE.modified||'').trim();
  if(!target || !payload.local_saved) return null;
  const delays=[0,450,1100,2200,3800];
  let last=null;
  for(const delay of delays){
    if(delay) await new Promise(resolve=>setTimeout(resolve,delay));
    try{
      const recovered=await api('/api/settings/sync-cloud',{method:'POST',body:JSON.stringify({expected_local_revision:target})});
      last=recovered;
      const confirmed=String(recovered.confirmed_revision||recovered.synced_revision||recovered.cloud_revision||recovered.revision_status?.cloud_revision||'').trim();
      if(recovered.cloud_saved===true && confirmed===target){
        return {...payload,...recovered,ok:true,cloud_saved:true,local_saved:true,remote_backend:'github',modified_time:target,
          revision_status:{...(payload.revision_status||{}),...(recovered.revision_status||{}),saved_revision:target,cloud_revision:target}};
      }
      if(recovered.code==='CLOUD_RECOVERY_LOCAL_CHANGED' || recovered.remote_newer===true) break;
    }catch(reconcileError){ last=reconcileError?.payload||last; }
  }
  if(last && typeof last==='object') error.reconcile_payload=last;
  return null;
}

let cloudRecoveryTimer=null;
function scheduleCloudRecovery(expectedRevision=''){
  const target=String(expectedRevision||STATE.modified||'').trim();
  if(!target)return;
  clearTimeout(cloudRecoveryTimer);
  cloudRecoveryTimer=setTimeout(async()=>{
    if(STATE.cloudSaved || String(STATE.modified||'')!==target)return;
    try{
      const recovered=await api('/api/settings/sync-cloud',{method:'POST',body:JSON.stringify({expected_local_revision:target})});
      const confirmed=String(recovered.confirmed_revision||recovered.synced_revision||recovered.cloud_revision||'').trim();
      if(recovered.cloud_saved===true && confirmed===target){
        markSaved({...recovered,modified_time:target,cloud_saved:true,local_saved:true},Number(STATE.editGeneration||0));
        if($('#githubCloudDetail'))$('#githubCloudDetail').textContent=`Estado editorial confirmado · commit ${String(recovered.cloud_commit||STATE.cloudCommit||'—').slice(0,10)}`;
        toast('Nuvem confirmada');
      }
    }catch(_err){}
  },5000);
}

async function performSaveSettings(button, { rerender = true, silent = false } = {}) {
  // R2.2 Stage 8: SAVE is driven by canonical state difference, never by an empty click.
  // GitHub remains authoritative and SUCCESS still requires write + read-back.
  setBusy(button, true);
  let persistedPayload = null;
  try {
    const renamed = await applyPhysicalRenames();
    collectSettings();
    const fingerprint=editorSettingsFingerprint();
    if(!EDITOR_CONFIRMED_FINGERPRINT)resetEditorDirtyBaseline(STATE.settings);
    if(fingerprint!==EDITOR_CONFIRMED_FINGERPRINT&&!STATE.dirty)markEditorDirty({owner:'editor.manual-save',stateKey:'settings',reason:'manual-save'});
    if(!STATE.dirty&&fingerprint===EDITOR_CONFIRMED_FINGERPRINT&&STATE.cloudSaved){
      if(!silent)toast('Nenhuma alteração canônica para salvar.');
      return {ok:true,noop:true,cloud_saved:true,modified_time:STATE.modified,revision_status:{saved_revision:STATE.savedRevision,cloud_revision:STATE.savedRevision,build_revision:STATE.buildRevision,published_revision:STATE.publishedRevision}};
    }
    const saveGeneration = Number(STATE.editGeneration || 0);
    const dirtyScope={owners:[...(STATE.dirtyOwners||[])],state_keys:[...(STATE.dirtyStateKeys||[])],reasons:[...(STATE.dirtyReasons||[])]};
    const outgoingSettings = JSON.parse(JSON.stringify(STATE.settings || {}));
    markSaving();
    const payload = await api('/api/settings', {
      method: 'POST',
      body: JSON.stringify({ settings: outgoingSettings, expected_revision: STATE.modified, dirty_scope:dirtyScope }),
    });
    persistedPayload = payload;
    syncOperationTelemetry(payload);
    const changedWhileSaving = Number(STATE.editGeneration || 0) !== saveGeneration;
    if (!changedWhileSaving) STATE.settings = payload.settings;
    STATE.workspace = STATE.settings.workspace || STATE.workspace || {};
    STATE.modified = payload.modified_time || '';
    const revisions=payload.revision_status||{}; STATE.savedRevision=revisions.saved_revision||STATE.modified; STATE.buildRevision=revisions.build_revision||STATE.buildRevision||''; STATE.publishedRevision=revisions.published_revision||STATE.publishedRevision||'';
    STATE.cloudSaved = Boolean(payload.cloud_saved);
    STATE.cloudSha = payload.cloud_sha || '';
    STATE.cloudCommit = payload.cloud_commit || '';
    STATE.remoteBackend = payload.remote_backend || '';
    STATE.remoteError = payload.remote_error || '';
    STATE.localSaved = Boolean(payload.local_saved);
    STATE.localPath = payload.local_path || '';
    STATE.portableSaved = Boolean(payload.portable_saved);
    STATE.portablePath = payload.portable_path || '';
    STATE.portableError = payload.portable_error || '';
    STATE.cloudGeneration = Number(payload.cloud_generation || STATE.cloudGeneration || 0);
    STATE.lastEditorialChanges = Array.isArray(payload.editorial_changes)?payload.editorial_changes:[];
    STATE.selectionSaveStatus = payload.cloud_saved?'cloud-confirmed':'cloud-pending';
    try{const journalPayload=await api('/api/editorial-journal?limit=30');STATE.editorialJournal=journalPayload.events||[];}catch(_err){}
    if (activeEditorPanelName()==='hero') { renderHeroSlides(); renderHeroSelectedMediaList(); }
    markSaved(payload, saveGeneration);
    if (changedWhileSaving) pendingSaveRequest ||= { button, options: { rerender, silent: true } };
    if (!payload.cloud_saved) throw Object.assign(new Error(payload.message || 'A nuvem não confirmou o Save.'), { payload });
    if ($('#githubCloudDetail')) $('#githubCloudDetail').textContent = STATE.cloudSaved
      ? `Estado editorial sincronizado no GitHub · commit ${STATE.cloudCommit ? STATE.cloudCommit.slice(0, 10) : '—'}`
      : `Save pendente: o cache local existe, mas a nuvem ainda não confirmou esta revisão.`;
    if (payload.conflict_rebased) {
      // Root operations can update settings server-side while the editor is open.
      // The backend has already merged this save over the newest root state.
      renderWorkspace();
      if (!silent) toast('Configurações atualizadas sobre o Workspace atual');
    } else if (!silent) {
      const backendLabel = 'GitHub';
      toast(payload.cloud_saved
        ? (renamed ? `${renamed} nome(s) no Drive · estado salvo na nuvem (${backendLabel})` : `Estado editorial salvo na nuvem (${backendLabel})`)
        : (payload.local_saved ? (payload.portable_saved ? 'Projeto salvo · local + portátil' : 'Projeto salvo localmente') : 'Falha ao salvar localmente'));
    }
    // Saving metadata must not trigger another complete Drive scan.
    // The server already reapplies settings to the current catalog in memory.
    try {
      if (rerender) await loadCatalog();
      else refreshPreview();
    } catch (renderError) {
      console.error('Estado salvo; atualização visual posterior falhou:', renderError);
      STATE.remoteError = `Estado salvo. Atualização da interface pendente: ${renderError.message || renderError}`;
      renderPersistenceFeedback();
      if (!silent) toast('Projeto salvo. Atualize a interface para recarregar a prévia.');
    }
    return payload;
  } catch (error) {
    const recovered = await reconcileCloudAfterSaveFailure(error, persistedPayload?.modified_time || STATE.modified);
    if (recovered) {
      STATE.settings = recovered.settings || STATE.settings;
      STATE.modified = recovered.modified_time || STATE.modified;
      syncOperationTelemetry(recovered);
      markSaved(recovered, Number(STATE.editGeneration || 0));
      if ($('#githubCloudDetail')) $('#githubCloudDetail').textContent = `Estado editorial confirmado por read-back · commit ${String(recovered.cloud_commit||STATE.cloudCommit||'—').slice(0,10)}`;
      if (!silent) toast('Estado editorial confirmado na nuvem por read-back');
      try { if (rerender) await loadCatalog(); else refreshPreview(); } catch (_) { refreshPreview(); }
      return recovered;
    }
    syncOperationTelemetry(error?.payload||{});
    markSaveError(error);
    throw error;
  } finally {
    setBusy(button, false);
  }
}

async function saveSettings(button, options = {}) {
  if(window.STUDIOFRAME_THEME_BROWSER_PREVIEW_ACTIVE){
    themeLibrarySetStatus('PRÉVIA ativa · aplique ou cancele antes de salvar');
    toast('Aplique ou cancele a prévia do tema antes de salvar.');
    return { skipped: true, reason: 'theme-preview-active' };
  }
  // Only one local save request is allowed at a time. Any edit made while that
  // request is running becomes one new request with the newest complete state.
  pendingSaveRequest = { button, options: { rerender: true, silent: false, ...options } };
  if (saveCoordinatorPromise) return saveCoordinatorPromise;
  saveCoordinatorPromise = (async () => {
    let result = null;
    while (pendingSaveRequest) {
      const request = pendingSaveRequest;
      pendingSaveRequest = null;
      result = await performSaveSettings(request.button, request.options);
    }
    return result;
  })();
  try {
    return await saveCoordinatorPromise;
  } catch (error) {
    pendingSaveRequest = null;
    throw error;
  } finally {
    saveCoordinatorPromise = null;
  }
}

function refreshPreview(options = {}) {
  const reason=String(options.reason||'editor-change');
  try { collectSettings(); } catch (error) { console.warn('Não foi possível coletar todos os campos para a prévia:',error); }
  const signature=previewStructuralSignature();
  const structural=options.structural===true || !PREVIEW_LAST_STRUCTURAL_SIGNATURE || signature!==PREVIEW_LAST_STRUCTURAL_SIGNATURE;
  if(structural){ reloadPreviewControlled(reason); return; }
  clearTimeout(PREVIEW_PATCH_TIMER);
  PREVIEW_PATCH_TIMER=setTimeout(()=>{ if(!postPreviewPatch(reason)) reloadPreviewControlled(`${reason}:preview-not-ready`); },Math.max(80,Number(options.debounce??180)));
}

function previewMediaDiagnosticsSnapshot() {
  const frame=$('#previewFrame');
  try {
    const source=frame?.contentWindow?.__STUDIOFRAME_MEDIA_DIAGNOSTICS__;
    if(!source || typeof source!=='object') return {available:false,loaded:0,failed:0,fallback:0,events:[]};
    return {
      available:true,
      loaded:Number(source.loaded||0), failed:Number(source.failed||0), fallback:Number(source.fallback||0),
      events:Array.isArray(source.events)?source.events.slice(-80).map((event)=>({
        at:event?.at||'', id:String(event?.id||''), title:String(event?.title||''), status:String(event?.status||''),
        url:String(event?.url||''), detail:String(event?.detail||''),
      })):[],
    };
  } catch (_) { return {available:false,loaded:0,failed:0,fallback:0,events:[]}; }
}
function diagnosticStatusClass(status='') {
  const value=String(status||'').toLowerCase();
  if(['passed','running','confirmed','published-current','ok','deployed','success'].includes(value)) return 'ok';
  if(['failed','error','unsaved-changes'].includes(value)) return 'error';
  return 'warning';
}
function diagnosticDate(value) {
  if(!value)return '—'; const date=new Date(value); return Number.isNaN(date.getTime())?String(value):date.toLocaleString('pt-BR');
}
function diagnosticDetailsText(details) {
  if(!details || typeof details!=='object')return '';
  const preferred=['message','phase','job_id','commit','changed_count','removed_count','bytes','uploaded_files','reused_files','scope','valid','checked','failures','final_html_preserved'];
  const pairs=[];
  preferred.forEach((key)=>{ if(details[key]!==undefined && details[key]!=='' && details[key]!==null)pairs.push(`${key}=${typeof details[key]==='object'?JSON.stringify(details[key]):details[key]}`); });
  if(!pairs.length){ Object.entries(details).slice(0,5).forEach(([key,value])=>pairs.push(`${key}=${typeof value==='object'?JSON.stringify(value):value}`)); }
  return pairs.join(' · ');
}

function renderDiagnosticHealth(data={},previewMedia={}){
  const root=$('#diagnosticHealthGrid');if(!root)return;
  const liveChecks=Array.isArray(data.health_checks)&&data.health_checks.length?data.health_checks:(Array.isArray(STATE.healthChecks)?STATE.healthChecks:[]);
  if(liveChecks.length){
    root.innerHTML=liveChecks.map((item)=>`<article class="${escapeHtml(diagnosticStatusClass(item.status))}"><span>${escapeHtml(item.label||item.key||'CHECK')}</span><strong>${escapeHtml(String(item.status||'').toUpperCase())}</strong><small>${escapeHtml(item.message||'')}</small><time>${escapeHtml([item.duration_ms!=null?operationDurationLabel(item.duration_ms):'',item.checked_at?diagnosticDate(item.checked_at):''].filter(Boolean).join(' · '))}</time></article>`).join('');
    return;
  }
  const revisions=data.revision_status||{}, scopes=data.validation_scope||{}, github=data.github||{};
  const checks=[
    ['Programa',Boolean(data.app_version),'Versão '+String(data.app_version||'não detectada')],
    ['Credencial Drive',Boolean(data.credential_source||data.credential_fingerprints?.drive),String(data.credential_source||'ausente')],
    ['Drive Auth',Boolean(data.connected),data.connected?String(data.account_email||'autenticado'):'conexão não confirmada'],
    ['Credencial GitHub',Boolean(github.credential_source||data.credential_bootstrap?.github_source||data.credential_fingerprints?.github),String(github.credential_source||data.credential_bootstrap?.github_source||'ausente')],
    ['GitHub Write',Boolean(github.authenticated&&github.can_push!==false),github.message||((github.authenticated&&github.can_push!==false)?'autenticado + escrita':'não confirmado')],
    ['Cloud revision',Boolean(revisions.cloud_revision&&revisions.cloud_matches_saved!==false),revisions.cloud_revision?String(revisions.cloud_revision).slice(0,14):'sem revisão cloud'],
    ['Build',Boolean(revisions.build_revision&&revisions.build_matches_cloud!==false),revisions.build_revision?String(revisions.build_revision).slice(0,14):'sem Build confirmado'],
    ['Preview runtime',Boolean(PREVIEW_READY||previewMedia.available),(PREVIEW_READY||previewMedia.available)?`${previewMedia.loaded||0} mídia(s) ok`:'preview não pronto'],
    ['Publicação real',String(scopes.real_publication?.status||'').toLowerCase()==='passed',String(scopes.real_publication?.status||'não registrada')],
    ['Domínio público',String(scopes.domain_validation?.status||'').toLowerCase()==='passed',String(scopes.domain_validation?.status||'não registrado')],
  ];
  root.innerHTML=checks.map(([label,ok,detail])=>`<article class="${ok?'ok':'warning'}"><span>${escapeHtml(label)}</span><strong>${ok?'OK':'ATENÇÃO'}</strong><small>${escapeHtml(detail||'')}</small></article>`).join('');
}

