  $('#metricGrid').innerHTML = metrics.map(([label, value]) => `<article><span>${label}</span><strong>${escapeHtml(value)}</strong></article>`).join('');

  const revisions=data.revision_status||{}, consistency=data.consistency||{};
  const consistencyRows=[
    ['Editor',revisions.editor_revision||'—',Boolean(revisions.save_matches_editor),'CACHE'],
    ['Cache local',revisions.saved_revision||'—',Boolean(revisions.memory_matches_saved),'LOCAL'],
    ['Nuvem',revisions.cloud_revision||'—',Boolean(revisions.cloud_matches_saved),'CLOUD'],
    ['Build',revisions.build_revision||'—',Boolean(revisions.build_matches_cloud),'BUILD'],
    ['Publicado',revisions.published_revision||'—',Boolean(revisions.published_matches_build),'PUBLIC'],
  ];
  const consistencyNode=$('#diagnosticConsistency');
  if(consistencyNode) consistencyNode.innerHTML=consistencyRows.map(([label,value,match,tag])=>`<div class="diagnostic-kv"><span>${escapeHtml(label)}</span><code>${escapeHtml(value)}</code><b class="${match?'ok':'warning'}">${escapeHtml(tag)} ${match?'OK':'DIVERGE'}</b></div>`).join('');
  const consistencyBadge=$('#diagnosticConsistencyBadge');
  if(consistencyBadge){ const state=String(consistency.status||''); consistencyBadge.textContent=state||'—'; consistencyBadge.className=diagnosticStatusClass(state); }

  const scopeLabels={internal_selftest:'Autoteste interno',local_runtime:'Runtime local',windows_real:'Windows real',real_publication:'Publicação real',domain_validation:'Domínio público'};
  const scopeRoot=$('#diagnosticValidationScope');
  if(scopeRoot){ scopeRoot.innerHTML=Object.entries(data.validation_scope||{}).map(([key,item])=>{ const status=String(item?.status||'not_recorded'); const detail=[item?.note,item?.total!=null?`${item.passed||0}/${item.total||0} testes`:item?.commit?`commit ${item.commit}`:''].filter(Boolean).join(' · '); return `<article class="diagnostic-validation-card ${diagnosticStatusClass(status)}"><span>${escapeHtml(scopeLabels[key]||key)}</span><strong>${escapeHtml(status)}</strong><small>${escapeHtml(detail||'Sem evidência registrada.')}</small></article>`; }).join(''); }

  const mediaRoot=$('#diagnosticMediaSummary');
