  if(mediaRoot){ const mediaMetrics=[['Preview carregadas',previewMedia.loaded||0],['Preview falhas',previewMedia.failed||0],['Fallbacks',previewMedia.fallback||0],['Links públicos válidos',publicValidation.valid??'—'],['Links públicos verificados',publicValidation.checked??'—']]; mediaRoot.innerHTML=mediaMetrics.map(([label,value])=>`<article><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></article>`).join(''); }
  const mediaEvents=$('#diagnosticMediaEvents');
