async function checkPublicationReadiness() {
  const button = $('#publicationReadiness') || $('#checkDrivePublicMedia');
  setBusy(button, true, 'Verificando…');
  try {
    const payload = await api('/api/publication/readiness', { method: 'POST', body: '{}' });
    const status = $('#publicationStatus');
    const access = payload.drive_public_access || {};
    const media = payload.media_validation || {};
    const accessLine = access.ok
      ? 'Drive público: SOMENTE LEITURA ✓'
      : `Drive público: ${access.message || access.code || 'não pronto'}`;
    const mediaLine = media.ok
      ? `Mídias: ${media.valid || 0}/${media.checked || 0} reproduzíveis ✓`
      : `Mídias: ${media.message || `${media.invalid || 0} inválida(s)`}`;
    if (status) {
      const failureLines = (media.failures || []).slice(0, 6).map((item) => `• ${item.name || item.file_id || 'Mídia'}: ${item.reason || item.message || 'indisponível'}`);
      const accessCode = !access.ok && access.code ? `Código Drive: ${access.code}` : '';
      status.textContent = [payload.message, payload.required_action || '', accessLine, accessCode, mediaLine, ...failureLines, payload.ready ? 'Drive + GitHub prontos para publicação gratuita.' : 'Save, editor e preview local continuam disponíveis.'].filter(Boolean).join('\n');
      status.classList.toggle('ok', Boolean(payload.ready));
      status.classList.toggle('error', !payload.ready);
    }
    const mediaStatus = $('#drivePublicMediaStatus');
    if (mediaStatus) {
      mediaStatus.textContent = [accessLine, mediaLine, access.code === 'DRIVE_PUBLIC_WRITE_ACCESS' ? 'BLOQUEADO: acesso público de edição é proibido.' : 'Cloud Run / billing: NÃO UTILIZADOS.'].join('\n');
      mediaStatus.classList.toggle('ok', Boolean(access.ok && media.ok));
      mediaStatus.classList.toggle('error', Boolean(!access.ok || !media.ok));
    }
    writeDiagnosticOutput(payload);
    return payload;
  } finally { setBusy(button, false); }
}


function renderGithubSetupSteps(validation = {}) {
  const steps = Array.isArray(validation.steps) ? validation.steps : [];
  const byKey = new Map(steps.map((item) => [item.key, item]));
  document.querySelectorAll('#githubSetupSteps [data-step]').forEach((node) => {
    const item = byKey.get(node.dataset.step);
    node.classList.remove('ok','fail');
    if (!item) return;
    node.classList.add(item.ok ? 'ok' : 'fail');
    node.title = item.message || '';
  });
}

function openGithubSetupDialog(reason = '') {
  const dialog = $('#githubSetupDialog');
  if (!dialog) return;
  const message = $('#githubSetupMessage');
  if (message && reason) message.textContent = reason;
  if (!dialog.open) dialog.showModal();
  STATE.githubSetupShown = true;
  setTimeout(() => $('#githubSetupToken')?.focus(), 40);
}

function closeGithubSetupDialog() {
  const dialog = $('#githubSetupDialog');
  if (dialog?.open) dialog.close();
}

async function bootstrapGithubConnection({ openOnFailure = true } = {}) {
  try {
    const payload = await api('/api/github/bootstrap', { method: 'POST', body: '{}' });
    renderGithubSetupSteps(payload.validation || {});
    STATE.githubConfigured = true;
    STATE.githubReady = Boolean(payload.cloud_saved);
    STATE.cloudSaved = Boolean(payload.cloud_saved);
    STATE.cloudSha = payload.cloud_sha || '';
    STATE.cloudCommit = payload.cloud_commit || '';
    STATE.remoteBackend = STATE.cloudSaved ? 'github' : '';
    STATE.remoteError = '';
    const message = $('#githubSetupMessage');
    if (message) { message.textContent = payload.message || 'GitHub pronto.'; message.classList.remove('error'); message.classList.add('ok'); }
    await loadGithubStatus({ autoPrompt: false });
    if (STATE.githubReady) closeGithubSetupDialog();
    renderPersistenceFeedback();
    return payload;
  } catch (error) {
    const payload = error?.payload || {};
    renderGithubSetupSteps(payload.validation || {});
    STATE.githubReady = false;
    STATE.remoteError = payload.message || error.message || '';
    const message = $('#githubSetupMessage');
    if (message) {
      message.textContent = [payload.message || error.message, payload.required_action || ''].filter(Boolean).join('\n');
      message.classList.remove('ok'); message.classList.add('error');
    }
    if (openOnFailure) openGithubSetupDialog(payload.message || 'GitHub ainda não está pronto para salvar.');
    throw error;
  }
}

async function ensureGithubReadyForSave({ silent = false } = {}) {
  if (STATE.githubReady && STATE.cloudSaved) return true;
  const status = await loadGithubStatus({ autoPrompt: false }).catch(() => null);
  if (status?.state_exists && status?.authenticated) {
    STATE.githubReady = true;
    STATE.cloudSaved = true;
    return true;
  }
  if (status?.configured && status?.authenticated) {
    try {
      await bootstrapGithubConnection({ openOnFailure: !silent });
      return STATE.githubReady;
    } catch (_error) {
      if (!silent) openGithubSetupDialog('O GitHub está autenticado, mas ainda não conseguiu gravar e reler o estado editorial.');
      return false;
    }
  }
  if (!silent) openGithubSetupDialog('Autorize o GitHub para habilitar sincronização em nuvem e publicação online. Salvar projeto e gerar HTML continuam disponíveis sem GitHub.');
  return false;
}

async function connectGithubWizard() {
  const button = $('#connectGithubWizard');
  const token = $('#githubSetupToken')?.value.trim() || $('#githubToken')?.value.trim() || '';
  if (!token) {
    const message = $('#githubSetupMessage');
    if (message) { message.textContent = 'Cole o token GitHub ou importe um arquivo TXT com o token.'; message.classList.add('error'); }
    return;
  }
  setBusy(button, true, 'Conectando…');
  try {
    const payload = await api('/api/github/configure', { method: 'POST', body: JSON.stringify({ token }) });
    $('#githubSetupToken').value = '';
    if ($('#githubToken')) $('#githubToken').value = '';
    renderGithubSetupSteps(payload.validation || {});
    STATE.githubConfigured = true;
    STATE.githubReady = Boolean(payload.cloud_saved);
    STATE.cloudSaved = Boolean(payload.cloud_saved);
    STATE.cloudSha = payload.cloud_sha || '';
    STATE.cloudCommit = payload.cloud_commit || '';
    STATE.remoteBackend = payload.remote_backend || (STATE.cloudSaved ? 'github' : '');
    STATE.remoteError = '';
    const message = $('#githubSetupMessage');
    if (message) { message.textContent = payload.message; message.classList.remove('error'); message.classList.add('ok'); }
    await loadSettings();
    renderAll();
    refreshPreview();
    await loadGithubStatus({ autoPrompt: false });
    if (STATE.githubReady) closeGithubSetupDialog();
    toast(`GitHub conectado · estado confirmado${STATE.cloudCommit ? ` · ${STATE.cloudCommit.slice(0,10)}` : ''}`);
  } catch (error) {
    const payload = error?.payload || {};
    renderGithubSetupSteps(payload.validation || {});
    STATE.githubConfigured = Boolean(payload.token_saved) || STATE.githubConfigured;
    STATE.githubReady = false;
    const message = $('#githubSetupMessage');
    if (message) {
      message.textContent = [payload.message || error.message, payload.required_action || ''].filter(Boolean).join('\n');
      message.classList.remove('ok'); message.classList.add('error');
    }
    writeDiagnosticOutput(payload);
  } finally {
    setBusy(button, false);
  }
}

async function loadGithubStatus({ autoPrompt = true } = {}) {
  const payload = await api('/api/github/status');
  const topButton = $('#connectGithubTop');
  if (topButton) {
    topButton.textContent = payload.authenticated ? 'GitHub integrado' : (payload.configured ? 'Revalidar GitHub' : 'Conectar GitHub');
    topButton.classList.toggle('credential-ready', Boolean(payload.configured));
    topButton.classList.toggle('credential-online', Boolean(payload.authenticated));
    topButton.title = payload.configured
      ? `Token carregado de ${payload.credential_source || 'fonte configurada'}${payload.credential_fingerprint ? ` · #${payload.credential_fingerprint}` : ''}`
      : 'Nenhum token GitHub foi encontrado.';
  }
  const node = $('#githubStatusText');
  const githubCred = payload.credential_source ? ` · ${payload.credential_source}${payload.credential_fingerprint ? ` #${payload.credential_fingerprint}` : ''}` : '';
  if (node) node.textContent = `${payload.message || (payload.authenticated ? 'GitHub conectado.' : 'GitHub não configurado.')}${githubCred}`;
  const detail = $('#githubCloudDetail');
  if (detail) {
    const writeStatus = payload.can_push === false ? ' · TOKEN SEM ESCRITA' : (payload.can_push === true ? ' · escrita OK' : '');
    const credential = payload.credential_source ? ` · credencial ${payload.credential_source}` : '';
    const pages = payload.pages_accessible === null || payload.pages_accessible === undefined ? ' · Pages: verificado somente ao publicar' : '';
    detail.textContent = payload.state_exists
      ? `Estado cloud: OK · ${payload.state_path} · commit ${String(payload.commit_sha || '').slice(0, 10) || '—'}${writeStatus}${credential}${pages}`
      : `Estado cloud: NÃO EXISTE · ${payload.state_path || 'data/editorial-state.json'}${writeStatus}${credential}${pages}`;
  }
  STATE.githubConfigured = Boolean(payload.configured);
  STATE.githubReady = Boolean(payload.authenticated && payload.can_push !== false);
  STATE.cloudSaved = Boolean(payload.state_exists);
  STATE.cloudSha = payload.state_sha || '';
  STATE.cloudCommit = payload.commit_sha || '';
  STATE.deployment = payload.deployment || STATE.deployment || null;
  if (payload.deployment?.head_sha) STATE.publishCommit = payload.deployment.head_sha;
  if (!STATE.dirty && !STATE.saving) renderPersistenceFeedback();
  if (autoPrompt && !payload.authenticated && !STATE.githubSetupShown && !payload.configured) {
    openGithubSetupDialog('Token GitHub ausente. Importe a credencial para restaurar salvamento e publicação.');
  }
  return payload;
}

async function syncGithubState() {
  const button = $('#syncGithubState');
  setBusy(button, true, 'Sincronizando…');
  try {
    if (STATE.dirty || STATE.saving) throw new Error('Salve as alterações locais antes de recuperar a versão da nuvem.');
    const payload = await api('/api/settings/sync-cloud', { method: 'POST', body: JSON.stringify({ expected_local_revision: STATE.modified }) });
    STATE.settings = payload.settings;
    STATE.modified = payload.modified_time || '';
    STATE.cloudSaved = true;
    STATE.cloudSha = payload.cloud_sha || '';
    STATE.cloudCommit = payload.cloud_commit || '';
    STATE.remoteBackend = payload.remote_backend || '';
    STATE.remoteError = '';
    STATE.dirty = false; STATE.saving = false;
    await loadSettings();
    renderAll();
    refreshPreview();
    await loadGithubStatus();
    toast('Estado editorial recuperado do GitHub');
    return payload;
  } finally { setBusy(button, false); }
}

async function configureGithub() {
  const token = $('#githubToken')?.value.trim() || '';
  if (token && $('#githubSetupToken')) $('#githubSetupToken').value = token;
  openGithubSetupDialog('Validando o token e criando/confirmando data/editorial-state.json…');
  return connectGithubWizard();
}

async function disconnectGithub() {
  const payload = await api('/api/github/disconnect', { method: 'POST', body: '{}' });
  $('#githubStatusText').textContent = payload.message;
  STATE.githubConfigured = false; STATE.githubReady = false; STATE.cloudSaved = false; STATE.cloudSha = ''; STATE.cloudCommit = ''; STATE.dirty = false; renderPersistenceFeedback();
  if ($('#githubCloudDetail')) $('#githubCloudDetail').textContent = 'GitHub desconectado · cache local preservado.';
  toast(payload.message);
}

async function postAction(buttonSelector, path, body = {}) {
  const button = $(buttonSelector);
  setBusy(button, true);
  try {
    const payload = await api(path, { method: 'POST', body: JSON.stringify(body) });
    writeDiagnosticOutput(payload);
    toast(payload.message || 'Concluído');
    return payload;
  } finally {
    setBusy(button, false);
  }
}

function openCredentialDialog() {
  STATE.credential = null;
  $('#credentialFile').value = '';
  const workspace = STATE.settings?.workspace || STATE.workspace || {};
  if ($('#credentialRootId')) $('#credentialRootId').value = workspace.drive_root_id || STATE.status?.workspace_root_id || '';
  $('#credentialSummary').textContent = 'Nenhum arquivo selecionado.';
  $('#credentialProgress').textContent = '';
  $('#configureCredential').disabled = true;
  $('#credentialDialog').showModal();
}

async function readCredentialFile(file) {
  const text = await file.text();
  const parsed = JSON.parse(text);
  if (parsed.type !== 'service_account') throw new Error('O JSON selecionado não é de uma conta de serviço.');
  STATE.credential = parsed;
  $('#credentialSummary').textContent = `${parsed.client_email || 'E-mail ausente'} · projeto ${parsed.project_id || 'não informado'}`;
  $('#configureCredential').disabled = false;
}

async function configureCredential() {
  const button = $('#configureCredential');
  if (!STATE.credential) return;
  setBusy(button, true, 'Validando pasta real…');
  $('#credentialProgress').textContent = 'Autenticando a Service Account e resolvendo a pasta raiz…';
  try {
    const rootId = normalizeDriveFolderId($('#credentialRootId')?.value || STATE.settings?.workspace?.drive_root_id || '');
    const payload = await api('/api/auth/configure', {
      method: 'POST',
      body: JSON.stringify({ credentials: STATE.credential, root_id: rootId, root_name: STATE.settings?.workspace?.drive_root_name || 'Portfólio Aesthetic' }),
    });
    STATE.credential = null;
    $('#credentialProgress').textContent = payload.root_resolution === 'discovered-by-name'
      ? 'Credencial válida. A raiz antiga não estava acessível; uma raiz compatível foi encontrada automaticamente. Lendo o catálogo…'
      : 'Credencial e raiz confirmadas. Lendo pastas e mídias…';
    await loadSettings();
    await loadStatus();
    await synchronize($('#syncDrive'));
    await loadStatus();
    $('#credentialDialog').close();
    toast(`Drive conectado · ${STATE.catalog?.stats?.projects || 0} mídias carregadas`);
  } catch (error) {
    $('#credentialProgress').textContent = error?.message || 'Falha ao conectar ao Google Drive.';
    throw error;
  } finally {
    setBusy(button, false);
  }
}

$('#headerMenuItems')?.addEventListener('click', (event) => {
  const up = event.target.closest('[data-header-menu-up]'); if (up) { moveHeaderMenuItem(up.dataset.headerMenuUp, -1); return; }
  const down = event.target.closest('[data-header-menu-down]'); if (down) { moveHeaderMenuItem(down.dataset.headerMenuDown, 1); return; }
});
$('#headerMenuItems')?.addEventListener('input', () => { collectHeaderMenuFromEditor(); markEditorDirty(); queueAutoSave(); refreshPreview(); });
