function isStudioFrameAndroidRuntime() {
  return /(?:^|\s)StudioFrameAndroid\/7\.5\.12\.2(?:\s|$)/.test(navigator.userAgent || '');
}

async function forceJsonDownload(url, fallbackName) {
  const token=await localToken();
  const target=`${url}${url.includes('?') ? '&' : '?'}t=${Date.now()}`;

  // Android keeps the exact existing server/download contract. The WebView shell
  // only asks the Storage Access Framework for a destination, then downloads the
  // same localhost endpoint with the same X-Portfolio-Token header. Desktop keeps
  // the original Blob + <a download> behavior below.
  if (isStudioFrameAndroidRuntime() && typeof window.prompt === 'function') {
    const absoluteUrl=new URL(target, window.location.href).toString();
    const accepted=window.prompt('STUDIOFRAME_ANDROID_DOWNLOAD', JSON.stringify({
      url:absoluteUrl,
      token,
      name:fallbackName || 'StudioFrame-export.json',
      mime:'application/json'
    }));
    if (accepted === 'accepted') return;
    if (accepted === 'error') throw new Error('O Android não conseguiu preparar o destino da exportação.');
  }

  const response = await fetch(target, { cache: 'no-store', headers:{'X-Portfolio-Token':token} });
  if (!response.ok) {
    let msg=`Falha ao baixar arquivo (HTTP ${response.status})`;
    try { const data=await response.json(); msg=data.message || msg; } catch (_e) {}
    throw new Error(msg);
  }
  const blob=await response.blob();
  const disposition=response.headers.get('Content-Disposition') || '';
  const match=disposition.match(/filename=\"?([^\";]+)\"?/i);
  const name=match?.[1] || fallbackName;
  const href=URL.createObjectURL(blob);
  const a=document.createElement('a'); a.href=href; a.download=name; a.style.display='none';
  document.body.appendChild(a); a.click(); a.remove(); setTimeout(()=>URL.revokeObjectURL(href),1500);
}

