let homeDragId = '';
$('#homeBlockList')?.addEventListener('dragstart', (event) => {
  const row = event.target.closest('.home-block-row');
  if (!row) return;
  homeDragId = row.dataset.homeBlockId;
  row.classList.add('dragging');
  event.dataTransfer.effectAllowed = 'move';
});
$('#homeBlockList')?.addEventListener('dragover', (event) => {
  const row = event.target.closest('.home-block-row');
  if (!row || !homeDragId || row.dataset.homeBlockId === homeDragId) return;
  event.preventDefault();
  [...$('#homeBlockList').querySelectorAll('.home-block-row')].forEach((item) => item.classList.toggle('drag-over', item === row));
});
$('#homeBlockList')?.addEventListener('drop', (event) => {
  const target = event.target.closest('.home-block-row');
  if (!target || !homeDragId || target.dataset.homeBlockId === homeDragId) return;
  event.preventDefault();
  mutateHomeBlocks((blocks) => {
    const from = blocks.findIndex((block) => block.id === homeDragId);
    const to = blocks.findIndex((block) => block.id === target.dataset.homeBlockId);
    if (from < 0 || to < 0) return;
    const [moved] = blocks.splice(from, 1);
    blocks.splice(to, 0, moved);
  });
  homeDragId = '';
});
$('#homeBlockList')?.addEventListener('dragend', () => {
  homeDragId = '';
  [...$('#homeBlockList').querySelectorAll('.home-block-row')].forEach((row) => row.classList.remove('dragging','drag-over'));
});

