$('#heroSlidesList')?.addEventListener('click', (event) => {
  const row = event.target.closest('[data-hero-slide-id]');
  if (!row) return;
  const id = row.dataset.heroSlideId;
  if (event.target.closest('[data-hero-pick-web]')) { openHeroMediaDialog({ mode:'slide', device:'web', slideId:id }); return; }
  if (event.target.closest('[data-hero-pick-mobile]')) { openHeroMediaDialog({ mode:'slide', device:'mobile', slideId:id }); return; }
  if (event.target.closest('[data-hero-slide-remove]')) {
    mutateHeroSlides((slides) => { const i=slides.findIndex((slide)=>slide.id===id); if(i>=0) slides.splice(i,1); }); return;
  }
  if (event.target.closest('[data-hero-slide-duplicate]')) {
    mutateHeroSlides((slides) => { const i=slides.findIndex((slide)=>slide.id===id); if(i>=0) { const clone={...slides[i],id:`hero-slide-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`}; slides.splice(i+1,0,clone); } }); return;
  }
  if (event.target.closest('[data-hero-slide-up]')) {
    mutateHeroSlides((slides) => { const i=slides.findIndex((slide)=>slide.id===id); if(i>0) [slides[i-1],slides[i]]=[slides[i],slides[i-1]]; }); return;
  }
  if (event.target.closest('[data-hero-slide-down]')) {
    mutateHeroSlides((slides) => { const i=slides.findIndex((slide)=>slide.id===id); if(i>=0&&i<slides.length-1) [slides[i+1],slides[i]]=[slides[i],slides[i+1]]; });
  }
});

// Any editorial edit immediately changes the persistent status to PENDENTE.
// V7.12.20 Stage 5.4 / ADR-017: choosing an explicit floating-control
// color is an explicit request for custom presentation. Capture-phase keeps the
// style selector in sync before the generic live-preview collector runs.
const FLOATING_CUSTOM_COLOR_STYLE = {
  floatingWhatsappBackgroundColor:'floatingWhatsappStyle',
  floatingWhatsappForegroundColor:'floatingWhatsappStyle',
  floatingWhatsappBorderColor:'floatingWhatsappStyle',
  servicesQuoteFloatingBackgroundColor:'servicesQuoteFloatingStyle',
  servicesQuoteFloatingForegroundColor:'servicesQuoteFloatingStyle',
  servicesQuoteFloatingBorderColor:'servicesQuoteFloatingStyle',
};
function promoteFloatingColorEditToCustom(event){
  const targetId=event?.target?.id||'';
  const styleId=FLOATING_CUSTOM_COLOR_STYLE[targetId];
  if(!styleId)return;
  const styleNode=$('#'+styleId);
  if(styleNode && styleNode.value!=='custom') styleNode.value='custom';
  const control=targetId.startsWith('floatingWhatsapp')?'whatsapp':(targetId.startsWith('servicesQuote')?'quote':'');
  if(control) commitFloatingControlFromEditor(control);
}
document.addEventListener('input',promoteFloatingColorEditToCustom,true);
document.addEventListener('change',promoteFloatingColorEditToCustom,true);

// Stage 5.5.1 / ADR-022: floating controls own their state immediately.
// Preview/autosave must never wait for a later global DOM collection.
const FLOATING_WHATSAPP_FIELDS=new Set(['floatingWhatsappVisible','floatingWhatsappLabel','floatingWhatsappPosition','floatingWhatsappOffsetX','floatingWhatsappOffsetY','floatingWhatsappSize','floatingWhatsappStyle','floatingWhatsappShape','floatingWhatsappDisplayMode','floatingWhatsappBackgroundColor','floatingWhatsappForegroundColor','floatingWhatsappBorderColor','floatingWhatsappNumber','floatingWhatsappMessage']);
const FLOATING_QUOTE_FIELDS=new Set(['servicesQuoteFloatingVisible','servicesQuoteDockLabel','servicesQuoteFloatingPosition','servicesQuoteFloatingOffsetX','servicesQuoteFloatingOffsetY','servicesQuoteFloatingSize','servicesQuoteFloatingStyle','servicesQuoteFloatingShape','servicesQuoteFloatingBackgroundColor','servicesQuoteFloatingForegroundColor','servicesQuoteFloatingBorderColor','servicesQuoteFloatingShowIcon']);
function commitFloatingControlEvent(event){
  const id=event?.target?.id||'';
  if(FLOATING_WHATSAPP_FIELDS.has(id)) commitFloatingControlFromEditor('whatsapp');
  else if(FLOATING_QUOTE_FIELDS.has(id)) commitFloatingControlFromEditor('quote');
}
document.addEventListener('input',commitFloatingControlEvent,true);
document.addEventListener('change',commitFloatingControlEvent,true);

function shouldTrackCanonicalEditorMutation(node){
  if(!node?.matches?.('input,textarea,select'))return false;
  if(node.id==='githubToken'||node.id==='credentialFile')return false;
  if(node.type==='search')return false;
  if(node.closest?.('#previewDock,.diagnostic-panel,[data-no-save],[data-readonly-surface]'))return false;
  return true;
}
function trackCanonicalEditorMutation(event){
  const node=event.target;if(!shouldTrackCanonicalEditorMutation(node))return;
  queueAutoSave(event);
}
document.addEventListener('input',trackCanonicalEditorMutation);
document.addEventListener('change',trackCanonicalEditorMutation);

// V7.9.6.1 — visual edits patch the loaded preview instead of rebuilding the iframe.
function shouldLivePatchEditorControl(node){
  if(!node?.matches?.('input,textarea,select'))return false;
  if(['githubToken','credentialFile','pagesDomain','serviceCoverSearch','heroMediaSearch','sectionContentSearch'].includes(node.id))return false;
  if(node.closest?.('[data-no-live-preview],.diagnostic-panel'))return false;
  return true;
}
document.addEventListener('input',(event)=>{if(shouldLivePatchEditorControl(event.target))refreshPreview({reason:'input'});});
document.addEventListener('change',(event)=>{if(shouldLivePatchEditorControl(event.target))refreshPreview({reason:'change',debounce:100});});

