async function recoverLatestCloudState(){
  // V7.12.20 Stage 1 — cloud recovery is idempotent. GitHub remains the
  // authoritative source, but the same revision must never be reapplied or
  // cause catalog/preview churn.
  if (STATE.cloudRecoveryActive) return { skipped:true, reason:'recovery-in-flight' };
  const startingRevision = STATE.modified || '';
  const startingGeneration = Number(STATE.editGeneration || 0);
  if (STATE.dirty || STATE.saving) return { skipped:true, reason:'local-edit-active' };
  STATE.cloudRecoveryActive = true;
  try {
    const timeout = new Promise((resolve) => setTimeout(() => resolve(null), 25000));
    const github = await Promise.race([loadGithubStatus({ autoPrompt: false }), timeout]);
    if (github?.configured && github?.authenticated && github?.state_exists) {
      if (STATE.dirty || STATE.saving || Number(STATE.editGeneration || 0) !== startingGeneration || STATE.modified !== startingRevision) {
        console.info('Recuperação automática ignorada: edição local já começou.');
        return { skipped:true, reason:'local-edit-started' };
      }
      const cloud = await Promise.race([
        api('/api/settings/sync-cloud', { method: 'POST', body: JSON.stringify({ expected_local_revision: startingRevision }) }),
        new Promise((_, reject) => setTimeout(() => reject(new Error('timeout GitHub state')), 25000)),
      ]);
      if (Number(STATE.editGeneration || 0) !== startingGeneration) {
        STATE.modified = cloud.modified_time || STATE.modified || '';
        STATE.dirty = true;
        queueAutoSave();
        return { ...cloud, deferred:true, reason:'edited-during-cloud-read' };
      }
      if(cloud.local_newer){
        STATE.cloudSaved=false;
        STATE.remoteError=cloud.message||'A edição local é mais nova que a nuvem.';
        STATE.dirty=true;
        renderPersistenceFeedback();
        queueAutoSave();
        toast('Edição local mais nova preservada · sincronizando com a nuvem');
        return {...cloud,cloud_applied:false,local_newer:true};
      }
      STATE.cloudSaved = true;
      STATE.cloudSha = cloud.cloud_sha || STATE.cloudSha || '';
      STATE.cloudCommit = cloud.cloud_commit || STATE.cloudCommit || '';
      STATE.remoteBackend = 'github';
      const applied = cloud.cloud_applied !== false && Boolean(cloud.cloud_applied || (cloud.modified_time && cloud.modified_time !== startingRevision));
      if (!applied) {
        PREVIEW_METRICS.cloudNoops += 1;
        renderPersistenceFeedback();
        return { ...cloud, cloud_applied:false };
      }
      PREVIEW_METRICS.cloudApplies += 1;
      STATE.settings = cloud.settings || STATE.settings;
      STATE.modified = cloud.modified_time || STATE.modified || '';
      await loadSettings();
      refreshOfficialSiteUI();
      renderPersistenceFeedback();
      toast('Versão editorial mais recente recuperada automaticamente');
      return { ...cloud, cloud_applied:true };
    }
    if (github?.configured && github?.authenticated && !github?.state_exists) {
      bootstrapGithubConnection({ openOnFailure: false }).catch(() => {});
    }
    return { skipped:true, reason:'cloud-state-unavailable' };
  } catch (error) {
    console.warn('Versão remota indisponível; editor continua com o save local:', error);
    return { skipped:true, reason:'cloud-error', error:String(error?.message||error) };
  } finally {
    STATE.cloudRecoveryActive = false;
  }
}

function afterEditorIdle(callback, timeout = 1800) {
  if ('requestIdleCallback' in window) return window.requestIdleCallback(callback, { timeout });
  return setTimeout(callback, Math.min(timeout, 900));
}
function afterEditorPaint() {
  return new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
}

// The editor uses the same playback rule as the public site: user-controlled
// audio/video is exclusive, while muted decorative previews remain visual.
function isEditorManagedMedia(media){return Boolean(media&&['VIDEO','AUDIO'].includes(media.tagName)&&(media.tagName==='AUDIO'||media.controls||!media.muted));}
document.addEventListener('play',(event)=>{
  const active=event.target;if(!isEditorManagedMedia(active))return;
  document.querySelectorAll('video,audio').forEach((media)=>{if(media!==active&&isEditorManagedMedia(media)&&!media.paused){try{media.pause();}catch(_error){}}});
},true);

async function initialize() {
  STATE.activeTreeNodeId = 'site-overview';
  renderPersistenceFeedback();
  await loadSettings();
  // Cloud is the operational source of truth. Resolve it once before the user starts editing.
  // Recovery is idempotent and does not reload the catalog/preview by itself.
  await recoverLatestCloudState();
  await loadCatalog({ render:true, preview:false });
  refreshOfficialSiteUI();
  await afterEditorPaint();
  const status = await loadStatus();
  schedulePreviewRefresh('initial-editor-ready', 650);

  // Cloud recovery already ran before the editor became interactive. Local state is fallback/cache only.
  afterEditorIdle(() => checkPagesDomain().catch(() => {}), 2600);
  afterEditorIdle(() => reconcilePublicationState({ quiet: true }).catch(() => {}), 2800);
  afterEditorIdle(() => refreshOperationTelemetry({ quiet: true }).catch(() => {}), 3000);

  if (status.credential_configured) {
    const cloud = $('#cloudState');
    if (cloud) cloud.querySelector('span').textContent = 'Editor pronto · Drive será atualizado em segundo plano…';
    afterEditorIdle(() => synchronize().then(async (payload) => {
      await loadStatus();
      if (payload?.source === 'drive') toast('Google Drive atualizado automaticamente');
    }).catch((error) => {
      console.error('Sincronização inicial do Drive falhou:', error);
      const cloud = $('#cloudState');
      if (cloud) cloud.querySelector('span').textContent = `Drive não atualizado · ${error.message || 'erro de conexão'}`;
      loadStatus().catch(() => {});
    }), 3400);
  }
}

