// V9.1 Phase 4 · PREVIEW-001 — responsive, movable workspace preview without a second renderer.
// The canonical /preview iframe and live patch pipeline remain authoritative. This layer only
// manages workspace geometry, responsive simulation and safe mobile presentation.
(function initPreviewDockLayout(){
  const body=document.body,
    dock=document.querySelector('#previewDock'),
    resizer=document.querySelector('#previewResizer'),
    closeButton=document.querySelector('#previewClose'),
    topToggle=document.querySelector('#togglePreviewTop'),
    mobileToggle=document.querySelector('#mobileEditorPreview'),
    fullscreenButton=document.querySelector('#previewFullscreen'),
    frame=document.querySelector('#previewFrame'),
    viewport=document.querySelector('#previewViewport'),
    canvas=document.querySelector('#previewCanvas'),
    range=document.querySelector('#previewWidthRange'),
    widthLabel=document.querySelector('#previewWidthLabel'),
    presetSelect=document.querySelector('#previewPreset'),
    refreshNow=document.querySelector('#previewRefreshNow'),
    openWindow=document.querySelector('#previewOpenWindow');
  if(!body||!dock||!frame||!viewport||!canvas)return;

  const OPEN_KEY='studioframe.preview.open',WIDTH_KEY='studioframe.preview.width',DEVICE_KEY='studioframe.preview.device',VIEWPORT_KEY='studioframe.preview.viewportWidth',ZOOM_KEY='studioframe.preview.zoom';
  const PRESETS={desktop:1440,notebook:1280,tablet:768,mobile:390,fluid:0,custom:0};
  const MIN_WIDTH=340,EDITOR_MIN_WIDTH=520;
  const isOverlayMode=()=>true;
  const sidebarGridWidth=()=>window.innerWidth>1440&&!body.classList.contains('sidebar-desktop-hidden')?(document.querySelector('.site-tree-sidebar')?.getBoundingClientRect().width||0):0;
  const MAX_WIDTH=()=>Math.max(MIN_WIDTH,Math.min(900,window.innerWidth-sidebarGridWidth()-EDITOR_MIN_WIDTH));
  let activeDevice=localStorage.getItem(DEVICE_KEY)||'fluid';
  let requestedViewport=Number(localStorage.getItem(VIEWPORT_KEY)||PRESETS[activeDevice]||0);
  let manualZoom=Math.max(0,Number(localStorage.getItem(ZOOM_KEY)||0));
  let lastOverlayMode=isOverlayMode();

  function isOpen(){return !body.classList.contains('preview-collapsed');}
  function updateToggleLabel(){
    const open=isOpen();
    if(topToggle){topToggle.textContent=open?'Ocultar prévia':'Abrir prévia';topToggle.setAttribute('aria-expanded',open?'true':'false');}
    if(mobileToggle){mobileToggle.textContent=open&&isOverlayMode()?'Fechar prévia':'Prévia';mobileToggle.setAttribute('aria-expanded',open?'true':'false');}
    if(fullscreenButton)fullscreenButton.textContent=dock.classList.contains('preview-fullscreen')?'Sair da tela cheia':'Tela cheia';
  }
  function setOpen(open,persist=true){
    const next=!!open;
    body.classList.toggle('preview-collapsed',!next);
    body.classList.toggle('preview-mobile-open',next&&isOverlayMode());
    dock.setAttribute('aria-hidden',next?'false':'true');
    if(!next)dock.classList.remove('preview-fullscreen');
    if(persist&&!isOverlayMode())localStorage.setItem(OPEN_KEY,next?'1':'0');
    updateToggleLabel();
    requestAnimationFrame(fitViewport);
  }
  function setWidth(width,persist=true){
    const safe=Math.round(Math.max(MIN_WIDTH,Math.min(MAX_WIDTH(),Number(width)||560)));
    document.documentElement.style.setProperty('--preview-width',`${safe}px`);
    if(persist)localStorage.setItem(WIDTH_KEY,String(safe));
    requestAnimationFrame(fitViewport);
  }
  function setFullscreen(enabled){
    if(enabled)setOpen(true,false);
    dock.classList.toggle('preview-fullscreen',!!enabled);
    updateToggleLabel();
    requestAnimationFrame(fitViewport);
  }
  function viewportWidth(){
    if(activeDevice==='fluid')return Math.max(320,Math.round(viewport.clientWidth-24));
    return Math.max(320,Number(requestedViewport||PRESETS[activeDevice]||1440));
  }
  function autoScale(cssWidth){return Math.min(1,Math.max(.25,(viewport.clientWidth-24)/Math.max(1,cssWidth)));}
  function fitViewport(){
    const cssWidth=viewportWidth();
    const availableH=Math.max(1,viewport.clientHeight-24);
    const scale=manualZoom>0?Math.max(.25,Math.min(2,manualZoom)):autoScale(cssWidth);
    const cssHeight=Math.max(640,Math.round(availableH/scale));
    frame.dataset.previewDevice=activeDevice;
    frame.style.width=`${cssWidth}px`;
    frame.style.height=`${cssHeight}px`;
    frame.style.transform=`scale(${scale})`;
    canvas.style.width=`${Math.round(cssWidth*scale)}px`;
    canvas.style.height=`${Math.round(cssHeight*scale)}px`;
    canvas.style.setProperty('--preview-scale',String(scale));
    if(widthLabel)widthLabel.textContent=activeDevice==='fluid'?`Livre · ${cssWidth}px`:`${cssWidth}px · ${Math.round(scale*100)}%`;
    if(range){range.value=String(Math.max(320,Math.min(1920,cssWidth)));range.disabled=activeDevice==='fluid';}
    document.querySelectorAll('[data-device]').forEach(b=>b.classList.toggle('active',b.dataset.device===activeDevice));
  }
  function setDevice(device,width=0,persist=true){
    activeDevice=Object.prototype.hasOwnProperty.call(PRESETS,device)?device:'fluid';
    requestedViewport=Number(width||PRESETS[activeDevice]||requestedViewport||1440);
    manualZoom=0;localStorage.removeItem(ZOOM_KEY);
    if(persist){localStorage.setItem(DEVICE_KEY,activeDevice);if(requestedViewport)localStorage.setItem(VIEWPORT_KEY,String(requestedViewport));}
    fitViewport();
  }
  function setManualZoom(value){
    manualZoom=Math.max(.25,Math.min(2,Number(value)||1));
    localStorage.setItem(ZOOM_KEY,String(manualZoom));
    fitViewport();
  }
  function resetView(){
    manualZoom=0;localStorage.removeItem(ZOOM_KEY);
    setDevice('fluid',0,true);setFullscreen(false);fitViewport();
  }

  window.StudioFramePreview={
    setDevice,
    fit:()=>{manualZoom=0;localStorage.removeItem(ZOOM_KEY);fitViewport();},
    getDevice:()=>activeDevice,
    open:()=>setOpen(true),close:()=>setOpen(false),toggle:()=>setOpen(!isOpen()),isOpen,
    setDockWidth:setWidth,
    zoomBy:(delta)=>{const current=manualZoom>0?manualZoom:autoScale(viewportWidth());setManualZoom(current+Number(delta||0));},
    zoom100:()=>setManualZoom(1),
    fullscreen:setFullscreen,
    reset:resetView,
    state:()=>({open:isOpen(),overlay:isOverlayMode(),device:activeDevice,viewportWidth:viewportWidth(),dockWidth:dock.getBoundingClientRect().width,fullscreen:dock.classList.contains('preview-fullscreen'),zoom:manualZoom||0})
  };

  const storedWidth=Number(localStorage.getItem(WIDTH_KEY));
  if(storedWidth)setWidth(storedWidth,false);else setWidth(Math.min(520,MAX_WIDTH()),false);
  const storedOpen=localStorage.getItem(OPEN_KEY);
  // Small screens must never start with a preview covering the editing controls.
  setOpen(false,false);

  topToggle?.addEventListener('click',()=>setOpen(!isOpen()));
  mobileToggle?.addEventListener('click',()=>setOpen(!isOpen(),false));
  closeButton?.addEventListener('click',()=>setOpen(false,!isOverlayMode()));
  fullscreenButton?.addEventListener('click',()=>setFullscreen(!dock.classList.contains('preview-fullscreen')));
  document.querySelectorAll('[data-device]').forEach(button=>button.addEventListener('click',()=>setDevice(button.dataset.device||'fluid',Number(button.dataset.previewWidth||0))));
  range?.addEventListener('input',()=>{activeDevice='custom';requestedViewport=Number(range.value||1440);manualZoom=0;localStorage.removeItem(ZOOM_KEY);localStorage.setItem(DEVICE_KEY,'custom');localStorage.setItem(VIEWPORT_KEY,String(requestedViewport));fitViewport();});
  presetSelect?.addEventListener('change',()=>{const width=Number(presetSelect.value||0);if(!width)return;activeDevice='custom';requestedViewport=width;manualZoom=0;localStorage.removeItem(ZOOM_KEY);localStorage.setItem(DEVICE_KEY,'custom');localStorage.setItem(VIEWPORT_KEY,String(width));fitViewport();presetSelect.value='';});
  refreshNow?.addEventListener('click',()=>reloadPreviewControlled('manual-preview-refresh'));
  openWindow?.addEventListener('click',()=>{const route=previewUrlQuery();const base=previewFrameBaseUrl();const join=base.includes('?')?'&':'?';window.open(`${base}${join}external=1${route}${previewDesiredHash()}`,'studioframe-preview-external','noopener,noreferrer');});

  let dragging=false,startX=0,startWidth=0;
  resizer?.addEventListener('pointerdown',event=>{
    if(dock.classList.contains('preview-fullscreen')||isOverlayMode())return;
    dragging=true;startX=event.clientX;startWidth=dock.getBoundingClientRect().width;
    resizer.setPointerCapture?.(event.pointerId);resizer.classList.add('dragging');body.classList.add('preview-dragging');event.preventDefault();
  });
  resizer?.addEventListener('pointermove',event=>{if(dragging)setWidth(startWidth+(startX-event.clientX),false);});
  const finishResize=event=>{if(!dragging)return;dragging=false;resizer.releasePointerCapture?.(event.pointerId);resizer.classList.remove('dragging');body.classList.remove('preview-dragging');setWidth(dock.getBoundingClientRect().width,true);};
  resizer?.addEventListener('pointerup',finishResize);resizer?.addEventListener('pointercancel',finishResize);

  new ResizeObserver(()=>fitViewport()).observe(viewport);
  window.addEventListener('resize',()=>{
    const overlayNow=isOverlayMode();
    if(overlayNow!==lastOverlayMode){
      // Crossing into compact mode closes the preview instead of allowing it to cover the editor.
      if(overlayNow)setOpen(false,false);
      else setOpen(localStorage.getItem(OPEN_KEY)!=='0',false);
      lastOverlayMode=overlayNow;
    }
    const width=dock.getBoundingClientRect().width;
    if(!overlayNow&&isOpen()&&!dock.classList.contains('preview-fullscreen')&&width>MAX_WIDTH())setWidth(MAX_WIDTH(),false);
    body.classList.toggle('preview-mobile-open',isOpen()&&overlayNow);
    fitViewport();
  });
  document.addEventListener('keydown',event=>{
    if(event.key==='Escape'&&dock.classList.contains('preview-fullscreen')){setFullscreen(false);return;}
    if(event.key==='Escape'&&isOverlayMode()&&isOpen()){setOpen(false,false);}
  });
  setDevice(activeDevice,requestedViewport,false);updateToggleLabel();
})();;


