$('#servicesEditor')?.addEventListener('click',(event)=>{
  const categoryRow=event.target.closest('[data-service-category-id]');if(!categoryRow)return;const categoryId=categoryRow.dataset.serviceCategoryId;
  if(event.target.closest('[data-service-cover-picker]')){openServiceCoverDialog(categoryId);return;}
  if(event.target.closest('[data-service-cover-clear]')){STATE.openServiceCategoryId=categoryId;mutateServiceCategory(categoryId,(categories,index)=>{categories[index].cover_media_id='';});return;}
  if(event.target.closest('[data-service-category-up]')){mutateServiceCategory(categoryId,(categories,index)=>{if(index>0)[categories[index-1],categories[index]]=[categories[index],categories[index-1]];});return;}
  if(event.target.closest('[data-service-category-down]')){mutateServiceCategory(categoryId,(categories,index)=>{if(index<categories.length-1)[categories[index+1],categories[index]]=[categories[index],categories[index+1]];});return;}
  if(event.target.closest('[data-service-category-remove]')){mutateServiceCategory(categoryId,(categories,index)=>categories.splice(index,1));return;}
  if(event.target.closest('[data-service-item-add]')){addServiceItem(categoryId);return;}
  const itemRow=event.target.closest('[data-service-item-id]');if(!itemRow)return;const itemId=itemRow.dataset.serviceItemId;
  if(event.target.closest('[data-service-block-add]')){const type=itemRow.querySelector('[data-service-block-new-type]')?.value||'text';mutateServiceItemBlocks(categoryId,itemId,(blocks,item,category)=>blocks.push(newServiceCommercialBlock(type,item,category)));return;}
  const blockRow=event.target.closest('[data-service-block-id]');if(blockRow){const blockId=blockRow.dataset.serviceBlockId;const relatedRow=event.target.closest('[data-service-related-row]');if(event.target.closest('[data-service-related-add]')){mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const block=blocks.find((value)=>String(value.id)===String(blockId));if(!block)return;block.items=Array.isArray(block.items)?block.items:[];const used=new Set(block.items.map((value)=>String(value.project_id||'')));const candidate=(STATE.projectEntities||[]).map(homeProjectRef).find((value)=>value&&!used.has(String(value)))||'';block.items.push({id:`related-${Date.now().toString(36)}`,project_id:candidate,title:'',description:'',action_label:''});block.visible=true;});return;}if(relatedRow&&event.target.closest('[data-service-related-up]')){const relatedId=relatedRow.dataset.serviceRelatedRow;mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const block=blocks.find((value)=>String(value.id)===String(blockId));const items=Array.isArray(block?.items)?block.items:[];const pos=items.findIndex((value)=>String(value.id)===String(relatedId));if(pos>0)[items[pos-1],items[pos]]=[items[pos],items[pos-1]];});return;}if(relatedRow&&event.target.closest('[data-service-related-down]')){const relatedId=relatedRow.dataset.serviceRelatedRow;mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const block=blocks.find((value)=>String(value.id)===String(blockId));const items=Array.isArray(block?.items)?block.items:[];const pos=items.findIndex((value)=>String(value.id)===String(relatedId));if(pos>=0&&pos<items.length-1)[items[pos+1],items[pos]]=[items[pos],items[pos+1]];});return;}if(relatedRow&&event.target.closest('[data-service-related-remove]')){const relatedId=relatedRow.dataset.serviceRelatedRow;mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const block=blocks.find((value)=>String(value.id)===String(blockId));if(block)block.items=(block.items||[]).filter((value)=>String(value.id)!==String(relatedId));});return;}if(event.target.closest('[data-service-block-up]')){mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const pos=blocks.findIndex((block)=>String(block.id)===String(blockId));if(pos>0)[blocks[pos-1],blocks[pos]]=[blocks[pos],blocks[pos-1]];});return;}if(event.target.closest('[data-service-block-down]')){mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const pos=blocks.findIndex((block)=>String(block.id)===String(blockId));if(pos>=0&&pos<blocks.length-1)[blocks[pos+1],blocks[pos]]=[blocks[pos],blocks[pos+1]];});return;}if(event.target.closest('[data-service-block-duplicate]')){mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const pos=blocks.findIndex((block)=>String(block.id)===String(blockId));if(pos<0)return;const clone=JSON.parse(JSON.stringify(blocks[pos]));clone.id=`service-block-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;clone.label=`${clone.label||SERVICE_COMMERCIAL_BLOCK_TYPES[clone.type]||'Bloco'} · cópia`;blocks.splice(pos+1,0,clone);});return;}if(event.target.closest('[data-service-block-remove]')){mutateServiceItemBlocks(categoryId,itemId,(blocks)=>{const pos=blocks.findIndex((block)=>String(block.id)===String(blockId));if(pos>=0)blocks.splice(pos,1);});return;}}
  if(event.target.closest('[data-service-item-cover-picker]')){openServiceCoverDialog(categoryId,itemId);return;}
  if(event.target.closest('[data-service-item-cover-clear]')){STATE.openServiceCategoryId=categoryId;mutateServiceCategory(categoryId,(categories,index)=>{const item=(categories[index].services||[]).find((value)=>String(value.id)===String(itemId));if(item)item.cover_media_id='';});return;}
  if(event.target.closest('[data-service-item-up]')){mutateServiceCategory(categoryId,(categories,index)=>{const items=categories[index].services||[],position=items.findIndex((item)=>String(item.id)===String(itemId));if(position>0)[items[position-1],items[position]]=[items[position],items[position-1]];items.forEach((item,i)=>item.order=(i+1)*10);});return;}
  if(event.target.closest('[data-service-item-down]')){mutateServiceCategory(categoryId,(categories,index)=>{const items=categories[index].services||[],position=items.findIndex((item)=>String(item.id)===String(itemId));if(position>=0&&position<items.length-1)[items[position+1],items[position]]=[items[position],items[position+1]];items.forEach((item,i)=>item.order=(i+1)*10);});return;}
  if(event.target.closest('[data-service-item-remove]')){mutateServiceCategory(categoryId,(categories,index)=>{categories[index].services=(categories[index].services||[]).filter((item)=>String(item.id)!==String(itemId));});}
});
