// R2.2 Stage 2 · Clean Shell / contextual Inspector.
(function initR22EditorShell(){
  const body=document.body, inspector=$('#editorInspector'), topToggle=$('#toggleInspectorTop'), mobileToggle=$('#mobileEditorInspector'), close=$('#inspectorClose'), scrim=$('#editorShellScrim');
  if(!body||!inspector)return;
  const DESKTOP_KEY='studioframe.inspector.desktopOpen';
  const compact=()=>window.innerWidth<=1180;
  const isOpen=()=>compact()?body.classList.contains('inspector-drawer-open'):!body.classList.contains('inspector-collapsed');
  function syncScrim(){
    const active=body.classList.contains('sidebar-drawer-open')||body.classList.contains('inspector-drawer-open')||body.classList.contains('preview-mobile-open');
    body.classList.toggle('editor-shell-overlay-active',active);
    if(scrim)scrim.tabIndex=active?0:-1;
  }
  function update(){
    const open=isOpen();inspector.setAttribute('aria-hidden',open?'false':'true');
    topToggle?.setAttribute('aria-expanded',open?'true':'false');mobileToggle?.setAttribute('aria-expanded',open?'true':'false');
    if(topToggle){const label=topToggle.querySelector('.topbar-button-label');if(label)label.textContent=open?'Fechar Inspector':'Inspector';}
    if(mobileToggle)mobileToggle.textContent=open?'Fechar Inspector':'Inspector';
    syncScrim();window.StudioFramePreview?.fit?.();
  }
  function setOpen(open,persist=true){
    if(compact()){
      body.classList.remove('inspector-collapsed');body.classList.toggle('inspector-drawer-open',!!open);
      if(open)body.classList.remove('sidebar-drawer-open');
    }else{
      body.classList.remove('inspector-drawer-open');body.classList.toggle('inspector-collapsed',!open);
      if(persist)try{localStorage.setItem(DESKTOP_KEY,open?'1':'0');}catch(_){}
    }
    update();
  }
  function syncMode(){
    if(compact()){body.classList.add('inspector-collapsed');body.classList.remove('inspector-drawer-open');}
    else{body.classList.remove('inspector-drawer-open');let open=true;try{open=localStorage.getItem(DESKTOP_KEY)!=='0';}catch(_){}body.classList.toggle('inspector-collapsed',!open);}
    update();
  }
  topToggle?.addEventListener('click',()=>setOpen(!isOpen()));
  mobileToggle?.addEventListener('click',()=>setOpen(!isOpen(),false));
  close?.addEventListener('click',()=>setOpen(false));
  $('#inspectorFocusPanel')?.addEventListener('click',()=>{document.querySelector('.panel.active')?.scrollIntoView({block:'start',behavior:'smooth'});if(compact())setOpen(false,false);});
  $('#inspectorOpenPreview')?.addEventListener('click',()=>{window.StudioFramePreview?.open?.();if(compact())setOpen(false,false);});
  $('#topbarTest')?.addEventListener('click',()=>openCanonicalTreeNode('v9-diagnostics-overview'));
  scrim?.addEventListener('click',()=>{body.classList.remove('sidebar-drawer-open','inspector-drawer-open');window.StudioFramePreview?.close?.();update();});
  document.addEventListener('keydown',event=>{if(event.key==='Escape'&&body.classList.contains('inspector-drawer-open')){setOpen(false,false);topToggle?.focus();}});
  new MutationObserver(syncScrim).observe(body,{attributes:true,attributeFilter:['class']});
  window.addEventListener('resize',syncMode);
  window.StudioFrameShell={setInspectorOpen:setOpen,isInspectorOpen:isOpen,syncScrim};
  syncMode();updateEditorInspector(canonicalTreeNodeElement(STATE.activeTreeNodeId||'v9-overview'));
})();

// V7.8.0 · the site tree remains readable instead of shrinking with the grid.
(function initResponsiveSidebar(){
  const body=document.body,button=$('#toggleSidebar'),tree=$('#editorSiteTree');
  if(!body||!button||!tree)return;
  const narrow=window.matchMedia('(max-width:1366px)');
  const DESKTOP_KEY='studioframe.sidebar.desktopOpen';
  function desktopOpen(){try{return localStorage.getItem(DESKTOP_KEY)!=='0';}catch(_){return true;}}
  function isOpen(){return narrow.matches?body.classList.contains('sidebar-drawer-open'):!body.classList.contains('sidebar-desktop-hidden');}
  function update(){
    const open=isOpen();button.setAttribute('aria-expanded',open?'true':'false');button.textContent=open?'Fechar árvore':'Abrir árvore';
    button.title=narrow.matches?'Abrir ou recolher a árvore sobre o editor':'Mostrar ou ocultar a árvore sem comprimir o conteúdo';
    window.StudioFramePreview?.fit?.();
    window.StudioFrameShell?.syncScrim?.();
  }
  function syncMode(){
    body.classList.remove('sidebar-drawer-open');
    body.classList.toggle('sidebar-desktop-hidden',!narrow.matches&&!desktopOpen());
    update();
  }
  button.addEventListener('click',()=>{
    if(narrow.matches){const opening=!body.classList.contains('sidebar-drawer-open');body.classList.toggle('sidebar-drawer-open',opening);if(opening)body.classList.remove('inspector-drawer-open');}
    else{
      const open=body.classList.contains('sidebar-desktop-hidden');
      body.classList.toggle('sidebar-desktop-hidden',!open);
      try{localStorage.setItem(DESKTOP_KEY,open?'1':'0');}catch(_){}
    }
    update();
  });
  tree.addEventListener('click',(event)=>{if(narrow.matches&&event.target.closest('button,[data-tab],a')){body.classList.remove('sidebar-drawer-open');update();}});
  document.addEventListener('keydown',(event)=>{if(event.key==='Escape'&&body.classList.contains('sidebar-drawer-open')){body.classList.remove('sidebar-drawer-open');update();button.focus();}});
  body.addEventListener('pointerdown',(event)=>{if(narrow.matches&&event.target===body&&body.classList.contains('sidebar-drawer-open')){body.classList.remove('sidebar-drawer-open');update();}});
  narrow.addEventListener?.('change',syncMode);
  syncMode();
})();
$('#customPageEditor')?.addEventListener('click',(event)=>{const editor=event.target.closest('[data-custom-page-editor-id]');if(!editor)return;const pageId=editor.dataset.customPageEditorId;if(event.target.closest('[data-custom-page-section-add]')){addCustomPageSection(pageId,editor.querySelector('[data-custom-page-section-type]')?.value||'auto_carousel');return;}const row=event.target.closest('[data-custom-page-section-id]');if(!row)return;const blockId=row.dataset.customPageSectionId;if(event.target.closest('[data-custom-page-section-edit]')){STATE.openCustomPageSectionId=STATE.openCustomPageSectionId===blockId?'':blockId;renderCustomPageBuilder();return;}if(event.target.closest('[data-custom-page-section-up]')){reorderCustomPageSection(pageId,blockId,-1);return;}if(event.target.closest('[data-custom-page-section-down]')){reorderCustomPageSection(pageId,blockId,1);return;}if(event.target.closest('[data-custom-page-section-remove]')){removeCustomPageSection(pageId,blockId);return;}if(event.target.closest('[data-custom-page-content-picker]')){collectCustomPageEditor();openSectionContentPicker(blockId,'custom-page');return;}if(event.target.closest('[data-custom-page-item-add]')){collectCustomPageEditor();const found=findCustomPageSection(blockId);found?.block?.items?.push({id:`page-item-${Date.now().toString(36)}`,project_id:'',media_id:'',title:'',description:'',action_label:''});renderCustomPageBuilder();return;}const itemRow=event.target.closest('[data-custom-page-section-item-row]');if(itemRow){collectCustomPageEditor();const found=findCustomPageSection(blockId);if(!found)return;const items=found.block.items||[],itemId=itemRow.dataset.customPageSectionItemRow,i=items.findIndex((it)=>it.id===itemId);if(event.target.closest('[data-custom-page-item-up]')&&i>0)[items[i-1],items[i]]=[items[i],items[i-1]];if(event.target.closest('[data-custom-page-item-down]')&&i>=0&&i<items.length-1)[items[i+1],items[i]]=[items[i],items[i+1]];if(event.target.closest('[data-custom-page-item-remove]')&&i>=0)items.splice(i,1);renderCustomPageBuilder();queueAutoSave();refreshPreview();}});


// V7.12.2 · graceful desktop shutdown. The server answers first, then stops
// itself so Windows releases the extracted application folder cleanly.
$('#shutdownStudioFrame')?.addEventListener('click',async()=>{
  if(!window.confirm('Encerrar o StudioFrame agora?\n\nO servidor local será finalizado e a pasta do programa será liberada.'))return;
  const button=$('#shutdownStudioFrame');if(button){button.disabled=true;button.textContent='Encerrando…';}
  try{
    await api('/api/runtime/shutdown',{method:'POST',body:'{}'});
    document.body.innerHTML='<main class="shutdown-screen"><div><b>STUDIOFRAME ENCERRADO</b><h1>Servidor local finalizado.</h1><p>A pasta do programa foi liberada. Você pode fechar esta aba.</p></div></main>';
  }catch(error){
    if(button){button.disabled=false;button.textContent='Encerrar';}
    showError?.(error);
  }
});


