function splitImageBuilder(){mutateSlicedComposer(block=>{const layers=normalizedSlicedHeroLayers(block),source=layers.find(l=>l.media_id)||layers[1];if(!source?.media_id){toast('Selecione uma imagem em uma layer antes de dividir.');return;}block.sliced_preset='sliced_depth_parallax';block.slice_orientation=block.split_mode||'vertical';block.slice_count=Math.max(2,Math.min(12,Number(block.slice_count||7)));block.slice_depth_mode='auto';block.slice_depth_spread=Math.max(.15,Number(block.slice_depth_spread||.7));block.mouse_parallax=true;block.scroll_parallax=true;layers.forEach((layer,index)=>{if(index<3){layer.media_type='media';layer.media_id=source.media_id;layer.focal_x=source.focal_x??50;layer.focal_y=source.focal_y??50;layer.depth=Math.min(1,(index/(Math.max(1,2)))*block.slice_depth_spread);}});block.layers=layers;});toast('Split Image Builder aplicado · recomposição neutra + depth automático');renderSlicedHeroComposer();}
function bindSlicedComposerCanvasDrag(){const frame=$('#slicedComposerFrame'),block=v789SlicedBlock();if(!frame||!block)return;let doc;try{doc=frame.contentDocument;}catch(_){return;}const layers=normalizedSlicedHeroLayers(block),selected=layers[SLICED_COMPOSER_LAYER_INDEX];if(!selected)return;const node=doc?.querySelector(`[data-sf-sliced-layer-id="${CSS.escape(String(selected.id))}"]`);if(!node)return;node.style.outline='2px solid #72F2A5';node.style.outlineOffset='-2px';node.style.cursor=selected.locked?'not-allowed':'move';if(selected.locked)return;let drag=null;node.addEventListener('pointerdown',event=>{if(event.button!==0)return;drag={startX:event.clientX,startY:event.clientY,x:Number(selected.x||0),y:Number(selected.y||0),fx:Number(selected.focal_x??50),fy:Number(selected.focal_y??50),focal:event.shiftKey};node.setPointerCapture?.(event.pointerId);event.preventDefault();});node.addEventListener('pointermove',event=>{if(!drag)return;const rect=node.getBoundingClientRect(),dx=(event.clientX-drag.startX)/Math.max(1,rect.width)*100,dy=(event.clientY-drag.startY)/Math.max(1,rect.height)*100;if(drag.focal){selected.focal_x=Math.max(0,Math.min(100,drag.fx+dx));selected.focal_y=Math.max(0,Math.min(100,drag.fy+dy));node.style.setProperty('--layer-focal-x',`${selected.focal_x}%`);node.style.setProperty('--layer-focal-y',`${selected.focal_y}%`);}else{selected.x=Math.max(-100,Math.min(100,drag.x+dx));selected.y=Math.max(-100,Math.min(100,drag.y+dy));node.style.setProperty('--layer-x',`${selected.x}%`);node.style.setProperty('--layer-y',`${selected.y}%`);}});const finish=event=>{if(!drag)return;drag=null;try{node.releasePointerCapture?.(event.pointerId);}catch(_){}const current=v789SlicedBlock();if(current){const currentLayers=normalizedSlicedHeroLayers(current);currentLayers[SLICED_COMPOSER_LAYER_INDEX]={...currentLayers[SLICED_COMPOSER_LAYER_INDEX],...selected};current.layers=currentLayers;markEditorDirty();queueAutoSave();refreshPreview({reason:'sliced-canvas-drag'});renderSlicedHeroComposer();}};node.addEventListener('pointerup',finish);node.addEventListener('pointercancel',finish);}
