let PHASE_F_LIBRARY_MODE='sections',PHASE_F_PENDING_TEMPLATE='',PHASE_F_TEMPLATE_ROLLBACK=null;
function phaseFDestinationOptions(current='home'){return composerDestinations().map(d=>`<option value="${escapeHtml(d.id)}" ${d.id===current?'selected':''}>${escapeHtml(d.label)}</option>`).join('')}
function phaseFSectionTypes(){return COMPOSER_SECTION_TYPES.map(type=>homeBlockBrowserMeta(type));}
function phaseFComponentTarget(preset){if(preset.type==='section')return {action:'insert',block:{'section-reveal':'text','section-stagger-grid':'editorial_blocks','section-sticky-features':'section_experience','section-scroll-stack':'section_experience','section-horizontal-gallery':'horizontal_projects','section-case-study-flip':'related_projects','section-bento-reveal':'editorial_blocks','section-timeline':'process','section-infinite-marquee':'marquee','section-cta-cinematic':'cinematic_hero'}[preset.id]||'text'};if(preset.type==='text')return {action:'insert',block:'text_motion'};if(preset.type==='hero')return {action:'owner',panel:'hero'};if(preset.type==='background')return {action:'owner',panel:'background'};if(preset.type==='button')return {action:'owner',panel:'designsystem'};return {action:'owner',panel:'designsystem'};}
function renderStructureLibrary(){const grid=$('#structureLibraryGrid'),summary=$('#structureLibrarySummary'),dest=$('#structureLibraryDestination');if(!grid)return;if(dest){const v=dest.value||'home';dest.innerHTML=phaseFDestinationOptions(v);if([...dest.options].some(o=>o.value===v))dest.value=v;}const q=normalizedBlockBrowserQuery($('#structureLibrarySearch')?.value||'');let rows=[];if(PHASE_F_LIBRARY_MODE==='sections')rows=phaseFSectionTypes().map(x=>({...x,kind:'section',id:x.type}));if(PHASE_F_LIBRARY_MODE==='templates')rows=PHASE_F_TEMPLATES.map(x=>({...x,kind:'template'}));if(PHASE_F_LIBRARY_MODE==='components')rows=PHASE_F_COMPONENT_PRESETS.map(x=>({...x,kind:'component',description:`${x.type} · ${x.motionEngine} · performance ${x.performance}`}));if(PHASE_F_LIBRARY_MODE==='sources')rows=PHASE_F_SOURCE_ADAPTERS.map(x=>({...x,description:`${x.status} · ${x.source_format}`}));rows=rows.filter(x=>!q||normalizedBlockBrowserQuery(`${x.label} ${x.id} ${x.description||''} ${x.type||''}`).includes(q));grid.innerHTML=rows.map(x=>`<article class="structure-library-card" data-library-kind="${escapeHtml(x.kind)}" data-library-id="${escapeHtml(x.id)}"><span class="structure-library-preview preview-${escapeHtml(x.type||x.kind)}"><i></i><i></i><i></i></span><small>${escapeHtml((x.type||x.scope||x.status||x.kind).toUpperCase())}</small><strong>${escapeHtml(x.label||x.id)}</strong><p>${escapeHtml(x.description||'Preset canônico StudioFrame.')}</p><div class="structure-library-tags">${x.performance?`<i>${escapeHtml(x.performance)}</i>`:''}${x.motionEngine?`<i>${escapeHtml(x.motionEngine)}</i>`:''}${x.status?`<i>${escapeHtml(x.status)}</i>`:''}</div><button class="accent" data-library-action type="button">${x.kind==='template'?'Ver DIFF':(x.kind==='component'?'Usar owner/preset':(x.kind==='block'?'Inserir adapter':'Inserir seção'))}</button></article>`).join('')||'<div class="empty">Nenhum item encontrado.</div>';if(summary)summary.innerHTML=`<strong>${rows.length} item(ns)</strong><span>Registry/state paralelo: 0 · destino: ${escapeHtml(composerDestinations().find(d=>d.id===(dest?.value||'home'))?.label||'Home')}</span>`;document.querySelectorAll('[data-structure-mode]').forEach(b=>b.classList.toggle('active',b.dataset.structureMode===PHASE_F_LIBRARY_MODE));}
function openStructureLibrary(mode='sections'){PHASE_F_LIBRARY_MODE=mode;const d=$('#structureLibraryDialog');if(!d)return;$('#structureLibrarySearch').value='';renderStructureLibrary();if(!d.open)d.showModal();}
function phaseFInsertBlock(type,presetId=''){const destination=$('#structureLibraryDestination')?.value||'home',block=newHomeBlock(type);if(!block)return;block.core=false;block.id=`phase-f-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;block.label=HOME_BLOCK_TYPES[type]||type;if(presetId)block.component_preset_id=presetId;const arr=[...composerArray(destination)];arr.push(block);persistComposerArray(destination,arr);STATE.openComposerSectionId=block.id;renderSectionComposer();renderHomeBlockEditor();renderEditorSiteTree();queueAutoSave();refreshPreview();toast(`${block.label} inserido em ${composerDestinations().find(d=>d.id===destination)?.label||destination}`);}
function phaseFOpenOwner(panel){$('#structureLibraryDialog')?.close();if(typeof setPanel==='function')setPanel(panel);else document.querySelector(`[data-tree-tab="${panel}"]`)?.click();toast('Preset encaminhado ao owner canônico; nenhum state paralelo foi criado.');}
function phaseFComponentUse(id){const p=PHASE_F_COMPONENT_PRESETS.find(x=>x.id===id);if(!p)return;const target=phaseFComponentTarget(p);if(target.action==='insert'){phaseFInsertBlock(target.block,p.id);const found=composerSections().find(x=>x.block.component_preset_id===p.id);if(found&&found.block.type==='text_motion')found.block.animation_type=p.id.replace('text-','');}else phaseFOpenOwner(target.panel);}
function phaseFTemplateDiff(id){const t=PHASE_F_TEMPLATES.find(x=>x.id===id);if(!t)return;PHASE_F_PENDING_TEMPLATE=id;const dest=$('#structureLibraryDestination')?.value||'home',label=composerDestinations().find(d=>d.id===dest)?.label||dest;$('#templateDiffTitle').textContent=t.label;$('#templateDiffBody').innerHTML=`<p>${escapeHtml(t.description)}</p><div class="template-diff-grid"><span><b>Destino</b>${escapeHtml(label)}</span><span><b>Adicionar</b>${t.blocks.length} seção(ões)</span><span><b>Remover</b>0</span><span><b>Owner</b>composerArray / persistComposerArray</span></div><ol>${t.blocks.map(type=>`<li>+ ${escapeHtml(HOME_BLOCK_TYPES[type]||type)}</li>`).join('')}</ol><small>Aplicação aditiva. Um snapshot local permite desfazer esta aplicação sem criar editorial state paralelo.</small>`;$('#templateDiffDialog').showModal();}
function phaseFApplyTemplate(){const t=PHASE_F_TEMPLATES.find(x=>x.id===PHASE_F_PENDING_TEMPLATE);if(!t)return;const dest=$('#structureLibraryDestination')?.value||'home',before=[...composerArray(dest)].map(x=>structuredClone(x));PHASE_F_TEMPLATE_ROLLBACK={destination:dest,blocks:before,label:t.label};const arr=[...composerArray(dest)];t.blocks.forEach(type=>{const b=newHomeBlock(type);if(!b)return;b.core=false;b.id=`tpl-f-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;b.template_source_id=t.id;b.label=HOME_BLOCK_TYPES[type]||type;arr.push(b)});persistComposerArray(dest,arr);$('#templateDiffDialog')?.close();$('#structureLibraryDialog')?.close();$('#undoStructureTemplate').disabled=false;renderSectionComposer();renderHomeBlockEditor();renderEditorSiteTree();queueAutoSave();refreshPreview();toast(`${t.label} aplicado de forma aditiva`);}
function phaseFUndoTemplate(){if(!PHASE_F_TEMPLATE_ROLLBACK)return;persistComposerArray(PHASE_F_TEMPLATE_ROLLBACK.destination,PHASE_F_TEMPLATE_ROLLBACK.blocks);toast(`${PHASE_F_TEMPLATE_ROLLBACK.label} desfeito`);PHASE_F_TEMPLATE_ROLLBACK=null;$('#undoStructureTemplate').disabled=true;renderSectionComposer();renderHomeBlockEditor();renderEditorSiteTree();queueAutoSave();refreshPreview();}
$('#openSectionBrowser')?.addEventListener('click',()=>openStructureLibrary('sections'));$('#openTemplateBrowser')?.addEventListener('click',()=>openStructureLibrary('templates'));$('#openComponentBrowser')?.addEventListener('click',()=>openStructureLibrary('components'));$('#structureLibrarySearch')?.addEventListener('input',renderStructureLibrary);$('#structureLibraryDestination')?.addEventListener('change',renderStructureLibrary);document.querySelectorAll('[data-structure-mode]').forEach(b=>b.addEventListener('click',()=>{PHASE_F_LIBRARY_MODE=b.dataset.structureMode;renderStructureLibrary();}));$('#structureLibraryGrid')?.addEventListener('click',e=>{const c=e.target.closest('[data-library-id]');if(!c||!e.target.closest('[data-library-action]'))return;const kind=c.dataset.libraryKind,id=c.dataset.libraryId;if(kind==='section')phaseFInsertBlock(id);else if(kind==='template')phaseFTemplateDiff(id);else if(kind==='component')phaseFComponentUse(id);else{const a=PHASE_F_SOURCE_ADAPTERS.find(x=>x.id===id);if(!a)return;if(a.target==='loop_cards'||a.target==='interactive_folders')phaseFInsertBlock(a.target);else if(a.target==='header-menu')phaseFOpenOwner('header');else if(a.target==='landing-page-reference')phaseFTemplateDiff('landing-page-mockup');else if(a.target==='hero-section-reference')phaseFTemplateDiff('intelligent-creation');else toast(`Source materializado: ${a.label}. Status: ${a.status}. Consulte SOURCE_LIBRARY_MANIFEST.json; nenhum runtime é fingido.`);}});$('#confirmTemplateApply')?.addEventListener('click',phaseFApplyTemplate);$('#undoStructureTemplate')?.addEventListener('click',phaseFUndoTemplate);
